#!/usr/bin/env bash
# =============================================================================
#  FleetPilot 1.0.0
#  Run every Linux host in your datacenter from one place.
#
#  Installs FleetPilot on Debian 12 (Bookworm) or 13 (Trixie):
#  nginx serves it over HTTPS with a self-signed certificate and passes the
#  requests to the app server (Node.js, systemd service fleetpilot), which keeps
#  its data in PostgreSQL. Database, service, backups and certificates are set up
#  by this script; nothing else is downloaded except the Debian packages, with
#  --letsencrypt the acme.sh client and with --update the latest script.
#
#  Usage:
#    sudo bash fleetpilot-install.sh                 Install or update (HTTPS on port 8443)
#    sudo bash fleetpilot-install.sh --port 443      On a different port
#    sudo bash fleetpilot-install.sh --http          Plain HTTP instead of HTTPS
#    sudo bash fleetpilot-install.sh --new-cert      Generate new certificates
#    sudo bash fleetpilot-install.sh --update        Fetch the latest version from GitHub
#    sudo bash fleetpilot-install.sh --uninstall     Remove
#    sudo bash fleetpilot-install.sh --uninstall --purge   Remove including database and backups
#
#  Data (PostgreSQL database fleetpilot on this server, unless --database-url is given):
#    sudo bash fleetpilot-install.sh --backup        Back up now (also daily, the last 14 are kept)
#    sudo bash fleetpilot-install.sh --restore FILE  Restore a backup (the current state is backed up first)
#    sudo bash fleetpilot-install.sh --list-backups  Show the backups in /var/backups/fleetpilot
#    sudo bash fleetpilot-install.sh --database-url postgres://user:pass@host:5432/db
#      Use an existing PostgreSQL server instead of a local one (kept on updates;
#      back to the local database with --local-database)
#    sudo bash fleetpilot-install.sh --no-auto-backup  No daily backup (back on with --auto-backup)
#
#  Let's Encrypt certificate for a domain, checked with a DNS TXT record, so the
#  server needs no open port 80 and may sit in a private network. Works for new and
#  existing installs, updates keep it and it renews itself:
#    sudo CF_Token=... bash fleetpilot-install.sh --letsencrypt app.example.com --dns dns_cf
#      --dns is the acme.sh name of your DNS provider, its credentials are passed as
#      environment variables once: https://github.com/acmesh-official/acme.sh/wiki/dnsapi
#    sudo bash fleetpilot-install.sh --letsencrypt app.example.com --dns manual
#      Without an API: you create the TXT record by hand (renewal by hand, too)
#    --email you@example.com                        Optional contact for Let's Encrypt
#    sudo bash fleetpilot-install.sh --no-letsencrypt   Back to the self-signed certificate
#
#  Moving to another server (e.g. Docker or Kubernetes, see docs/DEPLOYMENT.md):
#    sudo bash fleetpilot-install.sh --moved-to https://fleetpilot.example.com
#      This server keeps running and shows every user a card "FleetPilot has a new
#      address" with a button that carries all their data over in one click.
#    sudo bash fleetpilot-install.sh --not-moved    Remove that card again
#
#  With a Let's Encrypt domain, people who open FleetPilot by IP address (or under
#  another name) get a card offering to move their data to the domain. To never
#  show that card, e.g. behind a reverse proxy where the address would be wrong:
#    sudo bash fleetpilot-install.sh --no-move-card   (kept on updates, back with --move-card)
# =============================================================================
set -euo pipefail

# Made from blueprint 1.1.1 (https://github.com/santiagotoro2023/project-blueprint)
APP_ID="fleetpilot"
APP_NAME="FleetPilot"
APP_VERSION="1.0.0"
APP_PROFILE="server"
APP_PORT="8443"
APP_ROOT="/opt/${APP_ID}"
APP_WWW="${APP_ROOT}/www"
APP_SITE="/etc/nginx/sites-available/${APP_ID}"
APP_LINK="/etc/nginx/sites-enabled/${APP_ID}"
APP_ACTION="install"
APP_EXTRACT_DIR=""
APP_FORCE="no"
APP_PORT_SET="no"
APP_TLS="yes"
APP_TLS_SET="no"
APP_NEW_CERT="no"
APP_TLS_DIR="${APP_ROOT}/tls"
APP_CERT="${APP_TLS_DIR}/${APP_ID}.crt"
APP_KEY="${APP_TLS_DIR}/${APP_ID}.key"
APP_CONF="${APP_ROOT}/${APP_ID}.conf"
APP_SELF="${APP_ROOT}/${APP_ID}-install.sh"
APP_LE_DOMAIN=""
APP_LE_DNS=""
APP_LE_EMAIL=""
APP_LE_SET="no"
APP_MOVED_TO=""
APP_MOVED_SET="no"
APP_MOVE_CARD="yes"
APP_MOVE_CARD_SET="no"
APP_LE_CERT="${APP_TLS_DIR}/letsencrypt.crt"
APP_LE_KEY="${APP_TLS_DIR}/letsencrypt.key"
APP_ACME_HOME="${APP_ROOT}/acme"
APP_ACME_COMMIT="807da6498377ee5e0cf43a78091f46f12dc59a89"   # acme.sh 3.1.6
APP_ACME_SHA256="c7d68b021cfd6380ea83a82962abde5b484779fee0b97d38681dfa1396bbc8d7"
APP_ACME_URL="${APP_ACME_URL:-https://raw.githubusercontent.com/acmesh-official/acme.sh/${APP_ACME_COMMIT}}"
APP_ACME_SERVER="${APP_ACME_SERVER:-letsencrypt}"
APP_RENEW="${APP_ID}-renew"
APP_REPO="santiagotoro2023/fleetpilot"
APP_SCRIPT_URL="https://raw.githubusercontent.com/${APP_REPO}/main/${APP_ID}-install.sh"
APP_USER="${APP_ID}"
APP_SERVICE="${APP_ID}"
APP_BACKEND_PORT="${APP_BACKEND_PORT:-18080}"   # the app server, only on 127.0.0.1
APP_ENV_FILE="${APP_ROOT}/${APP_ID}.env"
APP_BACKUP_DIR="/var/backups/${APP_ID}"
APP_BACKUP_KEEP=14
APP_BACKUP_UNIT="${APP_ID}-backup"
APP_DB_URL=""
APP_DB_SET="no"
APP_AUTO_BACKUP="yes"
APP_AUTO_BACKUP_SET="no"
APP_PURGE="no"
APP_RESTORE_FILE=""
APP_KEY_DIR="/var/lib/${APP_ID}"
APP_KEY_FILE="${APP_KEY_DIR}/${APP_ID}.key"   # encrypts the stored secrets: back it up apart from the database

say()  { printf '\033[1;34m==>\033[0m %s\n' "$*"; }
ok()   { printf '\033[1;32m ✓ \033[0m %s\n' "$*"; }
warn() { printf '\033[1;33m ! \033[0m %s\n' "$*" >&2; }
die()  { printf '\033[1;31m ✗ \033[0m %s\n' "$*" >&2; exit 1; }

usage() {
  awk 'NR > 2 && /^# =====/ { exit } NR > 2' "$0" | sed 's/^# \{0,1\}//'
  exit 0
}
need() { [ -n "${2:-}" ] || die "$1 needs a value (help with --help)"; }

while [ $# -gt 0 ]; do
  case "$1" in
    --port)      need "$1" "${2:-}"; APP_PORT="$2"; APP_PORT_SET="yes"; shift 2 ;;
    --port=*)    APP_PORT="${1#*=}"; APP_PORT_SET="yes"; shift ;;
    --http)      APP_TLS="no"; APP_TLS_SET="yes"; shift ;;
    --https)     APP_TLS="yes"; APP_TLS_SET="yes"; shift ;;
    --new-cert)  APP_NEW_CERT="yes"; shift ;;
    --letsencrypt)   need "$1" "${2:-}"; APP_LE_DOMAIN="$2"; APP_LE_SET="yes"; shift 2 ;;
    --letsencrypt=*) APP_LE_DOMAIN="${1#*=}"; APP_LE_SET="yes"; shift ;;
    --dns)           need "$1" "${2:-}"; APP_LE_DNS="$2"; shift 2 ;;
    --dns=*)         APP_LE_DNS="${1#*=}"; shift ;;
    --email)         need "$1" "${2:-}"; APP_LE_EMAIL="$2"; shift 2 ;;
    --email=*)       APP_LE_EMAIL="${1#*=}"; shift ;;
    --no-letsencrypt) APP_LE_DOMAIN=""; APP_LE_SET="off"; shift ;;
    --moved-to)  need "$1" "${2:-}"; APP_MOVED_TO="$2"; APP_MOVED_SET="yes"; shift 2 ;;
    --moved-to=*) APP_MOVED_TO="${1#*=}"; APP_MOVED_SET="yes"; shift ;;
    --not-moved) APP_MOVED_TO=""; APP_MOVED_SET="off"; shift ;;
    --no-move-card) APP_MOVE_CARD="no"; APP_MOVE_CARD_SET="yes"; shift ;;
    --move-card) APP_MOVE_CARD="yes"; APP_MOVE_CARD_SET="yes"; shift ;;
    --update)    APP_ACTION="update"; shift ;;
    --uninstall) APP_ACTION="uninstall"; shift ;;
    --purge)     APP_PURGE="yes"; shift ;;
    --backup)    APP_ACTION="backup"; shift ;;
    --restore)   need "$1" "${2:-}"; APP_ACTION="restore"; APP_RESTORE_FILE="$2"; shift 2 ;;
    --list-backups) APP_ACTION="list-backups"; shift ;;
    --database-url)   need "$1" "${2:-}"; APP_DB_URL="$2"; APP_DB_SET="yes"; shift 2 ;;
    --database-url=*) APP_DB_URL="${1#*=}"; APP_DB_SET="yes"; shift ;;
    --local-database) APP_DB_URL=""; APP_DB_SET="off"; shift ;;
    --no-auto-backup) APP_AUTO_BACKUP="no"; APP_AUTO_BACKUP_SET="yes"; shift ;;
    --auto-backup)    APP_AUTO_BACKUP="yes"; APP_AUTO_BACKUP_SET="yes"; shift ;;
    --force)     APP_FORCE="yes"; shift ;;
    -h|--help)   usage ;;
    *) die "Unknown option: $1 (help with --help)" ;;
  esac
done
if [ -n "$APP_MOVED_TO" ]; then
  APP_MOVED_TO="${APP_MOVED_TO%/}"
  printf '%s' "$APP_MOVED_TO" | grep -Eq '^https?://[A-Za-z0-9.-]+(:[0-9]{1,5})?$' || die "--moved-to needs an address like https://${APP_ID}.example.com (no path)"
fi
if [ -n "$APP_DB_URL" ]; then
  printf '%s' "$APP_DB_URL" | grep -Eq '^postgres(ql)?://[^[:space:]]+$' || die "--database-url needs a PostgreSQL URL like postgres://user:password@host:5432/${APP_ID}"
fi

case "$APP_PORT" in
  ''|*[!0-9]*) die "Invalid port: ${APP_PORT}" ;;
esac
[ "$APP_PORT" -ge 1 ] && [ "$APP_PORT" -le 65535 ] || die "Port must be between 1 and 65535."


# ------------------------------------------------------------------ App specific (installer/app.sh)
# FleetPilot: additions to the installer (blueprint core in installer/core/).
# This file is pasted into fleetpilot-install.sh between the core's options and its actions.
# Keep it empty unless FleetPilot really needs more; additions are part of the
# installer specification, see .blueprint/spec/04-installer.md.
#
# Optional: runs at the end of every install and update, after nginx was reloaded.
# app_after_install() {
#   ok "Something specific to FleetPilot"
# }

write_files() {
  local W="$1"
  mkdir -p "$W/css"
  cat > "$W/css/app.css" <<'__FLEETPILOT_FILE_END__'
/* FleetPilot: only what this project needs on top of base.css.
   Rules for this file (.blueprint/spec/01-design.md, "Project CSS"):
   - Use the tokens from base.css (var(--panel), var(--line), var(--r-s), …). No new colors,
     no new radii, no new shadows, no new font sizes outside the scale.
   - The signal colors mean the areas of a configuration, as PacketPilot's mean its layers. */
:root {
  --a-system: var(--c-blue);
  --a-network: var(--c-teal);
  --a-access: var(--c-violet);
  --a-services: var(--c-green);
  --a-packages: var(--c-brown);
  --a-storage: var(--c-gold);
  --a-security: var(--c-rust);
  --a-monitoring: var(--c-pink);
  --a-schedules: var(--c-orange);
  --a-files: var(--c-steel);
}
.bg-system { background: var(--a-system); } .bg-network { background: var(--a-network); } .bg-access { background: var(--a-access); }
.bg-services { background: var(--a-services); } .bg-packages { background: var(--a-packages); } .bg-storage { background: var(--a-storage); }
.bg-security { background: var(--a-security); } .bg-monitoring { background: var(--a-monitoring); } .bg-schedules { background: var(--a-schedules); }
.bg-files { background: var(--a-files); }
.ar-system { --area: var(--a-system); } .ar-network { --area: var(--a-network); } .ar-access { --area: var(--a-access); }
.ar-services { --area: var(--a-services); } .ar-packages { --area: var(--a-packages); } .ar-storage { --area: var(--a-storage); }
.ar-security { --area: var(--a-security); } .ar-monitoring { --area: var(--a-monitoring); } .ar-schedules { --area: var(--a-schedules); }
.ar-files { --area: var(--a-files); }

/* ---------- Pages ---------- */
a.btn:not(.primary) { color: var(--ink); }
.page.fp-page-wide { max-width: 1440px; }
.fp-head { display: flex; gap: 16px; align-items: flex-start; flex-wrap: wrap; margin-bottom: 14px; }
.fp-head h1 { margin-bottom: .15em; overflow-wrap: anywhere; }
.fp-head .grow { min-width: 240px; }
.fp-intro { max-width: 80ch; margin-bottom: 0; }
.fp-actions { justify-content: flex-end; }
.fp-crumb { color: var(--ink-2); margin-bottom: 6px; }
.fp-crumb a { color: var(--ink-2); }
.fp-subhead { margin: 2px 0 6px; }
.fp-sec { font-size: 1.1rem; margin: 26px 0 8px; }
.fp-h4 { font-size: .8rem; font-weight: 650; color: var(--ink-2); margin: 14px 0 6px; }
.fp-start { margin: 8px 0 18px; }
.fp-start h2 { font-size: 1.1rem; }
.fp-allgood { max-width: 760px; }
.fp-note { border-left: 3px solid var(--c-blue); background: var(--panel); padding: 8px 12px; border-radius: 0 var(--r-s) var(--r-s) 0; margin: 10px 0; font-size: .9rem; }
.fp-note.fp-danger { border-left-color: var(--err); }
.fp-waitnote { border-left-color: var(--warn); }
.fp-err { color: var(--err); }
.fp-dirty { color: var(--warn); }
.fp-font { font-family: var(--font); font-size: .82rem; }
.fp-toolbar { margin: 12px 0; gap: 8px; }
.fp-find { min-width: 240px; flex: 1 1 260px; max-width: 420px; }
.fp-cols { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 16px; margin-top: 14px; align-items: start; }
.fp-card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-m); padding: 16px 18px; min-width: 0; }
.fp-card h2 { font-size: 1.1rem; }
.fp-kv dd { overflow-wrap: anywhere; }
.fp-notes { white-space: pre-wrap; }
.fp-danger { margin-top: 26px; padding-top: 14px; border-top: 1px solid var(--line); }
.fp-mini { list-style: none; padding: 0; margin: 6px 0; display: grid; gap: 3px; }

/* ---------- States and stripes ---------- */
.fp-state { display: inline-flex; align-items: center; gap: 5px; font-size: .78rem; font-family: var(--font); padding: 1px 8px; border-radius: 99px; border: 1px solid var(--line); background: var(--panel-2); white-space: nowrap; color: var(--ink-2); }
.fp-state::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--ink-3); }
.fp-state.ok { color: var(--ok); border-color: color-mix(in srgb, var(--ok) 40%, var(--line)); }
.fp-state.ok::before { background: var(--ok); }
.fp-state.bad { color: var(--err); border-color: color-mix(in srgb, var(--err) 40%, var(--line)); }
.fp-state.bad::before { background: var(--err); }
.fp-state.wait { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 40%, var(--line)); }
.fp-state.wait::before { background: var(--warn); }
.fp-state.busy { color: var(--focus); border-color: color-mix(in srgb, var(--focus) 40%, var(--line)); }
.fp-state.busy::before { background: var(--focus); animation: fp-pulse 1.2s ease-in-out infinite; }
@keyframes fp-pulse { 50% { opacity: .3; } }
.fp-bands { display: flex; gap: 3px; }
.fp-bands i { width: 26px; height: 6px; border-radius: 3px; display: block; }

/* ---------- Tables, forms, dialogs ---------- */
.fp-tablewrap { overflow-x: auto; max-width: 100%; }
.fp-table { font-family: var(--font); font-size: .86rem; }
.fp-table th { font-size: .8rem; white-space: nowrap; }
.fp-table td { padding: 6px 6px; vertical-align: top; word-break: normal; overflow-wrap: break-word; }
.fp-table td .mono, .fp-table td.mono { word-break: break-all; }
.fp-table td .mono, .fp-table td.mono { font-size: .8rem; }
.page > .tabs.subtabs { margin-bottom: 12px; }
.fp-table tr.fp-sel td { background: color-mix(in srgb, var(--focus) 7%, transparent); }
.fp-table .btn { padding: 3px 8px; font-size: .82rem; }
.fp-actions-cell { white-space: nowrap; text-align: right; }
.fp-form { display: grid; gap: 10px; }
.fp-form h2 { font-size: 1.1rem; margin: 14px 0 0; }
.fp-grid2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.fp-grid3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.fp-help { font-size: .78rem; color: var(--ink-3); }
.fp-check { gap: 8px; color: var(--ink); cursor: pointer; }
.fp-num { width: 110px; }
.fp-area { width: 100%; resize: vertical; }
.fp-fields { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 10px 14px; align-items: start; }
.fp-fields > .fp-wide-field, .fp-fields > .fp-rows, .fp-fields > .fp-check { grid-column: 1 / -1; }
.fp-rows { display: grid; gap: 6px; }
.fp-rows-head { font-size: .82rem; }
.fp-row { grid-template-columns: minmax(0, 1fr) auto !important; align-items: start; }
.fp-row .fp-fields { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
.fp-row-del { align-self: start; }
.fp-row-add { justify-self: start; }
.dlg.fp-wide { width: min(940px, 94vw); }
.dlg h3 { margin-bottom: 12px; }
.fp-dlg-body { display: grid; gap: 10px; max-height: 70vh; overflow: auto; padding: 2px; }
.fp-dlg-body > .tabs { margin-bottom: 4px; }
.fp-steps-preview { margin: 0; padding-left: 22px; display: grid; gap: 3px; }
.fp-reveal { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px; align-items: end; }
.fp-reveal .input { width: 100%; }
.fp-vars { margin-top: 12px; }
.fp-vars > summary { cursor: pointer; color: var(--ink-2); }
.fp-vars .kv { margin-top: 6px; }

/* ---------- Usage bar (subnets) ---------- */
.fp-use { display: flex; align-items: center; gap: 8px; min-width: 150px; }
.fp-use-bar { flex: 1; height: 6px; background: var(--grid); border-radius: 3px; overflow: hidden; min-width: 60px; }
.fp-use-bar i { display: block; height: 100%; background: var(--ok); }
.fp-use-bar i.full { background: var(--warn); }

/* ---------- The host map ---------- */
.fp-map { border: 1px solid var(--line); border-radius: var(--r-m); padding: 16px; min-height: 360px; overflow: auto; }
.fp-zones { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 14px; align-items: start; }
.fp-zone .fp-zones { grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 10px; margin-top: 10px; }
.fp-zone { background: color-mix(in srgb, var(--panel) 88%, transparent); border: 1.5px solid var(--line); border-radius: var(--r-m); padding: 10px; min-width: 0; transition: border-color .12s, box-shadow .12s; }
.fp-zone.fp-site { border-color: var(--grid-strong); background: var(--panel); }
.fp-zone.d1, .fp-zone.d2, .fp-zone.d3 { background: var(--panel-2); }
.fp-zone.fp-loose { border-style: dashed; }
.fp-zone.fp-drop { border-color: var(--focus); box-shadow: var(--shadow); }
.fp-zone-head { display: flex; align-items: center; gap: 6px; margin-bottom: 8px; cursor: default; }
.fp-zone-head[draggable="true"] { cursor: grab; }
.fp-zone-head .btn.icon { padding: 3px; }
.fp-zone-name { font-weight: 650; color: var(--ink); text-decoration: none; }
a.fp-zone-name:hover { text-decoration: underline; }
.fp-zone-meta { font-size: .78rem; color: var(--ink-3); white-space: nowrap; }
.fp-zone-empty { font-size: .82rem; color: var(--ink-3); margin: 4px 0; }
.fp-cards { display: flex; flex-wrap: wrap; gap: 6px; }
.fp-hostcard { display: inline-grid; grid-template-columns: auto auto; grid-template-rows: auto auto; column-gap: 7px; align-items: center; padding: 5px 9px 5px 8px; border: 1.5px solid var(--line);
  border-radius: var(--r-s); background: var(--panel); color: var(--ink); text-decoration: none; max-width: 100%; position: relative; transition: border-color .12s, opacity .12s; }
.fp-hostcard:hover { border-color: var(--focus); }
.fp-hostcard[draggable="true"] { cursor: grab; }
.fp-hostcard .fp-dot { grid-row: 1 / 3; }
.fp-hc-name { font-size: .85rem; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fp-hc-addr { font-family: var(--mono); font-size: .72rem; color: var(--ink-3); grid-column: 2; }
.fp-hc-drift { position: absolute; top: -7px; right: -7px; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 9px; background: var(--warn); color: var(--panel); font-size: .72rem; font-weight: 700; display: grid; place-items: center; }
.fp-hostcard.fp-dim { opacity: .25; }
.fp-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--ink-3); display: inline-block; flex: none; }
.st-managed .fp-dot { background: var(--ok); }
.st-taking_over .fp-dot { background: var(--focus); }
.st-unreachable .fp-dot, .st-failed .fp-dot { background: var(--err); }
.st-new .fp-dot { background: var(--c-mist); }
.st-retired .fp-dot { background: transparent; border: 1.5px solid var(--ink-3); }
.fp-hostcard.st-unreachable, .fp-hostcard.st-failed { border-color: color-mix(in srgb, var(--err) 40%, var(--line)); }
.fp-hostcard.st-retired { opacity: .6; }
.fp-legend { display: inline-flex; flex-wrap: wrap; gap: 12px; color: var(--ink-2); }
.fp-legend > span { display: inline-flex; align-items: center; gap: 5px; }
.fp-maphint { margin-top: 8px; }
.fp-map-empty { display: grid; place-items: center; gap: 8px; min-height: 300px; text-align: center; color: var(--ink-2); }
.fp-bulk { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 8px 10px; margin-bottom: 10px; background: var(--panel); border: 1px solid var(--focus); border-radius: var(--r-s); box-shadow: var(--shadow); position: sticky; top: 8px; z-index: 5; }
.fp-bulk.hidden { display: none; }

/* ---------- A host ---------- */
.fp-drift { border-color: color-mix(in srgb, var(--warn) 50%, var(--line)); margin: 10px 0; }
.fp-diff, .fp-pubkey { margin: 4px 0 0; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-s); padding: 8px 10px; overflow: auto; font: .78rem/1.45 var(--mono); white-space: pre-wrap; word-break: break-all; }
.fp-arealist { border-left: 3px solid var(--area, var(--line)); padding: 2px 0 2px 12px; margin: 10px 0; }
.fp-arealist .fp-h4 { margin-top: 0; }
.fp-setline { display: grid; grid-template-columns: minmax(140px, 220px) minmax(0, 1fr); gap: 10px; padding: 3px 0; font-size: .88rem; }
.fp-yaml pre { max-height: 70vh; min-height: 120px; }
.fp-yaml { height: auto; min-height: 0; }
.fp-keyrow { margin: 10px 0 14px; max-width: 900px; }
.fp-keyrow .btn.icon { padding: 3px; }

/* ---------- IP address map ---------- */
.fp-ipmap { display: grid; grid-template-columns: repeat(auto-fill, minmax(34px, 1fr)); gap: 3px; margin: 12px 0 8px; max-width: 1100px; }
.fp-ip { display: grid; place-items: center; height: 26px; border-radius: 4px; border: 1px solid var(--line); background: var(--panel); font: .7rem var(--mono); color: var(--ink-3); cursor: pointer; padding: 0; }
.fp-legend .fp-ip { display: inline-block; width: 14px; height: 14px; }
.fp-ip:hover { border-color: var(--focus); }
.fp-ip.in-pool { border-bottom: 3px solid color-mix(in srgb, var(--c-blue) 55%, var(--line)); }
.fp-ip.ip-assigned { background: color-mix(in srgb, var(--ok) 22%, var(--panel)); border-color: color-mix(in srgb, var(--ok) 50%, var(--line)); color: var(--ink); }
.fp-ip.ip-reserved { background: color-mix(in srgb, var(--c-violet) 18%, var(--panel)); border-color: color-mix(in srgb, var(--c-violet) 50%, var(--line)); color: var(--ink); }
.fp-ip.ip-discovered { background: color-mix(in srgb, var(--warn) 20%, var(--panel)); border-color: color-mix(in srgb, var(--warn) 50%, var(--line)); color: var(--ink); }
.fp-ip.ip-conflict { background: color-mix(in srgb, var(--err) 22%, var(--panel)); border-color: var(--err); color: var(--ink); }
.fp-ip.ip-gateway { background: var(--ink); border-color: var(--ink); color: var(--panel); cursor: default; }

/* ---------- Automation: tiles, catalog ---------- */
.fp-wf-meta { display: flex; flex-wrap: wrap; gap: 4px 12px; align-items: center; }
.fp-steplist { margin: 0; padding-left: 20px; color: var(--ink-2); }
.tile.fp-off { opacity: .6; }
.fp-areahead { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin: 24px 0 4px; }
.fp-areahead i { width: 26px; height: 6px; border-radius: 3px; }
.fp-areahead h2 { font-size: 1.1rem; margin: 0; }
.fp-catalog .tile { border-top: 3px solid var(--area, var(--line)); }
.fp-kind { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.fp-kindbtn { display: grid; gap: 2px; text-align: left; padding: 10px 12px; border: 1.5px solid var(--line); border-radius: var(--r-s); background: var(--panel); cursor: pointer; color: var(--ink); }
.fp-kindbtn.cur { border-color: var(--focus); box-shadow: inset 0 0 0 1px var(--focus); }

/* ---------- The template editor ---------- */
.fp-tpl-names { max-width: 900px; margin-bottom: 12px; }
.fp-tpl { display: grid; grid-template-columns: minmax(0, 1fr) minmax(320px, 40%); gap: 20px; align-items: start; margin-top: 4px; }
.fp-tpl-side { position: sticky; top: 12px; }
.fp-tpl-side h4 { font-size: .8rem; font-weight: 650; color: var(--ink-2); margin: 14px 0 6px; }
.fp-tpl-side .fp-yaml pre { max-height: calc(100vh - 140px); }
.fp-setting { border-left: 3px solid var(--area, var(--line)); }
.fp-setting > summary { font-size: .92rem; }
.fp-setting .sect-body { display: grid; gap: 10px; padding: 2px 12px 12px; }
.fp-setting .sect-body > p { margin: 0; }
.fp-setting-foot { border-top: 1px solid var(--grid); padding-top: 8px; }
.fp-addmenu { max-height: 460px; overflow: auto; padding: 8px; gap: 2px; }
.fp-addmenu > .input { margin-bottom: 6px; }
.fp-addarea { display: flex; align-items: center; gap: 8px; color: var(--ink-2); font-weight: 650; margin: 10px 4px 2px; }
.fp-addarea i { width: 18px; height: 5px; border-radius: 3px; }
.featitem[class*="ar-"] { border-left: 3px solid var(--area); border-radius: 0 6px 6px 0; }
.fp-assign { align-items: end; margin-top: 12px; }

/* ---------- The workflow editor ---------- */
.fp-wf-sentence { max-width: 900px; background: var(--panel); border: 1px solid var(--line); border-left: 3px solid var(--c-blue); border-radius: 0 var(--r-m) var(--r-m) 0; padding: 10px 14px; margin-bottom: 16px; }
.fp-wf-sentence p { margin: 0; }
.fp-wf-grid { display: grid; grid-template-columns: 300px minmax(0, 1fr) 360px; gap: 18px; align-items: start; }
.fp-wf-how { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-m); padding: 6px 16px 16px; display: grid; gap: 8px; }
.fp-wf-how h4, .fp-wf-steps > h4 { font-size: .8rem; font-weight: 650; color: var(--ink-2); margin: 12px 0 0; }
.fp-wf-how p { margin: 0; }
.fp-wf-how select[multiple] { width: 100%; }
.fp-cron { display: grid; gap: 6px; }
.fp-preset { font-size: .8rem; padding: 2px 8px; }
.fp-stepcards { list-style: none; padding: 0; margin: 8px 0 0; display: grid; gap: 0; counter-reset: step; }
.fp-stepcard { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 12px; align-items: start; background: var(--panel); border: 1.5px solid var(--line); border-left: 4px solid var(--area, var(--line));
  border-radius: var(--r-s); padding: 10px 10px 10px 12px; cursor: pointer; position: relative; margin-bottom: 14px; }
.fp-stepcard:not(:last-child)::after { content: ""; position: absolute; left: 25px; bottom: -15px; width: 2px; height: 14px; background: var(--grid-strong); }
.fp-stepcard:hover { border-color: var(--ink-3); border-left-color: var(--area, var(--ink-3)); }
.fp-stepcard.cur { border-color: var(--select); border-left-color: var(--area, var(--select)); box-shadow: 0 0 0 1px var(--select); }
.fp-stepcard b { font-size: .95rem; }
.fp-stepcard p { margin: 2px 0 0; }
.fp-stepnum { width: 26px; height: 26px; border-radius: 50%; border: 2px solid var(--area, var(--ink)); display: grid; place-items: center; font-weight: 700; font-size: .8rem; flex: none; }
.fp-stepchips { margin-top: 6px; gap: 4px; }
.fp-stepchips:empty { display: none; }
.fp-stepbtns { display: grid; gap: 2px; }
.fp-stepbtns .btn.icon { padding: 3px; }
.fp-wf-side { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-m); position: sticky; top: 12px; max-height: calc(100vh - 24px); display: grid; grid-template-rows: auto minmax(0, 1fr); }
.fp-side-title { font-weight: 650; font-size: 1.02rem; }
.fp-wf-side .fp-fields { grid-template-columns: minmax(0, 1fr); }
.fp-wf-side select[multiple] { width: 100%; }

/* ---------- Runs ---------- */
.fp-runmeta { margin: -4px 0 8px; gap: 6px 12px; }
.fp-matrix th { white-space: normal; vertical-align: bottom; min-width: 90px; border-top: 3px solid var(--area, transparent); }
.fp-matrix th:first-child { min-width: 140px; }
.fp-matrix th.cur { background: color-mix(in srgb, var(--focus) 10%, transparent); }
.fp-thnum { display: inline-grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; border: 1.5px solid var(--area, var(--ink-3)); font-size: .7rem; }
.fp-cell { min-width: 90px; }
.fp-cell .fp-mark { display: inline-flex; vertical-align: middle; }
.fp-cell .fp-mark svg { width: 16px; height: 16px; }
.fp-cellmsg { font-size: .76rem; color: var(--ink-2); margin-left: 4px; }
.fp-cell.st-ok .fp-mark { color: var(--ok); }
.fp-cell.st-changed { background: color-mix(in srgb, var(--ok) 9%, transparent); }
.fp-cell.st-changed .fp-mark { color: var(--ok); }
.fp-cell.st-failed, .fp-cell.st-unreachable { background: color-mix(in srgb, var(--err) 9%, transparent); }
.fp-cell.st-failed .fp-mark, .fp-cell.st-unreachable .fp-mark, .fp-cell.st-failed .fp-cellmsg, .fp-cell.st-unreachable .fp-cellmsg { color: var(--err); }
.fp-cell.st-running { background: color-mix(in srgb, var(--focus) 9%, transparent); }
.fp-cell.st-running .fp-mark { color: var(--focus); animation: fp-pulse 1.2s ease-in-out infinite; }
.fp-cell.st-skipped .fp-mark { color: var(--ink-3); }
.fp-logbar { margin-bottom: 8px; }
.fp-log { height: auto; min-height: 0; }
.fp-log pre { height: 460px; max-height: 70vh; }
.fp-log .lg-ok { color: var(--c-green); }
.fp-log .lg-changed { color: var(--c-gold); }
.fp-log .lg-warn { color: var(--c-orange); }
.fp-log .lg-error { color: var(--c-pink); }
.fp-log .lg-skip { opacity: .6; }
.fp-rolepick { align-items: flex-start; padding: 6px 0; }

/* ---------- Narrow screens ---------- */
@media (max-width: 1280px) {
  .fp-wf-grid { grid-template-columns: 280px minmax(0, 1fr); }
  .fp-wf-side { grid-column: 1 / -1; position: static; max-height: none; }
}
@media (max-width: 1100px) {
  .fp-tpl { grid-template-columns: minmax(0, 1fr); }
  .fp-tpl-side { display: none; }
}
@media (max-width: 860px) {
  .fp-wf-grid { grid-template-columns: minmax(0, 1fr); }
  .fp-grid3 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 760px) {
  .fp-head { gap: 10px; }
  .fp-head h1 { font-size: 1.6rem; }
  .fp-head .grow { min-width: 0; flex-basis: 100%; }
  .fp-actions { justify-content: flex-start; }
  .fp-grid2, .fp-grid3, .fp-kind { grid-template-columns: minmax(0, 1fr); }
  .fp-zones, .fp-zone .fp-zones { grid-template-columns: minmax(0, 1fr); }
  .fp-map { padding: 10px; }
  .fp-find { max-width: none; }
  .fp-setline { grid-template-columns: minmax(0, 1fr); gap: 0; }
  .fp-cols { grid-template-columns: minmax(0, 1fr); }
  .fp-log pre { height: 340px; }
  .cardgrid { grid-template-columns: minmax(0, 1fr); }
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/css"
  cat > "$W/css/base.css" <<'__FLEETPILOT_FILE_END__'
/* ==========================================================================
   Design system: cool paper, dark ink, signal colors.
   Shared by every project in this family, byte for byte. Never edit a copy
   in another project: change it here, then copy it again (docs/DESIGN.md).
   ========================================================================== */

/* ---------- Fonts: shipped with the app, so every system shows the same letters ---------- */
@font-face { font-family: "Cantarell"; src: url("../fonts/cantarell.woff2") format("woff2"); font-weight: 100 800; font-style: normal; font-display: block; }
@font-face { font-family: "DejaVu Sans Mono"; src: url("../fonts/dejavu-sans-mono.woff2") format("woff2"); font-weight: 400; font-style: normal; font-display: block; }
@font-face { font-family: "DejaVu Sans Mono"; src: url("../fonts/dejavu-sans-mono-bold.woff2") format("woff2"); font-weight: 700; font-style: normal; font-display: block; }

/* ---------- Tokens ---------- */
:root {
  --paper: #F3F6FA;
  --grid: #E0E7F0;
  --grid-strong: #CFD9E6;
  --panel: #FFFFFF;
  --panel-2: #F7F9FC;
  --ink: #17253A;
  --ink-2: #4B5B71;
  --ink-3: #7A889B;
  --line: #D3DCE7;
  --focus: #2F6FDB;
  --select: #EE7F1A;
  --ok: #1F9D68;
  --err: #D33A3A;
  --warn: #C98400;
  --btn: #17253A;
  --btn-ink: #FFFFFF;

  /* Signal colors: the same in light and dark mode */
  --c-blue: #2F6FDB;
  --c-violet: #7A5AF8;
  --c-orange: #EE7F1A;
  --c-green: #1F9D68;
  --c-teal: #0E93A8;
  --c-brown: #8B5E3C;
  --c-pink: #D24C8D;
  --c-slate: #94A3B8;
  --c-mist: #B4BFCE;
  --c-steel: #5B6B82;
  --c-gold: #B8920A;
  --c-rust: #B4532A;
  --c-pine: #0F766E;

  --font: "Cantarell", "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  --mono: "DejaVu Sans Mono", ui-monospace, "Cascadia Mono", Menlo, Consolas, monospace;
  --r-s: 6px;
  --r-m: 10px;
  --shadow: 0 1px 2px rgba(23, 37, 58, .08), 0 4px 14px rgba(23, 37, 58, .06);
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --paper: #0E1624; --grid: #172234; --grid-strong: #1F2C41; --panel: #131D2E; --panel-2: #172336;
    --ink: #E4EBF5; --ink-2: #AAB7C9; --ink-3: #7D8BA0; --line: #26354B; --btn: #E4EBF5; --btn-ink: #0E1624;
    --shadow: 0 1px 2px rgba(0,0,0,.3), 0 6px 18px rgba(0,0,0,.25); color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --paper: #0E1624; --grid: #172234; --grid-strong: #1F2C41; --panel: #131D2E; --panel-2: #172336;
  --ink: #E4EBF5; --ink-2: #AAB7C9; --ink-3: #7D8BA0; --line: #26354B; --btn: #E4EBF5; --btn-ink: #0E1624;
  --shadow: 0 1px 2px rgba(0,0,0,.3), 0 6px 18px rgba(0,0,0,.25); color-scheme: dark;
}

/* ---------- Base ---------- */
* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body { font: 15px/1.5 var(--font); color: var(--ink); background: var(--paper); -webkit-font-smoothing: antialiased; }
button, input, select, textarea { font: inherit; color: inherit; }
a { color: var(--focus); }
:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
code, .mono { font-family: var(--mono); font-size: .9em; }
h1, h2, h3 { line-height: 1.2; margin: 0 0 .5em; font-weight: 650; letter-spacing: -.01em; }
h1 { font-size: 2.1rem; } h2 { font-size: 1.45rem; } h3 { font-size: 1.1rem; }
p { margin: 0 0 .8em; }
.muted { color: var(--ink-2); }
.small { font-size: .85rem; }
.hidden { display: none !important; }
.ok-text { color: var(--ok, #1F9D68); }
@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }

/* ---------- Skeleton: icon rail on the left, scrolling main area ---------- */
.app { display: grid; grid-template-columns: 76px 1fr; height: 100vh; }
.rail { background: var(--panel); border-right: 1px solid var(--line); display: flex; flex-direction: column; align-items: stretch; padding: 10px 6px; gap: 4px; }
.rail .logo { display: grid; place-items: center; margin: 4px 0 12px; }
.rail a, .rail button { display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 9px 2px 7px; border-radius: var(--r-m);
  color: var(--ink-2); text-decoration: none; font-size: .72rem; border: 0; background: none; cursor: pointer; }
.rail a:hover, .rail button:hover { background: var(--panel-2); color: var(--ink); }
.rail a.active { background: var(--ink); color: var(--panel); }
.rail .spacer { flex: 1; }
.main { overflow: auto; position: relative; min-width: 0; }
.page { max-width: 1080px; margin: 0 auto; padding: 32px 28px 64px; }

/* ---------- Controls ---------- */
.btn { text-decoration: none; display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--line); background: var(--panel); border-radius: var(--r-s);
  padding: 6px 12px; cursor: pointer; line-height: 1.3; white-space: nowrap; }
.btn:hover { border-color: var(--ink-3); }
.btn.primary { background: var(--btn); color: var(--btn-ink); border-color: var(--btn); }
.btn.primary:hover { opacity: .9; }
.btn.ghost { border-color: transparent; background: transparent; }
.btn.icon { padding: 6px; }
.btn.danger { color: var(--err); }
.btn.danger-soft { color: var(--err); border-color: color-mix(in srgb, var(--err) 45%, var(--line)); }
.btn[disabled] { opacity: .45; cursor: not-allowed; }
.btn.on { border-color: var(--select); color: var(--select); box-shadow: inset 0 0 0 1px var(--select); }
.btn.icon.on { color: var(--accent, var(--ink)); }
.input, select.input { border: 1px solid var(--line); background: var(--panel); border-radius: var(--r-s); padding: 5px 8px; min-width: 0; }
.input:focus { border-color: var(--focus); outline: none; box-shadow: 0 0 0 3px color-mix(in srgb, var(--focus) 20%, transparent); }
.input.mono { font-family: var(--mono); font-size: .85rem; }
.input.bad { border-color: var(--err); }
.field { display: grid; gap: 3px; font-size: .82rem; color: var(--ink-2); }
.field > .input { color: var(--ink); font-size: .9rem; }
.row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.grow { flex: 1; }
.chip { display: inline-flex; align-items: center; gap: 4px; padding: 1px 8px; border-radius: 99px; font-size: .78rem; background: var(--panel-2); border: 1px solid var(--line); }
.chip.on { color: var(--ok); border-color: color-mix(in srgb, var(--ok) 45%, var(--line)); }
.toast { position: fixed; bottom: 22px; left: 50%; transform: translateX(-50%); background: var(--ink); color: var(--panel); padding: 9px 16px; border-radius: var(--r-m);
  box-shadow: var(--shadow); z-index: 50; font-size: .9rem; }
.linkbtn { border: 0; background: none; padding: 4px 0; color: var(--ink-2); cursor: pointer; text-decoration: underline dotted; }
.linkbtn:hover { color: var(--ink); }
.feedback { margin-top: 10px; font-weight: 600; }
.feedback.ok { color: var(--ok); } .feedback.bad { color: var(--err); }

/* ---------- Home page: hero, numbered sections, tiles ---------- */
.hero { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); gap: 32px; align-items: center; padding: 8px 0 28px; }
.hero h1 { font-size: 3rem; letter-spacing: -.03em; margin-bottom: .2em; }
.hero p { font-size: 1.08rem; color: var(--ink-2); max-width: 46ch; }
.hero-visual { height: 280px; border: 1px solid var(--line); border-radius: var(--r-m); overflow: hidden; background: var(--paper); position: relative; }
.hero-visual .caption { position: absolute; left: 12px; bottom: 10px; font-size: .78rem; color: var(--ink-2); background: color-mix(in srgb, var(--panel) 85%, transparent); padding: 3px 8px; border-radius: 99px; }
.modules { display: grid; gap: 18px; margin-top: 12px; }
.module { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-m); padding: 20px 22px; display: grid; grid-template-columns: 56px 1fr; gap: 16px; }
.module .num { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; font-weight: 700; font-size: 1.1rem; border: 2px solid var(--ink); }
.module.done .num { background: var(--ink); color: var(--panel); }
.module h2 { margin-bottom: .2em; }
.module .bands { display: flex; gap: 3px; margin: 2px 0 10px; }
.module .bands i { width: 26px; height: 6px; border-radius: 3px; display: block; }
.lessons { list-style: none; padding: 0; margin: 10px 0 0; display: grid; gap: 2px; }
.lessons a { display: grid; grid-template-columns: 22px 1fr auto; gap: 10px; align-items: center; padding: 7px 10px; border-radius: var(--r-s); color: var(--ink); text-decoration: none; }
.lessons a:hover { background: var(--panel-2); }
.lessons .st { color: var(--ink-3); display: grid; place-items: center; }
.lessons .st.ok { color: var(--ok); }
.lessons .meta { font-size: .8rem; color: var(--ink-3); }
.progressbar { height: 6px; background: var(--grid); border-radius: 3px; overflow: hidden; }
.progressbar > i { display: block; height: 100%; background: var(--ok); }
.cardgrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 16px; margin-top: 16px; }
.tile { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-m); padding: 16px; display: grid; gap: 8px; align-content: start; }
.tile h3 { margin: 4px 0 0; }
a.tile { color: inherit; text-decoration: none; transition: border-color .12s, box-shadow .12s; }
a.tile:hover { border-color: var(--focus); box-shadow: var(--shadow); }
.tile.done { border-color: color-mix(in srgb, var(--ok) 45%, var(--line)); }
.tile .st.ok { color: var(--ok); display: inline-flex; }
.pico { display: inline-flex; color: var(--focus); }
.lvl { display: inline-flex; gap: 3px; flex: none; }
.lvl i { width: 7px; height: 7px; border-radius: 50%; background: var(--line); }
.lvl i.on { background: var(--c-orange); }
.subcard { max-width: 760px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-m); padding: 16px 18px; }
.databox { margin-top: 32px; padding: 18px 20px; border: 1px solid var(--line); border-radius: var(--r-m, 12px); background: var(--panel); }
.databox h2 { margin-top: 0; }
.databox p { margin: 4px 0; max-width: 80ch; }
.databox .stat b { font-size: 1.1rem; }

/* ---------- Step page: top bar, body, bottom bar ---------- */
.lesson { display: grid; grid-template-rows: auto 1fr auto; height: 100vh; }
.lesson-top { display: flex; align-items: center; gap: 14px; padding: 12px 20px; border-bottom: 1px solid var(--line); background: var(--panel); }
.lesson-top .crumb { color: var(--ink-2); font-size: .85rem; }
.lesson-top h1 { font-size: 1.15rem; margin: 0; }
.steps { display: flex; gap: 6px; margin-left: auto; }
.steps button { width: 26px; height: 26px; border-radius: 50%; border: 2px solid var(--line); background: var(--panel); cursor: pointer; font-size: .75rem; color: var(--ink-2); display: grid; place-items: center; padding: 0; }
.steps button.cur { border-color: var(--ink); color: var(--ink); font-weight: 700; }
.steps button.ok { background: var(--ok); border-color: var(--ok); color: #fff; }
.lesson-body { overflow: auto; min-height: 0; }
.lesson-body.is-lab { position: relative; overflow: hidden; display: grid; grid-template-columns: var(--goal-w, 340px) minmax(0, 1fr); }
.lesson-nav { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 10px 20px; border-top: 1px solid var(--line); background: var(--panel); }
.chtimer { display: inline-flex; align-items: center; gap: 6px; margin-left: auto; font-family: var(--mono); font-size: .9rem; color: var(--ink-2); }

/* ---------- Reading text ---------- */
.theory { max-width: 760px; margin: 0 auto; padding: 30px 28px 48px; }
.theory p, .theory li { max-width: 70ch; }
.theory h2 { margin-top: 1.3em; }
.theory .note { border-left: 3px solid var(--c-blue); background: var(--panel); padding: 10px 14px; border-radius: 0 var(--r-s) var(--r-s) 0; margin: 14px 0; }
.theory .note.warn { border-color: var(--warn); }
.theory table { border-collapse: collapse; margin: 12px 0 18px; width: 100%; font-size: .92rem; background: var(--panel); }
.theory th, .theory td { border: 1px solid var(--line); padding: 6px 10px; text-align: left; vertical-align: top; }
.theory th { background: var(--panel-2); font-weight: 600; }
.theory pre { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-s); padding: 10px 12px; overflow: auto; font: .82rem/1.45 var(--mono); }

/* ---------- Task column: goals with checkmarks, hints ---------- */
.goalcol { border-right: 1px solid var(--line); background: var(--panel); overflow: auto; padding: 18px 18px 24px; }
.goalcol h2 { font-size: 1.15rem; }
.goals { list-style: none; padding: 0; margin: 12px 0; display: grid; gap: 8px; }
.goals li { display: grid; grid-template-columns: 22px 1fr; gap: 8px; align-items: start; font-size: .92rem; }
.goals li .st { color: var(--ink-3); margin-top: 1px; }
.goals li.ok .st { color: var(--ok); }
.goals li.ok .txt { color: var(--ink-2); }
.goals .ask { display: grid; gap: 4px; margin-top: 4px; }
.hint { margin-top: 10px; font-size: .88rem; background: var(--panel-2); border: 1px dashed var(--line); padding: 8px 10px; border-radius: var(--r-s); }
.done-banner { margin-top: 12px; padding: 10px 12px; border-radius: var(--r-s); background: color-mix(in srgb, var(--ok) 14%, var(--panel)); border: 1px solid color-mix(in srgb, var(--ok) 45%, transparent); font-weight: 600; }

/* ---------- Exercises ---------- */
.widget { max-width: 860px; margin: 0 auto; padding: 30px 28px 48px; }
.quiz-q { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-m); padding: 16px 18px; margin-bottom: 14px; }
.quiz-q .opts { display: grid; gap: 6px; margin-top: 10px; }
.quiz-q label { display: flex; gap: 10px; align-items: flex-start; padding: 7px 10px; border: 1px solid var(--line); border-radius: var(--r-s); cursor: pointer; }
.quiz-q label:hover { border-color: var(--ink-3); }
.quiz-q label.right { border-color: var(--ok); background: color-mix(in srgb, var(--ok) 10%, var(--panel)); }
.quiz-q label.wrong { border-color: var(--err); background: color-mix(in srgb, var(--err) 8%, var(--panel)); }
.quiz-q .explain { margin-top: 10px; font-size: .9rem; color: var(--ink-2); }
.quiz-q input[type=text] { width: 160px; }

/* ---------- Data: tables, key/value lists, lists of items, terminal ---------- */
.rtable { border-collapse: collapse; font-family: var(--mono); font-size: .85rem; background: var(--panel); }
.rtable td, .rtable th { border: 1px solid var(--line); padding: 5px 10px; text-align: left; }
.rtable th { font-family: var(--font); background: var(--panel-2); font-weight: 600; font-size: .82rem; }
.kv { display: grid; grid-template-columns: auto 1fr; gap: 3px 10px; font-size: .85rem; }
.kv dt { color: var(--ink-2); } .kv dd { margin: 0; font-family: var(--mono); font-size: .82rem; }
.tbl { width: 100%; border-collapse: collapse; font-size: .78rem; font-family: var(--mono); }
.tbl th { font-family: var(--font); text-align: left; font-weight: 600; color: var(--ink-2); padding: 4px 4px; border-bottom: 1px solid var(--line); font-size: .76rem; }
.tbl td { padding: 4px 4px; border-bottom: 1px solid var(--grid); word-break: break-all; }
.empty { color: var(--ink-3); font-size: .85rem; padding: 6px 0; }
.list { display: grid; gap: 6px; }
.list .item { display: grid; grid-template-columns: minmax(0, 1fr); gap: 5px; padding: 8px; border: 1px solid var(--line); border-radius: var(--r-s); background: var(--panel-2); }
.console { display: grid; grid-template-rows: 1fr auto auto; grid-template-columns: minmax(0, 1fr); height: 100%; min-height: 260px; }
.console pre { margin: 0; background: #0F1A2A; color: #D7E2F0; border-radius: var(--r-s); padding: 10px; font: .78rem/1.45 var(--mono); overflow: auto; min-height: 180px; max-height: 100%; white-space: pre-wrap; word-break: break-word; }
.console .in { display: flex; gap: 6px; margin-top: 6px; }
.console .in .input { flex: 1; min-width: 0; font-family: var(--mono); font-size: .82rem; }
.console .quick { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.console .quick button { font-size: .74rem; padding: 2px 8px; }

/* ---------- Panels: tabs, side panel, collapsible sections, work area ---------- */
.tabs { display: flex; gap: 0; padding: 0 6px; border-bottom: 1px solid var(--line); overflow-x: auto; scrollbar-width: none; }
.tabs button { border: 0; background: none; padding: 7px 8px; white-space: nowrap; cursor: pointer; color: var(--ink-2); display: flex; align-items: center; gap: 5px; font-size: .86rem; border-bottom: 2px solid transparent; margin-bottom: -1px; }
.tabs button.cur { color: var(--ink); border-bottom-color: var(--ink); font-weight: 600; }
.subtabs { flex-wrap: wrap; border-bottom: 1px solid var(--line); }
.side-head { display: flex; align-items: center; gap: 10px; padding: 12px 14px 8px; }
.side-head .grow { min-width: 0; }
.side-head .name { font-weight: 650; font-size: 1.02rem; border: 1px solid transparent; background: none; padding: 2px 4px; border-radius: 4px; width: 100%; }
.side-head .name:hover { border-color: var(--line); }
.side-body { overflow: auto; padding: 12px 14px 20px; min-height: 0; }
.side-body h4 { font-size: .8rem; font-weight: 650; color: var(--ink-2); margin: 14px 0 6px; }
.side-body > h4:first-child, .side-body > :first-child > h4:first-child { margin-top: 0; }
.sect { border: 1px solid var(--line); border-radius: var(--r-s); margin-top: 10px; background: var(--panel); }
.sect > summary { display: flex; align-items: center; gap: 8px; padding: 7px 10px; cursor: pointer; font-size: .85rem; font-weight: 650; list-style: none; }
.sect > summary::-webkit-details-marker { display: none; }
.sect > summary::before { content: "›"; display: inline-block; width: 10px; color: var(--ink-3); transition: transform .12s; }
.sect[open] > summary::before { transform: rotate(90deg); }
.sect-status { margin-left: auto; font-weight: 400; font-size: .78rem; color: var(--ink-3); }
.sect-status.on { color: var(--ok); }
.sect-body { padding: 2px 10px 10px; }
.sect-body > div > h4:first-child { margin-top: 4px; }
.canvas-wrap { position: relative; min-width: 0; min-height: 0; overflow: hidden; background-color: var(--paper);
  background-image: linear-gradient(var(--grid) 1px, transparent 1px), linear-gradient(90deg, var(--grid) 1px, transparent 1px);
  background-size: 24px 24px; }
.hint-overlay { position: absolute; left: 50%; bottom: 14px; transform: translateX(-50%); background: var(--panel); border: 1px solid var(--line); box-shadow: var(--shadow); border-radius: 99px; padding: 6px 14px; font-size: .85rem; color: var(--ink-2); }

/* Drag handles between panels; double-click restores the default size */
.rz { position: absolute; z-index: 6; touch-action: none; }
.rz::after { content: ""; position: absolute; background: var(--c-blue); opacity: 0; transition: opacity .12s; border-radius: 2px; }
.rz:hover::after, .rz.active::after { opacity: .55; }
.rz-col { width: 9px; cursor: col-resize; }
.rz-col::after { left: 3px; width: 3px; top: 0; bottom: 0; }
.rz-row { height: 9px; cursor: row-resize; }
.rz-row::after { top: 3px; height: 3px; left: 0; right: 0; }
body.resizing { user-select: none; }
body.resizing.col { cursor: col-resize; } body.resizing.row { cursor: row-resize; }

/* ---------- Overlays: dialog, menus, tooltip ---------- */
.dlg { border: 1px solid var(--line); border-radius: var(--r-m); background: var(--panel); color: var(--ink); padding: 18px 20px; width: min(560px, 92vw); box-shadow: var(--shadow); }
.dlg::backdrop { background: rgba(10, 18, 30, .45); }
.features { margin-top: 14px; display: grid; gap: 8px; }
.btn.addfeat { width: 100%; max-width: 100%; box-sizing: border-box; white-space: normal; justify-content: flex-start; border-style: dashed; background: transparent; flex-wrap: wrap; text-align: left; line-height: 1.35; }
.btn.addfeat .small { font-weight: 400; }
.featmenu { display: grid; gap: 2px; border: 1px solid var(--line); border-radius: var(--r-s); padding: 4px; background: var(--panel); box-shadow: var(--shadow); }
.featmenu.hidden { display: none; }
.featitem { display: grid; gap: 1px; text-align: left; border: 0; background: none; padding: 7px 9px; border-radius: 6px; cursor: pointer; color: var(--ink); }
.featitem:hover, .featitem:focus-visible { background: var(--panel-2); outline: none; }
.featitem b { font-size: .88rem; }
.featitem span { font-size: .8rem; color: var(--ink-2); }
.ctxmenu { position: fixed; z-index: 70; min-width: 210px; max-width: 300px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-s); box-shadow: var(--shadow); padding: 4px; display: grid; }
.ctx-title { font-size: .76rem; font-weight: 650; color: var(--ink-3); padding: 4px 9px 3px; text-transform: none; }
.ctx-item { display: grid; grid-template-columns: 18px 1fr auto; gap: 8px; align-items: center; border: 0; background: none; text-align: left; padding: 6px 9px; border-radius: 5px; color: var(--ink); cursor: pointer; font-size: .87rem; }
.ctx-item svg { width: 16px; height: 16px; }
.ctx-item:hover, .ctx-item:focus-visible { background: var(--panel-2); outline: none; }
.ctx-item[disabled] { opacity: .45; cursor: default; }
.ctx-item.danger { color: var(--err); }
.ctx-item kbd { font-family: var(--mono); font-size: .72rem; color: var(--ink-3); }
.ctx-sep { height: 1px; background: var(--line); margin: 4px 2px; }
abbr.gl { text-decoration: none; border-bottom: 1px dotted var(--ink-3); cursor: help; }
abbr.gl:hover, abbr.gl:focus-visible { border-bottom-color: var(--ink); outline: none; }
.gl-tip { position: fixed; z-index: 60; max-width: 320px; padding: 8px 11px; border-radius: var(--r-s); background: var(--panel); color: var(--ink-2);
  border: 1px solid var(--line); box-shadow: var(--shadow); font-size: .84rem; line-height: 1.45; pointer-events: none; opacity: 0; visibility: hidden; transition: opacity .12s; }
.gl-tip.on { opacity: 1; visibility: visible; }
.gl-tip b { color: var(--ink); }

/* ---------- Narrow screens ---------- */
@media (max-width: 1100px) {
  .lesson-body.is-lab { grid-template-columns: var(--goal-w, 290px) minmax(0, 1fr); }
  .hero { grid-template-columns: 1fr; }
}
@media (max-width: 760px) {
  .app { grid-template-columns: 1fr; grid-template-rows: 1fr 60px; }
  .rail { order: 2; flex-direction: row; border-right: 0; border-top: 1px solid var(--line); padding: 4px; justify-content: space-around; }
  .rail a, .rail button { flex: 1 1 0; min-width: 0; }
  .rail .logo, .rail .spacer { display: none; }
  .main { order: 1; }
  .rz { display: none; }
  .lesson-body.is-lab { grid-template-columns: 1fr; overflow: auto; }
  .goalcol { border-right: 0; border-bottom: 1px solid var(--line); }
  .page { padding: 20px 16px 48px; }
  .hero h1 { font-size: 2.2rem; }
  .lesson { height: auto; min-height: 100%; }
  .chtimer { display: none; }
}

/* ---------- Print ---------- */
@media print {
  @page { margin: 16mm 14mm; }
  :root, :root[data-theme="dark"] { --paper: #fff; --panel: #fff; --panel-2: #f6f7f9; --ink: #111; --ink-2: #333; --ink-3: #555; --line: #ccc; color-scheme: light; }
  html, body, .app, .main { height: auto !important; overflow: visible !important; background: #fff !important; }
  .app { display: block !important; }
  .rail, .no-print, .toast, .gl-tip { display: none !important; }
  .page { padding: 0 !important; max-width: none !important; }
  .theory { padding: 0 !important; margin: 0 !important; max-width: none !important; }
  .theory h2 { break-after: avoid; }
  .theory table, .theory pre, .theory .note { break-inside: avoid; }
  .theory pre { white-space: pre-wrap; }
  abbr.gl { border: 0; }
  * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/css/lib"
  cat > "$W/css/lib/audit.css" <<'__FLEETPILOT_FILE_END__'
/* Library element "audit" (blueprint 1.1.1): the audit log table */
.audit .row .input { flex: 1; max-width: 420px; }
.audit .audit-scroll { overflow-x: auto; margin-top: 10px; }
.audit .tbl td { vertical-align: top; }
.audit .audit-time { white-space: nowrap; color: var(--ink-2); }
.audit .audit-details { max-width: 360px; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; }
.audit .audit-bad td:nth-child(3) { color: var(--err); }
.audit .empty, .audit > .btn { margin-top: 10px; }
__FLEETPILOT_FILE_END__
  mkdir -p "$W/css/lib"
  cat > "$W/css/lib/auth.css" <<'__FLEETPILOT_FILE_END__'
/* Library element "auth" (blueprint 1.1.1): sign-in pages and account views */

/* Signed out: the rail shows only the logo and the theme button */
.auth-out .rail > a[data-nav] { display: none; }

/* The sign-in, setup and first-steps pages: one narrow column */
.auth-page { max-width: 440px; margin: 40px auto 0; }
.auth-page h1 { margin-bottom: .3em; }
.auth-form { display: grid; gap: 10px; }
.auth-form .row { margin-top: 4px; }
.auth-page .subcard { margin-top: 16px; }

/* Two-factor setup: the QR code next to the steps */
.auth-totp { display: grid; grid-template-columns: auto 1fr; gap: 16px; align-items: start; margin-bottom: 10px; }
.auth-qr { width: 180px; height: 180px; border: 1px solid var(--line); border-radius: var(--r-s); overflow: hidden; }
.auth-qr svg { display: block; width: 100%; height: 100%; }
.auth-secret { display: inline-block; font-family: var(--mono); font-size: .85rem; padding: 4px 8px; background: var(--panel-2); border: 1px solid var(--line); border-radius: var(--r-s); word-break: break-all; }
.auth-codes { display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 6px; }
.auth-codes code { font-family: var(--mono); font-size: .85rem; padding: 4px 8px; background: var(--panel-2); border: 1px solid var(--line); border-radius: var(--r-s); text-align: center; }

/* Accounts, sessions and the rules */
.auth-users, .auth-sessions { margin-top: 10px; }
.auth-users td, .auth-sessions td { vertical-align: middle; }
.auth-users .auth-off td { color: var(--ink-3); }
.auth-policy { max-width: 760px; }
.auth-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 12px; }
.auth-checks { display: grid; gap: 4px; margin-top: 12px; }

@media (max-width: 760px) {
  .auth-page { margin-top: 8px; }
  .auth-totp { grid-template-columns: 1fr; }
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/css/lib"
  cat > "$W/css/lib/stats.css" <<'__FLEETPILOT_FILE_END__'
/* Library element "stats" (blueprint 1.1.1): big numbers with a label.
   Every selector starts with .stats, every value comes from the tokens of base.css. */
.stats { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; margin-top: 14px; }
.stats > .stat-tile { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-s); padding: 10px 12px; }
.stats > .stat-tile > b { display: block; font-size: 1.3rem; font-family: var(--mono); font-weight: 700; }
.stats > .stat-tile > span { font-size: .8rem; color: var(--ink-2); }
.stats > .stat-tile.ok > b { color: var(--ok); }
.stats > .stat-tile.bad > b { color: var(--err); }
