// FleetPilot: the overview. The state of the fleet at a glance, and below only what needs someone.
import { h } from '../core/ui.js';
import { statTiles } from '../lib/stats.js';
import { main, get, can, pageHead, link, table, runState, when, plural, empty, hostState } from '../common.js';

export async function viewOverview(ctx) {
  document.title = 'Overview';
  let page = build(await get('/api/overview'));
  main.append(page);
  // Fresh numbers every 15 seconds while the page is open, in place
  const t = setInterval(async () => {
    if (document.visibilityState !== 'visible') return;
    const d = await get('/api/overview').catch(() => null);
    if (!d || !page.isConnected) return;
    const top = main.scrollTop, next = build(d);
    page.replaceWith(next); page = next; main.scrollTop = top;
  }, 15000);
  ctx.onLeave(() => clearInterval(t));
}

function build(d) {
  const c = d.counts, a = d.attention;
  const page = h('div', { class: 'page' });
  page.append(pageHead('Overview', 'How the fleet is doing, and what needs you.'));
  if (!c.hosts && can('hosts', 'manage')) {
    page.append(h('div', { class: 'subcard fp-start' },
      h('h2', {}, 'Start with your hosts'),
      h('p', { class: 'muted' }, 'Add hosts by address, a list or a range, or let FleetPilot find the VMs of a Proxmox cluster. Then take them over: FleetPilot logs in once with the password of your installation and manages them with certificates from then on.'),
      h('div', { class: 'row' }, link('Add hosts', '#/hosts?add=1', 'plus', 'primary'), link('Connect a Proxmox cluster', '#/hosts?tab=sources', 'sync'))));
  }
  const tiles = [
    { value: c.hosts ?? 0, label: 'hosts' },
    { value: c.managed ?? 0, label: 'managed', state: c.managed && c.managed === c.hosts ? 'ok' : undefined },
    { value: c.waiting ?? 0, label: 'not taken over' },
    { value: c.unreachable ?? 0, label: 'unreachable', state: c.unreachable ? 'bad' : undefined },
    { value: c.drifted ?? 0, label: 'drifted', state: c.drifted ? 'bad' : undefined },
    { value: c.running ?? 0, label: 'runs going' },
    { value: c.approvals ?? 0, label: 'waiting for approval', state: c.approvals ? 'bad' : undefined },
    { value: c.failed ?? 0, label: 'failed today', state: c.failed ? 'bad' : undefined }
  ];
  page.append(statTiles(tiles));
  const section = (title, rows, emptyText) => [h('h2', { class: 'fp-sec' }, title), ...(rows.length ? rows : [empty(emptyText)])];
  const runRow = r => h('tr', {}, h('td', {}, h('a', { href: `#/runs/${r.id}` }, r.name)), h('td', {}, runState(r.status)), h('td', {}, r.done !== undefined ? `${r.done} of ${plural(r.hosts, 'host', 'hosts')}` : plural(r.hosts ?? 0, 'host', 'hosts')), h('td', { class: 'muted' }, r.requested_by || ''), h('td', { class: 'muted' }, when(r.finished_at || r.started_at || r.created_at)));
  const nothing = !a.approvals.length && !a.running.length && !a.failedRuns.length && !a.unreachable.length && !a.drifted.length && !a.notTakenOver.length;
  if (nothing && c.hosts) page.append(h('div', { class: 'done-banner fp-allgood' }, 'All is well: nothing needs you right now.'));
  if (a.approvals.length) page.append(...section('Waiting for an approval', [table(['Run', 'State', 'Hosts', 'Started by', 'When'], a.approvals.map(runRow))]));
  if (a.running.length) page.append(...section('Running now', [table(['Run', 'State', 'Progress', 'Started by', 'Since'], a.running.map(runRow))]));
  if (a.failedRuns.length) page.append(...section('Failed in the last 7 days', [table(['Run', 'State', 'Hosts', '', 'Finished'], a.failedRuns.map(r => runRow({ ...r, hosts: Object.values(r.summary || {}).reduce((x, y) => x + y, 0) })))]));
  if (a.unreachable.length) page.append(...section('Unreachable hosts', [table(['Host', 'Address', 'Last seen'], a.unreachable.map(x => h('tr', {}, h('td', {}, h('a', { href: `#/hosts/${x.id}` }, x.name)), h('td', { class: 'mono' }, x.address), h('td', { class: 'muted' }, when(x.last_seen_at)))))]));
  if (a.drifted.length) page.append(...section('Hosts that drifted from their desired state', [table(['Host', 'Differences', 'Checked'], a.drifted.map(x => h('tr', {}, h('td', {}, h('a', { href: `#/hosts/${x.id}?tab=state` }, x.name)), h('td', {}, String(x.changed)), h('td', { class: 'muted' }, when(x.at)))))]));
  if (a.notTakenOver.length) page.append(...section('Not taken over yet', [table(['Host', 'Address', 'State', 'Added'], a.notTakenOver.map(x => h('tr', {}, h('td', {}, h('a', { href: `#/hosts/${x.id}` }, x.name)), h('td', { class: 'mono' }, x.address), h('td', {}, hostState(x.state)), h('td', { class: 'muted' }, when(x.created_at)))))]));
  return page;
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/js/views"
  cat > "$W/js/views/runs.js" <<'__FLEETPILOT_FILE_END__'
// FleetPilot: runs. The list (going, waiting for an approval, finished), and a run's page: which
// host is at which step (a host × step grid), approval, cancelling, running again, and the live log.
import { h, toast } from '../core/ui.js';
import { api } from '../core/api.js';
import { I } from '../icons.js';
import { main, get, call, can, pageHead, btn, tabs, dialog, field, input, select, table, empty, when, duration, plural, runState, runStateText } from '../common.js';

const TRIGGERS = { manual: 'Started by hand', schedule: 'On its schedule', host_added: 'A host was added', template_changed: 'A template changed', api: 'Through the API' };
const ACTIVE = ['queued', 'running', 'awaiting_approval', 'waiting'];
const MARK = { ok: I.check, changed: I.check, failed: I.x, unreachable: I.x, skipped: I.minus, running: I.timer, pending: '' };

export async function viewRuns(ctx) {
  document.title = 'Runs';
  const q = ctx.query;
  const tab = q.workflow || q.host ? 'all' : q.tab || ctx.store.prefs['runs.tab'] || 'all';
  const page = h('div', { class: 'page' });
  page.append(pageHead('Runs', 'Every time a workflow ran or runs: on which hosts, by whom, and what happened.', [
    can('runs', 'run') ? h('a', { class: 'btn primary', href: '#/hosts?tab=table' }, 'Start a run on hosts') : null
  ].filter(Boolean)));
  if (q.workflow || q.host) page.append(h('p', { class: 'small muted' }, q.workflow ? 'Runs of one workflow. ' : 'Runs on one host. ', h('a', { href: '#/runs' }, 'Show all runs')));
  const body = h('div', {});
  page.append(tabs([['all', 'All'], ['active', 'Going'], ['waiting', 'Waiting for approval'], ['failed', 'Failed']], tab, id => { ctx.store.setPref('runs.tab', id); draw(id); }), body);
  main.append(page);
  let timer;
  ctx.onLeave(() => clearInterval(timer));
  const draw = async id => {
    clearInterval(timer);
    body.innerHTML = '';
    const params = new URLSearchParams();
    if (id === 'active') params.set('active', '1');
    if (id === 'waiting') params.set('waiting', '1');
    if (id === 'failed') params.set('status', 'failed');
    if (q.workflow) params.set('workflow', q.workflow);
    if (q.host) params.set('host', q.host);
    const box = h('div', {});
    body.append(box);
    let rows = await get(`/api/runs?${params}`);
    const paint = () => {
      box.innerHTML = '';
      if (!rows.length) { box.append(empty(id === 'waiting' ? 'No run waits for an approval.' : id === 'active' ? 'Nothing runs right now.' : 'No runs yet. Start a workflow on hosts, or let a schedule start one.')); return; }
      box.append(runTable(rows));
      if (rows.length % 50 === 0) box.append(h('div', { class: 'row', style: { marginTop: '10px' } }, btn('Show older runs', 'down', async () => {
        const p = new URLSearchParams(params); p.set('before', rows[rows.length - 1].id);
        rows = rows.concat(await get(`/api/runs?${p}`)); paint();
      }, 'ghost')));
    };
    paint();
    // Fresh states while something runs
    timer = setInterval(async () => {
      if (document.visibilityState !== 'visible' || !rows.some(r => ACTIVE.includes(r.status))) return;
      const fresh = await api.get(`/api/runs?${params}`).catch(() => null);
      if (fresh && box.isConnected) { rows = fresh; paint(); }
    }, 4000);
  };
  await draw(tab);
}

export function runTable(rows) {
  return table(['Run', 'State', 'Why', 'Hosts', 'By', 'When', 'Took'], rows.map(r => h('tr', {},
    h('td', {}, h('a', { href: `#/runs/${r.id}` }, r.name), r.check_only ? h('span', { class: 'chip', style: { marginLeft: '6px' } }, 'check only') : null),
    h('td', {}, runState(r.status)), h('td', { class: 'muted' }, TRIGGERS[r.trigger] || r.trigger),
    h('td', { title: r.host_names || '' }, r.hosts === 1 ? r.host_names : plural(r.hosts, 'host', 'hosts')),
    h('td', {}, r.requested_by || 'FleetPilot'), h('td', { class: 'muted' }, when(r.created_at)),
    h('td', { class: 'muted' }, r.started_at ? duration(r.started_at, r.finished_at) : '–'))));
}

// ---------------------------------------------------------------- One run
export async function viewRun(ctx, id) {
  let r = await get(`/api/runs/${id}`);
  document.title = r.name;
  const page = h('div', { class: 'page fp-page-wide' });
  const head = h('div', {}), grid = h('div', {}), logBox = h('div', {});
  page.append(h('p', { class: 'fp-crumb small' }, h('a', { href: '#/runs' }, 'Runs'), ' / '), head, grid, logBox);
  main.append(page);

  const paintHead = () => {
    head.innerHTML = '';
    const may = r.may;
    const finished = !ACTIVE.includes(r.status);
    head.append(pageHead(r.name, null, [
      may.approve ? btn('Approve', 'check', () => act('approve'), 'primary') : null,
      may.approve || (may.cancel && ['awaiting_approval', 'waiting'].includes(r.status)) ? btn('Reject', 'x', async () => {
        const reason = input({ placeholder: 'Why not' });
        if (await dialog('Reject this run', [field('Reason', reason, 'The person who started it sees it.')], { ok: 'Reject the run', okClass: 'danger', onOk: () => call(() => api.post(`/api/runs/${r.id}/reject`, { reason: reason.value })) })) refresh();
      }) : null,
      may.cancel && !['awaiting_approval', 'waiting'].includes(r.status) ? btn('Cancel the run', 'stop', async () => {
        if (await dialog('Cancel this run', [h('p', {}, 'The step that runs now ends on every host; no further step starts. What was changed stays changed.')], { ok: 'Cancel the run', okClass: 'danger', cancel: 'Let it run', onOk: () => call(() => api.post(`/api/runs/${r.id}/cancel`, {})) })) refresh();
      }, 'ghost') : null,
      finished && may.retry ? btn('Run it again', 'reset', () => retry(false)) : null,
      finished && may.retry && r.hosts.some(x => ['failed', 'unreachable', 'skipped'].includes(x.status)) ? btn('Again on the failed hosts', 'reset', () => retry(true), 'ghost') : null,
      r.workflow_id ? h('a', { class: 'btn ghost', href: `#/automate/workflow/${r.workflow_id}` }, 'The workflow') : null
    ].filter(Boolean)));
    const counts = {};
    for (const x of r.hosts) counts[x.status] = (counts[x.status] || 0) + 1;
    head.append(h('div', { class: 'row fp-runmeta' }, runState(r.status), r.check_only ? h('span', { class: 'chip' }, 'Only a check: nothing was changed') : null,
      h('span', { class: 'small muted' }, `${TRIGGERS[r.trigger] || r.trigger}${r.requested_by ? ` by ${r.requested_by}` : ''}, ${when(r.created_at)}`),
      r.approved_by ? h('span', { class: 'small muted' }, `${r.status === 'rejected' ? 'Rejected' : 'Approved'} by ${r.approved_by}`) : null,
      r.started_at ? h('span', { class: 'small muted' }, `${finished ? 'Took' : 'Running for'} ${duration(r.started_at, r.finished_at)}`) : null,
      ...Object.entries(counts).map(([k, n]) => h('span', { class: `fp-state ${k === 'ok' || k === 'changed' ? 'ok' : k === 'failed' || k === 'unreachable' ? 'bad' : k === 'running' ? 'busy' : 'idle'}` }, `${n} ${runStateText(k).toLowerCase()}`))));
    if (r.reason) head.append(h('p', { class: 'fp-note' }, `Reason: ${r.reason}`));
    if (['awaiting_approval', 'waiting'].includes(r.status)) head.append(h('div', { class: 'fp-note fp-waitnote' }, r.status === 'awaiting_approval'
      ? (r.may.approve ? 'This run waits for your approval. Look at the steps and the hosts, then approve or reject it.' : 'This run waits for an approval by someone whose roles allow it.')
      : (r.may.approve ? 'The run stopped at an approval step and waits for you.' : 'The run stopped at an approval step and waits for someone to approve it.')));
  };

  const paintGrid = () => {
    grid.innerHTML = '';
    const res = new Map(r.results.map(x => [`${x.step}:${x.host_id}`, x]));
    const batches = new Set(r.hosts.map(x => x.batch)).size;
    const cur = r.state?.step;
    grid.append(h('h2', { class: 'fp-sec' }, 'Hosts and steps'));
    grid.append(h('div', { class: 'fp-tablewrap' }, h('table', { class: 'tbl fp-table fp-matrix' },
      h('thead', {}, h('tr', {}, h('th', {}, 'Host'), batches > 1 ? h('th', {}, 'Batch') : null, r.steps.map((s, i) => h('th', { title: s.sentence, class: `ar-${s.area}${ACTIVE.includes(r.status) && cur === i ? ' cur' : ''}` }, h('span', { class: 'fp-thnum' }, String(i + 1)), ' ', s.title)), h('th', {}, 'Result'))),
      h('tbody', {}, r.hosts.map(x => h('tr', {},
        h('td', {}, h('a', { href: `#/hosts/${x.id}` }, x.name), h('div', { class: 'small muted mono' }, x.address || '')),
        batches > 1 ? h('td', { class: 'muted' }, String(x.batch + 1)) : null,
        r.steps.map((s, i) => { const c = res.get(`${i}:${x.id}`); const stt = c?.status || 'pending'; return h('td', { class: `fp-cell st-${stt}`, title: `${s.title}: ${runStateText(stt)}${c?.message ? `. ${c.message}` : ''}` }, h('span', { class: 'fp-mark', 'aria-hidden': 'true', html: MARK[stt] || '' }), c?.message ? h('span', { class: 'fp-cellmsg' }, c.message) : null); }),
        h('td', {}, runState(x.status))))))));
    grid.append(h('details', { class: 'fp-vars small' }, h('summary', {}, 'What each step does'), h('ol', { class: 'fp-steps-preview' }, r.steps.map(s => h('li', {}, h('b', {}, s.title), `: ${s.sentence}`, s.onFailure === 'run' ? ' If it fails, the run stops.' : s.onFailure === 'continue' ? ' If it fails, the host goes on.' : '')))));
  };

  // ------------------------------------------------------------ The live log
  let after = '0', hostFilter = '';
  const pre = h('pre', { 'aria-live': 'polite' });
  const follow = h('input', { type: 'checkbox', checked: true });
  const hostSel = select([['', 'Every host'], ...r.hosts.map(x => [x.name, x.name])], '', { onchange: e => { hostFilter = e.target.value; after = '0'; pre.innerHTML = ''; pullLog(); } });
  logBox.append(h('h2', { class: 'fp-sec' }, 'Log'), h('div', { class: 'row fp-logbar' }, hostSel, h('label', { class: 'row small fp-check' }, follow, 'Follow the newest lines'),
    btn('Download the log', 'download', async () => {
      const all = await get(`/api/runs/${r.id}/log?after=0`);
      const text = all.lines.map(l => `${new Date(l.at).toISOString()} ${l.host || '-'} [${l.level}] ${l.line}`).join('\n');
      const a = h('a', { href: URL.createObjectURL(new Blob([text], { type: 'text/plain' })), download: `fleetpilot-run-${r.id}.log` }); document.body.append(a); a.click(); a.remove();
    }, 'ghost')), h('div', { class: 'console fp-log' }, pre));
  const fmt = l => h('span', { class: `lg-${l.level}` }, `${new Date(l.at).toLocaleTimeString(undefined, { hour12: false })}  ${l.host ? `${l.host.padEnd(14)} ` : ''}${l.line}\n`);
  let pulling = false;
  async function pullLog() {
    if (pulling) return;
    pulling = true;
    try {
      const d = await api.get(`/api/runs/${r.id}/log?after=${after}${hostFilter ? `&host=${encodeURIComponent(hostFilter)}` : ''}`);
      if (d.lines.length) {
        after = d.lines[d.lines.length - 1].id;
        pre.append(...d.lines.map(fmt));
        if (follow.checked) pre.scrollTop = pre.scrollHeight;
      }
      if (!pre.childNodes.length && !d.lines.length) pre.textContent = ACTIVE.includes(r.status) ? 'Nothing logged yet.\n' : 'This run logged nothing.\n';
      else if (pre.firstChild?.nodeType === 3) pre.firstChild.remove();
    } catch { /* the next pull tries again */ }
    pulling = false;
  }

  async function refresh() {
    const fresh = await api.get(`/api/runs/${r.id}`).catch(() => null);
    if (!fresh || !page.isConnected) return;
    r = fresh; paintHead(); paintGrid();
  }
  async function act(what) { await call(() => api.post(`/api/runs/${r.id}/${what}`, {})).catch(() => null); toast(what === 'approve' ? 'Approved: the run starts' : 'Done'); refresh(); }
  async function retry(failedOnly) {
    const n = await call(() => api.post(`/api/runs/${r.id}/retry`, { failedOnly })).catch(() => null);
    if (n?.id) location.hash = `#/runs/${n.id}`;
  }

  paintHead(); paintGrid(); await pullLog();
  const t1 = setInterval(() => { if (document.visibilityState === 'visible' && ACTIVE.includes(r.status)) pullLog(); }, 1500);
  const t2 = setInterval(() => { if (document.visibilityState === 'visible' && ACTIVE.includes(r.status)) refresh().then(() => { if (!ACTIVE.includes(r.status)) pullLog(); }); }, 3000);
  ctx.onLeave(() => { clearInterval(t1); clearInterval(t2); });
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/js/views"
  cat > "$W/js/views/settings.js" <<'__FLEETPILOT_FILE_END__'
// FleetPilot: settings. Your account; for administrators the accounts with their roles, the roles
// (rights per area, for which groups, with or without approval), the sign-in rules, FleetPilot's
// own settings and the audit log; the vault; FleetPilot's SSH keys and a certificate for yourself.
import { h, toast, iconBtn } from '../core/ui.js';
import { api } from '../core/api.js';
import { I } from '../icons.js';
import { session, accountView, usersView, policyView, confirmFresh } from '../lib/auth.js';
import { auditView } from '../lib/audit.js';
import { main, meta, get, call, can, pageHead, btn, tabs, dialog, field, input, select, table, empty, when, chips, groupOptions, forgetChoices } from '../common.js';
import { revealSecret } from './hosts.js';

const AUDIT_LABELS = {
  'host.added': 'Added hosts', 'host.changed': 'Changed a host', 'host.removed': 'Removed a host', 'host.bulk_move': 'Moved hosts', 'host.bulk_tag': 'Tagged hosts', 'host.bulk_untag': 'Removed tags from hosts', 'host.bulk_retire': 'Retired hosts', 'host.bulk_activate': 'Brought hosts back',
  'group.created': 'Added a group', 'group.changed': 'Changed a group', 'group.deleted': 'Deleted a group',
  'template.created': 'Created a template', 'template.saved': 'Saved a template version', 'template.changed': 'Changed a template', 'template.deleted': 'Deleted a template',
  'template.assigned': 'Applied a template', 'template.unassigned': 'Removed a template',
  'workflow.created': 'Created a workflow', 'workflow.changed': 'Changed a workflow', 'workflow.deleted': 'Deleted a workflow',
  'run.started': 'Started a run', 'run.approved': 'Approved a run', 'run.rejected': 'Rejected a run', 'run.cancelled': 'Cancelled a run',
  'secret.created': 'Added a secret', 'secret.changed': 'Changed a secret', 'secret.revealed': 'Showed a secret', 'secret.deleted': 'Deleted a secret',
  'ssh_certificate.issued': 'Got an SSH certificate', 'role.created': 'Added a role', 'role.changed': 'Changed a role', 'role.deleted': 'Deleted a role',
  'user.roles_changed': 'Changed the roles of an account', 'settings.changed': 'Changed the settings',
  'subnet.created': 'Added a subnet', 'subnet.changed': 'Changed a subnet', 'subnet.deleted': 'Deleted a subnet', 'subnet.scanned': 'Scanned a subnet',
  'vlan.created': 'Added a VLAN', 'vlan.changed': 'Changed a VLAN', 'vlan.deleted': 'Deleted a VLAN', 'pool.created': 'Added a pool', 'pool.deleted': 'Deleted a pool',
  'address.reserved': 'Reserved an address', 'address.assigned': 'Assigned an address', 'address.changed': 'Changed an address', 'address.released': 'Released an address',
  'source.created': 'Added a Proxmox cluster', 'source.changed': 'Changed a Proxmox cluster', 'source.deleted': 'Removed a Proxmox cluster', 'source.imported': 'Imported VMs'
};

export async function viewSettings(ctx, tab) {
  document.title = 'Settings';
  const admin = meta.access.admin;
  const list = [['account', 'Your account'], ...(can('vault', 'view') ? [['vault', 'Vault']] : []), ['ssh', 'SSH keys'],
    ...(admin ? [['accounts', 'Accounts'], ['roles', 'Roles'], ['rules', 'Sign-in rules'], ['fleetpilot', 'FleetPilot'], ['audit', 'Audit log']] : [])];
  tab = list.some(x => x[0] === tab) ? tab : 'account';
  const page = h('div', { class: 'page' });
  page.append(pageHead('Settings', `FleetPilot ${meta.version}${meta.ansible ? ` with Ansible ${meta.ansible}` : ''}. Signed in as ${session.user.username}${admin ? ', administrator' : meta.access.roles.length ? `, ${meta.access.roles.join(', ')}` : ''}.`));
  const body = h('div', {});
  page.append(tabs(list, tab, id => { history.replaceState(null, '', `#/settings/${id}`); draw(id); }), body);
  main.append(page);
  const draw = async id => {
    body.innerHTML = '';
    if (id === 'vault') await drawVault(body);
    else if (id === 'ssh') await drawSsh(body);
    else if (id === 'accounts') await drawAccounts(body);
    else if (id === 'roles') await drawRoles(body);
    else if (id === 'rules') await policyView(body);
    else if (id === 'fleetpilot') await drawFleetPilot(body);
    else if (id === 'audit') auditView(body, { label: a => AUDIT_LABELS[a] || null });
    else accountView(body);
  };
  await draw(tab);
}

// ---------------------------------------------------------------- Accounts and their roles
async function drawAccounts(body) {
  let roles = await get('/api/access/roles');
  let users = await get('/api/access/users');
  body.append(h('p', { class: 'muted small' }, 'Administrators may do everything. Everyone else gets their rights from roles; give each account one or more.'));
  const v = usersView(body, {
    extra: u => {
      const a = users.find(x => x.username === u.username);
      if (u.isAdmin) return h('span', { class: 'small muted' }, 'Everything');
      return h('div', { class: 'row', style: { gap: '4px' } }, a?.roles.length ? chips(a.roles.map(r => r.name)) : h('span', { class: 'small muted' }, 'No role: sees nothing'),
        h('button', { class: 'btn ghost', type: 'button', onclick: () => editRoles(a) }, 'Roles'));
    },
    onChange: async () => { users = await get('/api/access/users'); }
  });
  async function editRoles(a) {
    if (!a) return;
    const boxes = roles.map(r => [r, h('input', { type: 'checkbox', checked: a.roles.some(x => x.id === r.id) })]);
    const ok = await dialog(`Roles of ${a.username}`, boxes.map(([r, c]) => h('label', { class: 'row small fp-check fp-rolepick' }, c, h('span', {}, h('b', {}, r.name), h('span', { class: 'muted' }, ` ${r.description}`)))), {
      onOk: () => call(() => api.put(`/api/access/users/${a.id}/roles`, { roleIds: boxes.filter(([, c]) => c.checked).map(([r]) => r.id) }))
    });
    if (ok) { users = await get('/api/access/users'); roles = await get('/api/access/roles'); v.refresh(); toast('Roles saved'); }
  }
}

async function drawRoles(body) {
  const roles = await get('/api/access/roles');
  const groups = await groupOptions();
  const groupName = new Map(groups);
  const areas = meta.access.areas, names = meta.access.levels;
  body.append(h('p', { class: 'muted small' }, 'A role gives rights per area, everywhere or only for some sites and groups. With "Runs wait for an approval", someone with the right to approve looks at every run first.'));
  body.append(h('div', { class: 'row', style: { marginBottom: '10px' } }, btn('Add a role', 'plus', () => roleDialog(null), 'primary')));
  body.append(table(['Role', ...Object.values(areas).map(a => a.title), 'Where', 'Accounts', ''], roles.map(r => h('tr', {},
    h('td', {}, h('b', {}, r.name), r.builtin ? h('span', { class: 'chip', style: { marginLeft: '6px' } }, 'built in') : null, h('div', { class: 'small muted' }, r.description), r.permissions.needsApproval ? h('div', { style: { marginTop: '4px' } }, h('span', { class: 'fp-state wait' }, 'Runs wait for an approval')) : null),
    ...Object.keys(areas).map(k => h('td', { class: 'small' }, names[r.permissions[k]] || 'No access')),
    h('td', { class: 'small' }, r.scope_group_ids.length ? r.scope_group_ids.map(g => groupName.get(g) || '?').join(', ') : 'Everywhere'),
    h('td', {}, String(r.users)),
    h('td', { class: 'fp-actions-cell' }, btn('Change', '', () => roleDialog(r), 'ghost'), btn('Delete', '', async () => {
      if (await dialog(`Delete the role ${r.name}`, [h('p', {}, r.users ? `${r.users} accounts lose the rights of this role.` : 'No account has it.')], { ok: 'Delete the role', okClass: 'danger', onOk: () => call(() => api.del(`/api/access/roles/${r.id}`)) })) redraw();
    }, 'ghost'))))));
  const redraw = () => { body.innerHTML = ''; drawRoles(body); };
  async function roleDialog(r) {
    const name = input({ value: r?.name || '', placeholder: 'Web team' });
    const desc = input({ value: r?.description || '' });
    const sels = Object.fromEntries(Object.entries(areas).map(([k, a]) => [k, select(a.levels.map(l => [l, names[l]]), r?.permissions[k] || 'none')]));
    const approval = h('input', { type: 'checkbox', checked: !!r?.permissions.needsApproval });
    const scope = h('select', { class: 'input', multiple: true, size: Math.min(6, Math.max(3, groups.length)) }, groups.map(([v, n]) => h('option', { value: v, selected: (r?.scope_group_ids || []).includes(String(v)) }, n)));
    const ok = await dialog(r ? `Change ${r.name}` : 'Add a role', [
      h('div', { class: 'fp-grid2' }, field('Name', name), field('Description', desc)),
      h('div', { class: 'fp-grid3' }, Object.entries(areas).map(([k, a]) => field(a.title, sels[k], a.text))),
      h('label', { class: 'row small fp-check' }, approval, 'Runs wait for an approval by someone else'),
      groups.length ? field('Only for these sites and groups (and the groups inside)', scope, 'Nothing chosen: everywhere.') : null
    ], {
      wide: true, ok: r ? 'Save' : 'Add the role',
      onOk: () => call(() => {
        const b = { name: name.value, description: desc.value, permissions: { ...Object.fromEntries(Object.entries(sels).map(([k, s]) => [k, s.value])), needsApproval: approval.checked }, scope: [...scope.selectedOptions].map(o => o.value) };
        return r ? api.patch(`/api/access/roles/${r.id}`, b) : api.post('/api/access/roles', b);
      })
    });
    if (ok) redraw();
  }
}

// ---------------------------------------------------------------- FleetPilot's own settings
async function drawFleetPilot(body) {
  const s = await get('/api/settings');
  const conc = input({ mono: true, type: 'number', min: 1, max: 64, value: s['runs.concurrency'], style: { width: '96px' } });
  const keep = input({ mono: true, type: 'number', min: 7, max: 3650, value: s['runs.keep_days'], style: { width: '96px' } });
  const live = h('input', { type: 'checkbox', checked: s['network.live_check'] });
  const reveal = input({ mono: true, type: 'number', min: 1, max: 60, value: s['vault.reveal_minutes'], style: { width: '96px' } });
  body.append(h('form', { class: 'fp-form', onsubmit: async e => {
    e.preventDefault();
    await call(() => api.put('/api/settings', { 'runs.concurrency': Number(conc.value), 'runs.keep_days': Number(keep.value), 'network.live_check': live.checked, 'vault.reveal_minutes': Number(reveal.value) })).then(() => toast('Settings saved')).catch(() => {});
  } },
  h('h2', {}, 'Runs'),
  h('div', { class: 'fp-grid2' }, field('Runs at the same time', conc, 'Per FleetPilot server. Takes effect after a restart.'), field('Keep finished runs for', keep, 'Days, with their logs.')),
  h('h2', {}, 'Network'),
  h('label', { class: 'row small fp-check' }, live, 'Ask an address on the network before it is given out (SSH, Windows and printer ports, then ping)'),
  h('h2', {}, 'Vault'),
  field('A confirmation for showing secrets lasts', reveal, 'Minutes. After that, showing a value asks for the password or code again.'),
  h('div', { class: 'row', style: { marginTop: '16px' } }, h('button', { class: 'btn primary', type: 'submit' }, 'Save settings'))));
}

// ---------------------------------------------------------------- The vault
const SCOPES = { global: 'For everything', group: 'For a group', host: 'For one host', system: 'FleetPilot\'s own' };

async function drawVault(body) {
  const q = input({ type: 'search', class: 'input fp-find', placeholder: 'Find a secret: name, user or host', 'aria-label': 'Find a secret' });
  const scope = select([['', 'Every scope'], ...Object.entries(SCOPES)], '');
  const out = h('div', {});
  const load = async () => {
    const p = new URLSearchParams();
    if (q.value.trim()) p.set('q', q.value.trim());
    if (scope.value) p.set('scope', scope.value);
    const list = await get(`/api/vault?${p}`);
    out.innerHTML = '';
    if (!list.length) { out.append(empty(q.value || scope.value ? 'Nothing matches.' : 'The vault is empty. Add the login of your standard installation first: take-over workflows log in with it.')); return; }
    out.append(table(['Name', 'Kind', 'For', 'User', 'Version', 'Changed', ''], list.map(s => h('tr', {},
      h('td', {}, h('b', {}, s.name), s.public?.fingerprint ? h('div', { class: 'small muted mono' }, s.public.fingerprint) : null, s.public?.validTo ? h('div', { class: 'small muted' }, `Valid until ${new Date(s.public.validTo).toLocaleDateString()}`) : null),
      h('td', { class: 'fp-font' }, meta.vaultKinds[s.kind] || s.kind),
      h('td', {}, s.scope === 'host' ? h('a', { href: `#/hosts/${s.host_id}?tab=secrets` }, s.host_name || 'a host') : s.scope === 'group' ? `Group ${s.group_name || ''}` : SCOPES[s.scope]),
      h('td', {}, s.username || '–'), h('td', {}, String(s.version)), h('td', { class: 'muted' }, when(s.rotated_at || s.updated_at)),
      h('td', { class: 'fp-actions-cell' },
        can('vault', 'reveal') && (s.scope !== 'system' || meta.access.admin) ? btn('Show', 'eye', () => revealSecret(s), 'ghost') : null,
        btn('History', '', () => history(s), 'ghost'),
        can('vault', 'change') && s.scope !== 'system' ? btn('Change', '', async () => { if (await secretDialog({ secret: s })) load(); }, 'ghost') : null)))));
  };
  q.addEventListener('input', () => { clearTimeout(q._t); q._t = setTimeout(load, 250); });
  scope.addEventListener('change', load);
  body.append(h('p', { class: 'muted small' }, 'Every value is encrypted with the key of this installation. Showing one needs a fresh confirmation and is recorded in the audit log. Every change keeps the old version.'),
    h('div', { class: 'row fp-toolbar' }, q, scope, can('vault', 'change') ? btn('Add a secret', 'plus', async () => { if (await secretDialog({ scope: 'global' })) load(); }, 'primary') : null), out);
  await load();

  async function history(s) {
    const d = await get(`/api/vault/${s.id}`);
    await dialog(`History of ${s.name}`, [table(['Version', 'By', 'When', ''], d.versions.map(v => h('tr', {}, h('td', {}, String(v.version)), h('td', {}, v.created_by || ''), h('td', { class: 'muted' }, when(v.created_at)),
      h('td', {}, can('vault', 'reveal') && (s.scope !== 'system' || meta.access.admin) ? btn('Show', 'eye', () => revealSecret(s, v.version === s.version ? undefined : v.version), 'ghost') : null))))]);
  }
}

/**
 * Adds a secret (scope global, group or host) or changes one ({ secret }). Values per kind;
 * passwords can be made by FleetPilot. Resolves true when saved.
 */
export async function secretDialog({ scope = 'global', hostId = null, groupId = null, secret = null } = {}) {
  const kinds = Object.entries(meta.vaultKinds).filter(([k]) => k !== 'ssh_cert' || secret);
  const kind = select(kinds, secret?.kind || 'login', { disabled: !!secret });
  const name = input({ value: secret?.name || '', placeholder: 'Debian installation' });
  const user = input({ value: secret?.username || '', placeholder: 'admin', mono: true });
  const groups = !secret && scope !== 'host' && !groupId ? await groupOptions() : null;
  const groupSel = groups?.length ? select(groups, '') : null;
  const gen = h('input', { type: 'checkbox' });
  const genLen = input({ mono: true, type: 'number', min: 12, max: 128, value: 24, style: { width: '80px' } });
  const ta = (ph, rows = 5) => h('textarea', { class: 'input mono fp-area', rows, spellcheck: 'false', placeholder: ph });
  const f = {
    password: input({ type: 'password', mono: true, autocomplete: 'new-password', placeholder: secret ? 'Leave empty to keep it' : '' }),
    becomePassword: input({ type: 'password', mono: true, autocomplete: 'new-password', placeholder: secret ? 'Leave empty to keep it' : 'Only for su' }),
    token: ta(secret ? 'Leave empty to keep it' : '', 3), text: ta(secret ? 'Leave empty to keep it' : ''),
    privateKey: ta('-----BEGIN OPENSSH PRIVATE KEY-----'), publicKey: ta('ssh-ed25519 AAAA… (optional)', 2),
    certificate: ta('-----BEGIN CERTIFICATE-----'), key: ta('-----BEGIN PRIVATE KEY-----')
  };
  const forKind = h('div', { class: 'fp-form' });
  const scopeSel = select([['global', 'For everything'], ...(groupSel ? [['group', 'For a group']] : [])], scope === 'host' ? 'global' : scope);
  const groupBox = groupSel ? h('div', {}, field('Group', groupSel)) : null;
  const showGroup = () => groupBox?.classList.toggle('hidden', scopeSel.value !== 'group');
  scopeSel.addEventListener('change', showGroup);
  showGroup();
  const drawKind = () => {
    forKind.innerHTML = '';
    const k = kind.value;
    const genRow = h('div', { class: 'row small' }, h('label', { class: 'row fp-check' }, gen, 'Let FleetPilot make a random password of'), genLen, 'characters');
    if (k === 'login') forKind.append(field('User', user), genRow, field('Password', f.password), field('Root password', f.becomePassword, 'When the user becomes root with su. Empty: the same as the password, or sudo.'));
    if (k === 'password') forKind.append(genRow, field('Password', f.password));
    if (k === 'token') forKind.append(field('User or token id', user), field('Token', f.token));
    if (k === 'note') forKind.append(field('Text', f.text));
    if (k === 'ssh_key') forKind.append(field('User', user), field('Private key', f.privateKey), field('Public key', f.publicKey));
    if (k === 'ssh_cert') forKind.append(field('Certificate', f.certificate));
    if (k === 'tls') forKind.append(field('Certificate (with the chain)', f.certificate), field('Private key', f.key));
  };
  kind.addEventListener('change', drawKind);
  drawKind();
  const r = await dialog(secret ? `Change ${secret.name}` : scope === 'host' ? 'Add a secret for this host' : 'Add a secret', [
    h('div', { class: 'fp-grid2' }, field('Kind', kind), field('Name', name)),
    !secret && scope !== 'host' && !groupId ? field('For', scopeSel) : null,
    groupBox,
    forKind,
    secret ? h('p', { class: 'small muted' }, 'Saving makes a new version; the old one stays in the history.') : null
  ], {
    ok: secret ? 'Save a new version' : 'Add the secret', wide: true,
    onOk: () => call(() => {
      const k = kind.value, data = {};
      for (const key of ['password', 'becomePassword', 'token', 'text', 'privateKey', 'publicKey', 'certificate', 'key']) if (f[key].value) data[key] = f[key].value;
      const b = { name: name.value, username: user.value, data, generate: gen.checked && ['login', 'password'].includes(k) ? { length: Number(genLen.value) || 24 } : undefined };
      if (secret) return api.put(`/api/vault/${secret.id}`, b);
      const sc = scope === 'host' ? 'host' : groupId ? 'group' : scopeSel.value;
      return api.post('/api/vault', { ...b, kind: k, scope: sc, hostId, groupId: groupId || (sc === 'group' ? groupSel?.value : null) || null });
    })
  });
  if (r) { forgetChoices(); toast(secret ? 'Saved' : 'Secret added'); }
  return !!r;
}

// ---------------------------------------------------------------- SSH: FleetPilot's keys, a certificate for yourself
async function drawSsh(body) {
  const k = await get('/api/vault/fleetpilot');
  const keyRow = (label, value, help) => h('div', { class: 'fp-keyrow' }, h('div', { class: 'row' }, h('b', {}, label), iconBtn(I.copy, `Copy ${label}`, () => { navigator.clipboard?.writeText(value); toast('Copied'); })),
    h('pre', { class: 'fp-pubkey' }, value), h('p', { class: 'small muted' }, help));
  body.append(h('h2', { class: 'fp-sec' }, 'How FleetPilot logs in'),
    h('p', { class: 'muted small' }, 'The take-over logs in once with a password and leaves FleetPilot\'s key. Then it creates the user fleetpilot, trusts FleetPilot\'s user certificate authority and gives the host a host certificate. From then on every run logs in with a certificate that is valid for a few minutes only.'),
    keyRow('FleetPilot\'s public key', k.fleetKey, 'Left on a host by the first login, removed after the take-over when the workflow says so.'),
    keyRow('User certificate authority', k.userCa, 'Hosts trust it for logins (TrustedUserCAKeys). Put it on hosts you set up yourself to let FleetPilot in.'),
    keyRow('Host certificate authority', k.hostCa, 'Signs the host keys of managed hosts. Add it to your known_hosts with "@cert-authority * " in front, and SSH never asks about host keys again.'));
  if (!can('hosts', 'change')) return;
  const pub = h('textarea', { class: 'input mono fp-area', rows: 2, spellcheck: 'false', placeholder: 'ssh-ed25519 AAAA… you@laptop' });
  const hours = select([[1, '1 hour'], [4, '4 hours'], [8, '8 hours'], [24, '24 hours']], 8);
  const out = h('div', {});
  body.append(h('h2', { class: 'fp-sec' }, 'A certificate for yourself'),
    h('p', { class: 'muted small' }, `Log in to managed hosts with your own key: FleetPilot signs it for a few hours. You log in as the user of your host with the principal fp-${session.user.username}, when a template lets that principal in (Access, "Logins with SSH certificates").`),
    field('Your public key', pub), h('div', { class: 'row fp-assign' }, field('Valid for', hours), btn('Sign my key', 'key', async () => {
      const send = () => api.post('/api/vault/certificate', { publicKey: pub.value.trim(), hours: Number(hours.value) });
      let r;
      try { r = await send(); }
      catch (e) {
        if (e.code !== 'verify_needed') { toast(e.message); return; }
        if (!(await confirmFresh('Confirm that it is you'))) return;
        r = await call(send).catch(() => null);
      }
      if (!r) return;
      out.innerHTML = '';
      out.append(keyRow(`Your certificate (${r.hours} h, principal ${r.principal})`, r.certificate, 'Save it next to your key as id_ed25519-cert.pub (the name of the key with -cert.pub); SSH uses it on its own.'));
    }, 'primary')), out);
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/js/views"
  cat > "$W/js/views/template.js" <<'__FLEETPILOT_FILE_END__'
// FleetPilot: the template editor. Settings from the catalog, area by area, each a form; the
// playbook FleetPilot makes from them, live beside the forms; where the template applies, which
// hosts are behind, and pushing a new version to them; the versions and going back to one.
import { h, toast, contextMenu } from '../core/ui.js';
import { api } from '../core/api.js';
import { I } from '../icons.js';
import { main, meta, get, call, can, pageHead, btn, tabs, dialog, field, input, select, table, empty, when, plural, bands, hostState, renderFields, groupOptions } from '../common.js';

const clone = v => JSON.parse(JSON.stringify(v));

export async function viewTemplate(ctx, id) {
  const isNew = id === 'new';
  const t = isNew ? { name: '', description: '', definition: { settings: [] }, versions: [], current_version: 0, archived: false } : await get(`/api/templates/${id}`);
  document.title = isNew ? 'New template' : t.name;
  const mayChange = can('automation', 'change');
  const st = { def: clone(t.definition), name: t.name, description: t.description, dirty: false, restoredFrom: null };
  const page = h('div', { class: 'page fp-page-wide' });
  const saveBtn = btn(isNew ? 'Create the template' : 'Save a new version', 'save', () => save(), 'primary');
  const dirtyNote = h('span', { class: 'small muted fp-dirty' });
  const markDirty = () => { st.dirty = true; saveBtn.disabled = false; dirtyNote.textContent = st.restoredFrom ? `Changes from version ${st.restoredFrom}, not saved` : 'Changes not saved'; schedulePreview(); };
  saveBtn.disabled = !isNew;
  const before = e => { if (st.dirty) { e.preventDefault(); e.returnValue = ''; } };
  window.addEventListener('beforeunload', before);
  ctx.onLeave(() => window.removeEventListener('beforeunload', before));

  page.append(h('p', { class: 'fp-crumb small' }, h('a', { href: '#/automate/templates' }, 'Templates'), ' / '));
  page.append(pageHead(isNew ? 'New template' : t.name, isNew ? 'Pick the settings this template sets. FleetPilot writes the Ansible playbook for you.' : `Version ${t.current_version}${t.archived ? ' · archived' : ''} · ${t.description || 'No description'}`, mayChange ? [
    dirtyNote, saveBtn,
    !isNew ? btn('Duplicate', 'copy', async () => { const r = await call(() => api.post(`/api/templates/${t.id}/duplicate`, {})).catch(() => null); if (r) location.hash = `#/automate/template/${r.id}`; }) : null,
    !isNew ? btn(t.archived ? 'Restore' : 'Archive', '', async () => { await call(() => api.patch(`/api/templates/${t.id}`, { archived: !t.archived })); ctx.rerender(); }, 'ghost') : null,
    !isNew ? btn('Delete', 'trash', async () => {
      if (await dialog(`Delete ${t.name}`, [h('p', {}, 'The template and all its versions go. Hosts keep what was applied to them.')], { ok: 'Delete the template', okClass: 'danger', onOk: () => call(() => api.del(`/api/templates/${t.id}`)) })) { st.dirty = false; location.hash = '#/automate/templates'; }
    }, 'ghost') : null
  ].filter(Boolean) : []));

  // Name and description: always at hand
  const nameIn = input({ value: st.name, placeholder: 'Web server', disabled: !mayChange, oninput: e => { st.name = e.target.value; markDirty(); } });
  const descIn = input({ value: st.description, placeholder: 'What hosts with this template are for', disabled: !mayChange, oninput: e => { st.description = e.target.value; markDirty(); } });
  page.append(h('div', { class: 'fp-grid2 fp-tpl-names' }, field('Name', nameIn), field('Description', descIn)));

  const body = h('div', {});
  const tabList = [['settings', 'Settings'], ['playbook', 'Playbook'], ...(isNew ? [] : [['usage', 'Where it applies'], ['versions', `Versions (${t.versions.length})`]])];
  const tab = ctx.query.tab && tabList.some(x => x[0] === ctx.query.tab) ? ctx.query.tab : 'settings';
  page.append(tabs(tabList, tab, x => draw(x)), body);
  main.append(page);

  // ------------------------------------------------------------ The live playbook
  const pre = h('pre', {});
  const preBox = () => h('div', { class: 'console fp-yaml' }, pre);
  const previewNote = h('p', { class: 'small muted' });
  let timer = null, seq = 0;
  async function preview() {
    const n = ++seq;
    try {
      const r = await api.post('/api/templates/preview', { definition: st.def, name: st.name || 'Template' });
      if (n !== seq) return;
      pre.textContent = r.playbook; previewNote.textContent = 'Plain Ansible from ansible-core, made from the settings on the left.'; previewNote.classList.remove('fp-err');
    } catch (e) {
      if (n !== seq) return;
      previewNote.textContent = e.message; previewNote.classList.add('fp-err');
    }
  }
  function schedulePreview() { clearTimeout(timer); timer = setTimeout(preview, 450); }
  ctx.onLeave(() => clearTimeout(timer));

  const draw = async x => {
    body.innerHTML = '';
    if (x === 'playbook') { body.append(previewNote, preBox()); preview(); }
    else if (x === 'usage') await drawUsage(ctx, body, t);
    else if (x === 'versions') drawVersions(body, t, def => { st.def = clone(def.definition); st.restoredFrom = def.version; markDirty(); page.querySelector('[role=tab]')?.click(); toast(`Version ${def.version} is in the editor: save it to make it the newest`); });
    else {
      const editor = h('div', { class: 'fp-tpl-editor' });
      body.append(h('div', { class: 'fp-tpl' }, editor, h('aside', { class: 'fp-tpl-side' }, h('h4', {}, 'The playbook'), previewNote, preBox())));
      drawEditor(editor, st, mayChange, markDirty);
      preview();
    }
  };
  await draw(tab);

  async function save() {
    if (!st.name.trim()) { toast('Give the template a name.'); nameIn.focus(); return; }
    if (isNew) {
      const r = await call(() => api.post('/api/templates', { name: st.name, description: st.description, definition: st.def })).catch(() => null);
      if (!r) return;
      st.dirty = false; toast('Template created');
      location.hash = `#/automate/template/${r.id}?tab=usage`;
      return;
    }
    const usage = await get(`/api/templates/${t.id}/usage`).catch(() => ({ hosts: [] }));
    const managed = usage.hosts.filter(x => x.assigned && x.state === 'managed');
    const note = input({ placeholder: 'What changed, in a few words' });
    const push = h('input', { type: 'checkbox', checked: false });
    const r = await dialog(`Save version ${t.current_version + 1}`, [
      field('Note', note),
      managed.length && can('runs', 'run') ? h('label', { class: 'row small fp-check' }, push, `Apply the new version now to the ${plural(managed.length, 'managed host', 'managed hosts')} that use it`) : h('p', { class: 'small muted' }, 'No managed host uses this template yet.'),
      h('p', { class: 'small muted' }, 'Hosts keep the version they have until it is applied: by a run you start, a workflow, or the push on "Where it applies".')
    ], { ok: 'Save', onOk: () => call(() => api.post(`/api/templates/${t.id}/versions`, { definition: st.def, name: st.name, description: st.description, note: note.value })) });
    if (!r) return;
    st.dirty = false;
    toast(`Version ${r.version} saved`);
    if (push.checked) {
      const run = await call(() => api.post(`/api/templates/${t.id}/push`, { all: true })).catch(() => null);
      if (run?.id) { location.hash = `#/runs/${run.id}`; return; }
    }
    ctx.rerender();
  }
}

// ---------------------------------------------------------------- The settings, area by area
function drawEditor(el, st, mayChange, markDirty) {
  el.innerHTML = '';
  const list = st.def.settings;
  if (!list.length) el.append(h('div', { class: 'subcard fp-start' }, h('h2', {}, 'No settings yet'), h('p', { class: 'muted' }, 'Add what hosts with this template should have: users and keys, packages, a firewall, a web server, mounts, cron jobs and more. Each setting is a short form.')));
  for (const a of meta.catalog.areas) {
    const inArea = list.filter(s => meta.types.get(s.type)?.area === a.id);
    if (!inArea.length) continue;
    el.append(h('div', { class: 'fp-areahead' }, h('i', { class: `bg-${a.id}` }), h('h2', {}, a.title), h('span', { class: 'muted small' }, plural(inArea.length, 'setting', 'settings'))));
    for (const s of inArea) el.append(settingCard(s));
  }
  if (mayChange) el.append(addMenu());

  function settingCard(s) {
    const type = meta.types.get(s.type);
    const remove = () => {
      const i = list.indexOf(s); if (i < 0) return;
      list.splice(i, 1); markDirty(); drawEditor(el, st, mayChange, markDirty);
      toast(`${type.title} removed`);
    };
    const status = h('span', { class: `sect-status${s.off ? '' : ' on'}` }, s.off ? 'off' : 'on');
    const summary = h('summary', {}, h('span', { class: 'fp-sum-title' }, type.title), status);
    summary.addEventListener('contextmenu', e => { if (mayChange) contextMenu(e, [{ label: `Remove ${type.title}`, icon: I.trash, danger: true, onClick: remove }], type.title); });
    const off = h('input', { type: 'checkbox', checked: !!s.off, disabled: !mayChange, onchange: e => { if (e.target.checked) s.off = true; else delete s.off; status.textContent = s.off ? 'off' : 'on'; status.classList.toggle('on', !s.off); markDirty(); } });
    return h('details', { class: `sect fp-setting ar-${type.area}`, open: true }, summary,
      h('div', { class: 'sect-body' },
        h('p', { class: 'muted small' }, type.text),
        renderFields(type.fields, s.values, () => markDirty(), { readOnly: !mayChange }),
        mayChange ? h('div', { class: 'row fp-setting-foot' }, h('label', { class: 'row small fp-check' }, off, 'Leave out for now'), h('span', { class: 'grow' }), btn(`Remove ${type.title}`, 'trash', remove, 'ghost danger')) : null));
  }

  function addMenu() {
    const wrap = h('div', { class: 'features' });
    const menu = h('div', { class: 'featmenu fp-addmenu hidden' });
    const find = input({ type: 'search', placeholder: 'Find a setting: nginx, users, firewall …', 'aria-label': 'Find a setting' });
    const items = h('div', {});
    const used = new Set(list.map(s => s.type));
    const fill = () => {
      items.innerHTML = '';
      const q = find.value.trim().toLowerCase();
      for (const a of meta.catalog.areas) {
        const types = meta.catalog.types.filter(x => x.area === a.id && !used.has(x.id) && (!q || `${x.title} ${x.text} ${x.id}`.toLowerCase().includes(q)));
        if (!types.length) continue;
        items.append(h('div', { class: 'fp-addarea small' }, h('i', { class: `bg-${a.id}` }), a.title));
        for (const x of types) items.append(h('button', { type: 'button', class: `featitem ar-${a.id}`, onclick: () => add(x) }, h('b', {}, x.title), h('span', {}, x.text)));
      }
      if (!items.children.length) items.append(empty('Nothing matches, or every matching setting is in the template already.'));
    };
    const add = x => {
      list.push({ id: Math.random().toString(16).slice(2, 14), type: x.id, values: {} });
      markDirty(); drawEditor(el, st, mayChange, markDirty);
      const cards = el.querySelectorAll('.fp-setting');
      const card = [...cards].find(c => c.querySelector('.fp-sum-title')?.textContent === x.title);
      card?.scrollIntoView({ block: 'center', behavior: 'smooth' });
      card?.querySelector('input:not([type=checkbox]), select, textarea')?.focus({ preventScroll: true });
    };
    find.addEventListener('input', fill);
    menu.append(find, items);
    const open = h('button', { type: 'button', class: 'btn addfeat', html: `${I.plus}<span>Add a setting</span> <span class="small muted">users, packages, nginx, firewall, …</span>`, onclick: () => { menu.classList.toggle('hidden'); if (!menu.classList.contains('hidden')) { fill(); find.focus(); } } });
    wrap.append(open, menu);
    wrap.append(h('details', { class: 'fp-vars small' }, h('summary', {}, 'Variables you can use in texts'),
      h('p', { class: 'muted' }, 'FleetPilot fills these per host. Nothing else in a text is read as a variable.'),
      h('dl', { class: 'kv' }, meta.catalog.variables.flatMap(([k, d, ex]) => [h('dt', {}, `{{ ${k} }}`), h('dd', {}, `${d}, like ${ex}`)]))));
    return wrap;
  }
}

// ---------------------------------------------------------------- Where it applies
async function drawUsage(ctx, body, t) {
  const u = await get(`/api/templates/${t.id}/usage`);
  const mayAssign = can('hosts', 'change');
  body.append(h('h2', { class: 'fp-sec' }, 'Applies to'), h('p', { class: 'muted small' }, 'A template given to a site or group applies to every host inside. Settings of more specific templates win: site, then group, then the host itself.'));
  if (u.assignments.length) body.append(table(['Where', 'Version', ''], u.assignments.map(a => h('tr', {},
    h('td', {}, a.group_id ? h('a', { href: `#/hosts/group/${a.group_id}` }, `${a.group_kind === 'site' ? 'Site' : 'Group'} ${a.group_name}`) : h('a', { href: `#/hosts/${a.host_id}` }, `Host ${a.host_name}`)),
    h('td', {}, a.pinned_version ? `Stays at version ${a.pinned_version}` : 'Always the newest'),
    h('td', {}, mayAssign ? btn('Remove', '', async () => { await call(() => api.del(`/api/templates/${t.id}/assign/${a.id}`)); ctx.rerender(); }, 'ghost') : null)))));
  else body.append(empty('It applies nowhere yet.'));
  if (mayAssign) {
    const [groups, hosts] = await Promise.all([groupOptions(), get('/api/hosts')]);
    const target = select([['', 'Choose…'], ...groups.map(([v, n]) => [`g${v}`, n]), ...hosts.map(x => [`h${x.id}`, `Host ${x.name}`])], '');
    const pin = select([['', 'Always the newest version'], ...t.versions.map(v => [v.version, `Stay at version ${v.version}`])], '');
    body.append(h('div', { class: 'row fp-assign' }, field('Apply it to', target), field('Version', pin), btn('Apply it there', 'plus', async () => {
      if (!target.value) return toast('Choose a site, a group or a host.');
      const b = target.value.startsWith('g') ? { groupId: target.value.slice(1) } : { hostId: target.value.slice(1) };
      await call(() => api.post(`/api/templates/${t.id}/assign`, { ...b, pinnedVersion: pin.value || null }));
      toast('Applied'); ctx.rerender();
    })));
  }

  body.append(h('h2', { class: 'fp-sec' }, 'Hosts'));
  if (!u.hosts.length) { body.append(empty('No host uses this template yet.')); return; }
  const behind = u.hosts.filter(x => x.state === 'managed' && (x.applied_version ?? 0) < u.current);
  const picked = new Set();
  const mayRun = can('runs', 'run');
  body.append(h('p', { class: 'muted small' }, `The newest version is ${u.current}. ${behind.length ? `${plural(behind.length, 'managed host has', 'managed hosts have')} an older one or none yet.` : 'Every managed host has it.'}`));
  const push = async b => { const r = await call(() => api.post(`/api/templates/${t.id}/push`, b)).catch(() => null); if (r?.id) location.hash = `#/runs/${r.id}`; };
  if (mayRun) body.append(h('div', { class: 'row', style: { marginBottom: '10px' } },
    btn(`Push version ${u.current} to the hosts behind`, 'play', () => push({}), 'primary'),
    btn('Push to every host that uses it', 'play', () => push({ all: true })),
    btn('Push to the chosen hosts', 'play', () => (picked.size ? push({ hostIds: [...picked] }) : toast('Choose hosts in the table first.')))));
  body.append(table([mayRun ? '' : null, 'Host', 'State', 'Applied', 'Why it is here'].filter(x => x !== null), u.hosts.map(x => h('tr', {},
    mayRun ? h('td', {}, h('input', { type: 'checkbox', 'aria-label': `Choose ${x.name}`, disabled: x.state !== 'managed', onchange: e => (e.target.checked ? picked.add(x.id) : picked.delete(x.id)) })) : null,
    h('td', {}, h('a', { href: `#/hosts/${x.id}` }, x.name)), h('td', {}, hostState(x.state)),
    h('td', {}, x.applied_version ? h('span', { class: `fp-state ${x.applied_version < u.current ? 'wait' : 'ok'}` }, `Version ${x.applied_version}${x.applied_version < u.current ? ', behind' : ''}`) : h('span', { class: 'muted' }, 'Not yet'), x.applied_at ? h('span', { class: 'small muted' }, ` ${when(x.applied_at)}`) : null),
    h('td', { class: 'muted' }, x.assigned ? 'It applies to the host' : 'Used before: it no longer applies')))));
}

// ---------------------------------------------------------------- Versions
function drawVersions(body, t, restore) {
  const mayChange = can('automation', 'change');
  body.append(h('p', { class: 'muted small' }, 'Every save is a version. Look at the playbook of an older one, or bring it back into the editor and save it as the newest.'));
  body.append(table(['Version', 'Note', 'By', 'When', ''], t.versions.map(v => h('tr', {},
    h('td', {}, String(v.version), v.version === t.current_version ? h('span', { class: 'chip on', style: { marginLeft: '6px' } }, 'newest') : null),
    h('td', {}, v.note || '–'), h('td', {}, v.created_by || ''), h('td', { class: 'muted' }, when(v.created_at)),
    h('td', { class: 'fp-actions-cell' },
      btn('Playbook', 'doc', async () => { const x = await get(`/api/templates/${t.id}?version=${v.version}`); const p = h('pre', {}); p.textContent = x.playbook; await dialog(`${t.name}, version ${v.version}`, [h('div', { class: 'console fp-yaml' }, p)], { wide: true }); }, 'ghost'),
      mayChange && v.version !== t.current_version ? btn('Bring it back', 'reset', async () => { const x = await get(`/api/templates/${t.id}?version=${v.version}`); restore(x); }, 'ghost') : null)))));
}
