  cat > "$W/server/api/settings.mjs" <<'__FLEETPILOT_FILE_END__'
// FleetPilot API: settings of the installation (administrators).
//   GET /api/settings    PUT /api/settings
import { query } from '../core/db.mjs';
import { httpError } from '../core/http.mjs';
import { requireAdmin } from '../lib/auth.mjs';
import { record } from '../lib/audit.mjs';

export const DEFAULTS = {
  'runs.concurrency': 4,          // runs at the same time per FleetPilot server
  'runs.keep_days': 180,           // finished runs are removed after so many days
  'hosts.auto_takeover': false,    // reserved: take-over workflows with the trigger "host added" decide
  'network.live_check': true,      // probe an address before it is handed out
  'vault.reveal_minutes': 5        // how long a confirmation lasts for showing secrets
};
const RULES = {
  'runs.concurrency': v => Number.isInteger(v) && v >= 1 && v <= 64,
  'runs.keep_days': v => Number.isInteger(v) && v >= 7 && v <= 3650,
  'hosts.auto_takeover': v => typeof v === 'boolean',
  'network.live_check': v => typeof v === 'boolean',
  'vault.reveal_minutes': v => Number.isInteger(v) && v >= 1 && v <= 60
};

export async function getSetting(key) {
  const [r] = await query('select value from settings where key = $1', [key]);
  return r ? r.value : DEFAULTS[key];
}
export async function allSettings() {
  const rows = await query('select key, value from settings where key = any($1)', [Object.keys(DEFAULTS)]);
  return { ...DEFAULTS, ...Object.fromEntries(rows.map(r => [r.key, r.value])) };
}

export default function settings(app) {
  app.get('/api/settings', async ctx => { requireAdmin(ctx); return allSettings(); });
  app.put('/api/settings', async ctx => {
    requireAdmin(ctx);
    const b = ctx.body || {};
    for (const [k, v] of Object.entries(b)) {
      if (!(k in DEFAULTS)) continue;
      if (!RULES[k](v)) throw httpError(400, 'bad_value', `The value for ${k} is not possible.`);
      await query('insert into settings (key, value) values ($1, $2) on conflict (key) do update set value = $2, updated_at = now()', [k, JSON.stringify(v)]);
    }
    await record(ctx, 'settings.changed', { changes: b });
    return allSettings();
  });
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/server/api"
  cat > "$W/server/api/sources.mjs" <<'__FLEETPILOT_FILE_END__'
// FleetPilot API: hypervisors that list their machines (Proxmox VE).
//   GET /api/sources                          POST /api/sources { name, url, tokenId, token, verifyTls, fingerprint, groupId }
//   PATCH|DELETE /api/sources/:id             POST /api/sources/fingerprint { url }: the certificate to pin
//   POST /api/sources/:id/sync                reads the VMs now
//   GET /api/sources/:id/vms                  the VMs found, with the host each one is
//   POST /api/sources/:id/import              { vmIds, groupId, workflowId }: VMs become hosts
import { query } from '../core/db.mjs';
import { httpError } from '../core/http.mjs';
import { record } from '../lib/audit.mjs';
import { need } from '../lib/access.mjs';
import { createSecret, readSecret, updateSecret } from '../lib/vault.mjs';
import { fetchFingerprint, listVms } from '../lib/proxmox.mjs';
import { addHosts } from './hosts.mjs';
import { hostAdded, runWorkflow } from './workflows.mjs';

const isId = v => /^\d+$/.test(String(v ?? ''));
const str = (v, n) => String(v ?? '').trim().slice(0, n);
const COLS = 's.id::text, s.kind, s.name, s.url, s.token_id, s.verify_tls, s.fingerprint, s.group_id::text, s.last_sync_at, s.last_error, s.created_at, g.name as group_name';

async function load(id) {
  if (!isId(id)) throw httpError(404, 'not_found', 'There is no such source.');
  const [s] = await query('select * from sources where id = $1', [id]);
  if (!s) throw httpError(404, 'not_found', 'There is no such source.');
  return s;
}

/** Reads the VMs of a source and keeps them (also links them to hosts with the same name or address) */
export async function syncSource(s) {
  const secret = s.secret_id ? await readSecret(s.secret_id) : null;
  try {
    const vms = await listVms(s, secret?.data?.token || '');
    for (const v of vms) {
      await query(`insert into source_vms (source_id, external_id, node, name, type, status, ips, tags, os, seen_at) values ($1, $2, $3, $4, $5, $6, $7, $8, $9, now())
        on conflict (source_id, external_id) do update set node = $3, name = $4, type = $5, status = $6, ips = case when cardinality($7::text[]) > 0 then $7 else source_vms.ips end, tags = $8, os = case when $9 <> '' then $9 else source_vms.os end, seen_at = now()`,
      [s.id, v.externalId, v.node, v.name, v.type, v.status, v.ips, v.tags, v.os]);
    }
    await query(`update source_vms v set host_id = h.id from hosts h where v.source_id = $1 and v.host_id is null and (h.source_id = $1 and h.external_id = v.external_id or lower(h.name) = lower(v.name))`, [s.id]);
    // VMs that are gone from Proxmox are forgotten (their hosts stay)
    await query("delete from source_vms where source_id = $1 and seen_at < now() - interval '1 minute'", [s.id]);
    await query("update sources set last_sync_at = now(), last_error = '' where id = $1", [s.id]);
    return { vms: vms.length };
  } catch (e) {
    await query('update sources set last_error = $2 where id = $1', [s.id, e.message.slice(0, 500)]);
    throw httpError(502, 'source_failed', e.message);
  }
}

export default function sources(app) {
  app.get('/api/sources', async ctx => {
    await need(ctx, 'hosts', 'view');
    return query(`select ${COLS}, (select count(*)::int from source_vms v where v.source_id = s.id) as vms, (select count(*)::int from source_vms v where v.source_id = s.id and v.host_id is not null) as hosts
      from sources s left join groups g on g.id = s.group_id order by lower(s.name)`);
  });

  app.post('/api/sources/fingerprint', async ctx => {
    await need(ctx, 'hosts', 'manage');
    try { return { fingerprint: await fetchFingerprint(str(ctx.body?.url, 300)) }; }
    catch (e) { throw httpError(502, 'no_answer', `No certificate from that address: ${e.message}`); }
  });

  app.post('/api/sources', async ctx => {
    await need(ctx, 'hosts', 'manage');
    const b = ctx.body || {};
    const name = str(b.name, 80), url = str(b.url, 300).replace(/\/+$/, '');
    if (!name) throw httpError(400, 'name_missing', 'Give the source a name.');
    if (!/^https?:\/\/[A-Za-z0-9.:[\]-]+(:\d+)?$/.test(url)) throw httpError(400, 'bad_url', 'The address looks like https://pve.example.com:8006');
    if (!/^[A-Za-z0-9._@!-]+![A-Za-z0-9._-]+$/.test(str(b.tokenId, 200))) throw httpError(400, 'bad_token', 'The token id looks like fleetpilot@pve!inventory');
    if (!str(b.token, 200)) throw httpError(400, 'no_token', 'Give the secret of the token.');
    const secret = await createSecret({ scope: 'system', kind: 'token', name: `Proxmox token: ${name}`, username: str(b.tokenId, 200), data: { token: str(b.token, 200) }, by: ctx.user.username }).catch(e => { if (e.code === 'name_taken') throw httpError(409, 'name_taken', 'There is a source with this name already.'); throw e; });
    const rows = await query(`insert into sources (name, url, token_id, secret_id, verify_tls, fingerprint, group_id) values ($1, $2, $3, $4, $5, $6, $7) on conflict do nothing returning *`,
      [name, url, str(b.tokenId, 200), secret.id, b.verifyTls !== false, str(b.fingerprint, 200), isId(b.groupId) ? b.groupId : null]);
    if (!rows.length) { await query('delete from secrets where id = $1', [secret.id]); throw httpError(409, 'name_taken', 'There is a source with this name already.'); }
    await record(ctx, 'source.created', { target: { type: 'source', id: rows[0].id, name }, url });
    let sync = null;
    try { sync = await syncSource(rows[0]); } catch (e) { sync = { error: e.message }; }
    return { status: 201, body: { id: String(rows[0].id), sync } };
  });

  app.patch('/api/sources/:id', async ctx => {
    await need(ctx, 'hosts', 'manage');
    const s = await load(ctx.params.id);
    const b = ctx.body || {};
    const url = 'url' in b ? str(b.url, 300).replace(/\/+$/, '') : s.url;
    if (!/^https?:\/\/[A-Za-z0-9.:[\]-]+(:\d+)?$/.test(url)) throw httpError(400, 'bad_url', 'The address looks like https://pve.example.com:8006');
    await query('update sources set name = $2, url = $3, token_id = $4, verify_tls = $5, fingerprint = $6, group_id = $7, updated_at = now() where id = $1',
      [s.id, 'name' in b ? str(b.name, 80) || s.name : s.name, url, 'tokenId' in b ? str(b.tokenId, 200) : s.token_id, 'verifyTls' in b ? !!b.verifyTls : s.verify_tls, 'fingerprint' in b ? str(b.fingerprint, 200) : s.fingerprint, 'groupId' in b ? (isId(b.groupId) ? b.groupId : null) : s.group_id]);
    if (str(b.token, 200) && s.secret_id) await updateSecret(s.secret_id, { data: { token: str(b.token, 200) }, by: ctx.user.username, rotated: true });
    await record(ctx, 'source.changed', { target: { type: 'source', id: s.id, name: s.name }, changes: Object.keys(b).filter(k => k !== 'token') });
    return null;
  });

  app.del('/api/sources/:id', async ctx => {
    await need(ctx, 'hosts', 'manage');
    const s = await load(ctx.params.id);
    await query('delete from sources where id = $1', [s.id]);
    if (s.secret_id) await query('delete from secrets where id = $1', [s.secret_id]);
    await record(ctx, 'source.deleted', { target: { type: 'source', id: s.id, name: s.name } });
    return null;
  });

  app.post('/api/sources/:id/sync', async ctx => {
    await need(ctx, 'hosts', 'view');
    return syncSource(await load(ctx.params.id));
  });

  app.get('/api/sources/:id/vms', async ctx => {
    await need(ctx, 'hosts', 'view');
    const s = await load(ctx.params.id);
    return query(`select v.id::text, v.external_id, v.node, v.name, v.type, v.status, v.ips, v.tags, v.os, v.seen_at, v.host_id::text, h.name as host_name, h.state as host_state
      from source_vms v left join hosts h on h.id = v.host_id where v.source_id = $1 order by lower(v.name)`, [s.id]);
  });

  app.post('/api/sources/:id/import', async ctx => {
    const s = await load(ctx.params.id);
    const b = ctx.body || {};
    const groupId = isId(b.groupId) ? String(b.groupId) : s.group_id ? String(s.group_id) : null;
    await need(ctx, 'hosts', 'manage', groupId ?? undefined);
    const ids = (Array.isArray(b.vmIds) ? b.vmIds : []).filter(isId);
    const vms = await query('select * from source_vms where source_id = $1 and id = any($2::bigint[]) and host_id is null', [s.id, ids]);
    const list = [], skipped = [];
    for (const v of vms) {
      if (!v.ips.length) { skipped.push({ name: v.name, why: 'No address known: start the VM with the QEMU guest agent, or add it by its address.' }); continue; }
      list.push({ name: v.name.replace(/[^A-Za-z0-9._-]/g, '-').replace(/^[^A-Za-z0-9]+/, '').slice(0, 63) || `vm${v.external_id.split('/')[1]}`, address: v.ips[0], tags: v.tags.filter(t => /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(t)), sourceId: s.id, externalId: v.external_id });
    }
    const r = await addHosts(ctx, list, { groupId });
    await query('update source_vms v set host_id = h.id from hosts h where v.source_id = $1 and h.source_id = $1 and h.external_id = v.external_id and v.host_id is null', [s.id]);
    let run = null;
    if (r.added.length && isId(b.workflowId)) run = await runWorkflow(ctx, b.workflowId, r.added);
    else if (r.added.length) await hostAdded(r.added);
    return { added: r.added.length, skipped: [...skipped, ...r.skipped], run };
  });
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/server/api"
  cat > "$W/server/api/templates.mjs" <<'__FLEETPILOT_FILE_END__'
// FleetPilot API: templates (a desired configuration from forms) and where they apply.
//   GET /api/templates                       with counts of where they apply and hosts behind
//   GET /api/templates/:id?version=          one template, a version of it, its versions
//   POST /api/templates                      { name, description, definition }
//   POST /api/templates/:id/versions         { definition, note, name, description }: saves a new version
//   POST /api/templates/preview              { definition, name }: the playbook as YAML
//   PATCH /api/templates/:id                 { name, description, archived }
//   POST /api/templates/:id/duplicate        DELETE /api/templates/:id (only when used nowhere)
//   GET /api/templates/:id/usage             where it applies, which hosts have which version applied
//   POST /api/templates/:id/assign           { groupId | hostId, pinnedVersion }
//   DELETE /api/templates/:id/assign/:aid
//   POST /api/templates/:id/push             { hostIds | all }: applies the newest version to hosts
import { query, tx } from '../core/db.mjs';
import { httpError } from '../core/http.mjs';
import { record } from '../lib/audit.mjs';
import { need } from '../lib/access.mjs';
import { normalizeDefinition, previewPlaybook, TYPES } from '../lib/compile.mjs';
import { startRun } from '../lib/runner.mjs';
import { runWorkflow } from './workflows.mjs';

const isId = v => /^\d+$/.test(String(v ?? ''));
const str = (v, n) => String(v ?? '').trim().slice(0, n);

async function load(id) {
  if (!isId(id)) throw httpError(404, 'not_found', 'There is no such template.');
  const [t] = await query('select * from templates where id = $1', [id]);
  if (!t) throw httpError(404, 'not_found', 'There is no such template.');
  return t;
}

/** Vault entries referenced by a definition must exist; referencing needs the right to see the vault */
async function checkSecrets(ctx, def) {
  const ids = [];
  for (const s of def.settings) {
    const t = TYPES.get(s.type);
    for (const f of t.fields) {
      if (f.type === 'secret' && s.values[f.key]) ids.push(s.values[f.key]);
      if (f.type === 'rows') for (const c of f.columns.filter(c => c.type === 'secret')) for (const r of s.values[f.key]) if (r[c.key]) ids.push(r[c.key]);
    }
  }
  if (!ids.length) return;
  await need(ctx, 'vault', 'view');
  const found = await query("select id::text from secrets where id = any($1::bigint[]) and scope in ('global', 'group')", [ids]);
  const missing = ids.filter(i => !found.some(f => f.id === String(i)));
  if (missing.length) throw httpError(400, 'no_secret', 'A setting uses a vault entry that does not exist (or belongs to one host).');
}

/** Hosts that use a template: by assignment (their groups or themselves) and by what was applied */
async function hostsUsing(templateId) {
  return query(`with recursive inside(id) as (select group_id from assignments where template_id = $1 and group_id is not null
      union select g.id from groups g join inside on g.parent_id = inside.id)
    select h.id::text, h.name, h.state, h.group_id, ht.applied_version, ht.applied_at,
      (h.group_id in (select id from inside) or exists (select 1 from assignments a where a.template_id = $1 and a.host_id = h.id)) as assigned
    from hosts h left join host_templates ht on ht.host_id = h.id and ht.template_id = $1
    where h.group_id in (select id from inside) or exists (select 1 from assignments a where a.template_id = $1 and a.host_id = h.id) or ht.host_id is not null
    order by h.name`, [templateId]);
}

export default function templates(app) {
  app.get('/api/templates', async ctx => {
    await need(ctx, 'automation', 'view');
    return query(`select t.id::text, t.name, t.description, t.current_version, t.archived, t.updated_at, v.definition,
      (select count(*)::int from assignments a where a.template_id = t.id) as assignments,
      (select count(*)::int from host_templates ht where ht.template_id = t.id) as applied,
      (select count(*)::int from host_templates ht where ht.template_id = t.id and ht.applied_version < t.current_version) as behind
      from templates t left join template_versions v on v.template_id = t.id and v.version = t.current_version order by t.archived, lower(t.name)`);
  });

  app.get('/api/templates/:id', async ctx => {
    await need(ctx, 'automation', 'view');
    const t = await load(ctx.params.id);
    const version = isId(ctx.query.version) ? Number(ctx.query.version) : t.current_version;
    const [v] = await query('select * from template_versions where template_id = $1 and version = $2', [t.id, version]);
    const versions = await query('select version, note, created_by, created_at from template_versions where template_id = $1 order by version desc limit 100', [t.id]);
    return { ...t, id: String(t.id), version, definition: v?.definition || { settings: [] }, playbook: v?.playbook || '', note: v?.note || '', versions };
  });

  app.post('/api/templates/preview', async ctx => {
    await need(ctx, 'automation', 'view');
    const def = normalizeDefinition(ctx.body?.definition || {});
    return { playbook: previewPlaybook(def, str(ctx.body?.name, 80) || 'Template') };
  });

  app.post('/api/templates', async ctx => {
    await need(ctx, 'automation', 'change');
    const b = ctx.body || {};
    const name = str(b.name, 80);
    if (!name) throw httpError(400, 'name_missing', 'Give the template a name.');
    const def = normalizeDefinition(b.definition || { settings: [] });
    await checkSecrets(ctx, def);
    const t = await tx(async c => {
      const rows = (await c.query('insert into templates (name, description, current_version, created_by) values ($1, $2, 1, $3) on conflict do nothing returning *', [name, str(b.description, 1000), ctx.user.username])).rows;
      if (!rows.length) throw httpError(409, 'name_taken', 'There is a template with this name already.');
      await c.query('insert into template_versions (template_id, version, definition, playbook, note, created_by) values ($1, 1, $2, $3, $4, $5)', [rows[0].id, JSON.stringify(def), previewPlaybook(def, name), str(b.note, 200) || 'First version', ctx.user.username]);
      return rows[0];
    });
    await record(ctx, 'template.created', { target: { type: 'template', id: t.id, name } });
    return { status: 201, body: { ...t, id: String(t.id) } };
  });

  app.post('/api/templates/:id/versions', async ctx => {
    await need(ctx, 'automation', 'change');
    const t = await load(ctx.params.id);
    const b = ctx.body || {};
    const def = normalizeDefinition(b.definition || { settings: [] });
    await checkSecrets(ctx, def);
    const name = 'name' in b ? str(b.name, 80) : t.name;
    if (!name) throw httpError(400, 'name_missing', 'Give the template a name.');
    const v = await tx(async c => {
      const [cur] = (await c.query('select current_version from templates where id = $1 for update', [t.id])).rows;
      const next = cur.current_version + 1;
      try {
        await c.query('update templates set current_version = $2, name = $3, description = $4, updated_at = now() where id = $1', [t.id, next, name, 'description' in b ? str(b.description, 1000) : t.description]);
      } catch (e) { if (e.code === '23505') throw httpError(409, 'name_taken', 'There is a template with this name already.'); throw e; }
      await c.query('insert into template_versions (template_id, version, definition, playbook, note, created_by) values ($1, $2, $3, $4, $5, $6)', [t.id, next, JSON.stringify(def), previewPlaybook(def, name), str(b.note, 200), ctx.user.username]);
      return next;
    });
    await record(ctx, 'template.saved', { target: { type: 'template', id: t.id, name }, version: v, note: b.note });
    // Workflows triggered by "template changed" run on the hosts that use it
    const wfs = await query("select * from workflows where enabled and kind = 'maintain' and definition->'trigger'->>'type' = 'template_changed'");
    if (wfs.length) {
      const hosts = (await hostsUsing(t.id)).filter(h => h.assigned && h.state === 'managed').map(h => h.id);
      for (const wf of wfs) if (hosts.length) await startRun({ workflow: wf, hostIds: hosts, trigger: 'template_changed', params: { templateId: String(t.id) } }).catch(() => {});
    }
    return { version: v };
  });

  app.patch('/api/templates/:id', async ctx => {
    await need(ctx, 'automation', 'change');
    const t = await load(ctx.params.id);
    const b = ctx.body || {};
    try {
      await query('update templates set name = $2, description = $3, archived = $4, updated_at = now() where id = $1',
        [t.id, 'name' in b ? str(b.name, 80) || t.name : t.name, 'description' in b ? str(b.description, 1000) : t.description, 'archived' in b ? !!b.archived : t.archived]);
    } catch (e) { if (e.code === '23505') throw httpError(409, 'name_taken', 'There is a template with this name already.'); throw e; }
    await record(ctx, 'template.changed', { target: { type: 'template', id: t.id, name: b.name || t.name }, changes: Object.keys(b) });
    return null;
  });

  app.post('/api/templates/:id/duplicate', async ctx => {
    await need(ctx, 'automation', 'change');
    const t = await load(ctx.params.id);
    const [v] = await query('select definition from template_versions where template_id = $1 and version = $2', [t.id, t.current_version]);
    let name = `${t.name} (copy)`;
    for (let i = 2; (await query('select 1 from templates where lower(name) = lower($1)', [name])).length; i++) name = `${t.name} (copy ${i})`;
    const row = await tx(async c => {
      const [r] = (await c.query('insert into templates (name, description, current_version, created_by) values ($1, $2, 1, $3) returning id', [name.slice(0, 80), t.description, ctx.user.username])).rows;
      await c.query('insert into template_versions (template_id, version, definition, playbook, note, created_by) values ($1, 1, $2, $3, $4, $5)', [r.id, JSON.stringify(v.definition), previewPlaybook(v.definition, name), `Copy of ${t.name}`, ctx.user.username]);
      return r;
    });
    await record(ctx, 'template.created', { target: { type: 'template', id: row.id, name }, from: t.name });
    return { status: 201, body: { id: String(row.id), name } };
  });

  app.del('/api/templates/:id', async ctx => {
    await need(ctx, 'automation', 'change');
    const t = await load(ctx.params.id);
    const [u] = await query('select (select count(*)::int from assignments where template_id = $1) as a', [t.id]);
    if (u.a) throw httpError(409, 'in_use', `${t.name} still applies to ${u.a} groups or hosts. Remove it there first, or archive it.`);
    await query('delete from templates where id = $1', [t.id]);
    await record(ctx, 'template.deleted', { target: { type: 'template', id: t.id, name: t.name } });
    return null;
  });

  app.get('/api/templates/:id/usage', async ctx => {
    await need(ctx, 'automation', 'view');
    const t = await load(ctx.params.id);
    const assignments = await query(`select a.id::text, a.group_id::text, a.host_id::text, a.pinned_version, g.name as group_name, g.kind as group_kind, h.name as host_name
      from assignments a left join groups g on g.id = a.group_id left join hosts h on h.id = a.host_id where a.template_id = $1 order by g.name, h.name`, [t.id]);
    const hosts = (await hostsUsing(t.id)).map(h => ({ ...h, group_id: undefined }));
    return { current: t.current_version, assignments, hosts };
  });

  app.post('/api/templates/:id/assign', async ctx => {
    const t = await load(ctx.params.id);
    const b = ctx.body || {};
    const groupId = isId(b.groupId) ? String(b.groupId) : null, hostId = groupId ? null : isId(b.hostId) ? String(b.hostId) : null;
    if (!groupId && !hostId) throw httpError(400, 'no_target', 'Choose a site, a group or a host.');
    let targetName;
    if (groupId) { const [g] = await query('select name from groups where id = $1', [groupId]); if (!g) throw httpError(404, 'not_found', 'There is no such group.'); targetName = g.name; await need(ctx, 'hosts', 'change', groupId); }
    else { const [h] = await query('select name, group_id from hosts where id = $1', [hostId]); if (!h) throw httpError(404, 'not_found', 'There is no such host.'); targetName = h.name; await need(ctx, 'hosts', 'change', h.group_id ?? null); }
    const pinned = isId(b.pinnedVersion) ? Number(b.pinnedVersion) : null;
    await query(`insert into assignments (template_id, group_id, host_id, pinned_version, position) values ($1, $2, $3, $4,
      (select coalesce(max(position), 0) + 1 from assignments where group_id is not distinct from $2::bigint and host_id is not distinct from $3::bigint))
      on conflict (template_id, coalesce(group_id, 0), coalesce(host_id, 0)) do update set pinned_version = $4`, [t.id, groupId, hostId, pinned]);
    await record(ctx, 'template.assigned', { target: { type: groupId ? 'group' : 'host', id: groupId || hostId, name: targetName }, template: t.name, pinned });
    return null;
  });

  app.del('/api/templates/:id/assign/:aid', async ctx => {
    const t = await load(ctx.params.id);
    const [a] = await query('select a.*, g.name as gname, h.name as hname, h.group_id as hgroup from assignments a left join groups g on g.id = a.group_id left join hosts h on h.id = a.host_id where a.id = $1 and a.template_id = $2', [isId(ctx.params.aid) ? ctx.params.aid : 0, t.id]);
    if (!a) throw httpError(404, 'not_found', 'This template does not apply there.');
    await need(ctx, 'hosts', 'change', a.group_id ? String(a.group_id) : a.hgroup ?? null);
    await query('delete from assignments where id = $1', [a.id]);
    await record(ctx, 'template.unassigned', { target: { type: a.group_id ? 'group' : 'host', id: a.group_id || a.host_id, name: a.gname || a.hname }, template: t.name });
    return null;
  });

  app.post('/api/templates/:id/push', async ctx => {
    const t = await load(ctx.params.id);
    const b = ctx.body || {};
    const using = await hostsUsing(t.id);
    let ids = (Array.isArray(b.hostIds) ? b.hostIds.map(String) : using.filter(h => b.all || h.applied_version < t.current_version).map(h => h.id));
    ids = ids.filter(id => using.some(h => h.id === id && h.state === 'managed'));
    if (!ids.length) throw httpError(400, 'no_hosts', 'No managed host uses this template (or all have the newest version).');
    const [wf] = await query("select * from workflows where builtin = 'push'");
    if (!wf) throw httpError(500, 'no_workflow', 'The built-in workflow "Apply templates" is missing.');
    const def = { ...wf.definition, steps: [{ id: 'push', type: 'templates', values: { templates: [String(t.id)] }, onFailure: 'host', when: { tags: [], groups: [], os: '' } }] };
    const id = await runWorkflow(ctx, wf.id, ids, { name: `Push ${t.name} version ${t.current_version}`, definition: def, params: { templateId: String(t.id) } });
    return { status: 201, body: { id } };
  });
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/server/api"
  cat > "$W/server/api/vault.mjs" <<'__FLEETPILOT_FILE_END__'
// FleetPilot API: the vault.
//   GET /api/vault?scope=&host=&q=          entries (never their values)
//   POST /api/vault                         { scope, groupId, hostId, kind, name, username, data, generate }
//   GET /api/vault/:id                      one entry and its versions
//   PUT /api/vault/:id                      { name, username, data, generate }: a new version
//   POST /api/vault/:id/reveal              { version }: the values, after a fresh confirmation (recorded)
//   DELETE /api/vault/:id
//   GET /api/vault/fleetpilot               FleetPilot's public key and certificate authorities
//   POST /api/vault/certificate             { publicKey, hours }: a short-lived SSH certificate for yourself
import crypto from 'node:crypto';
import { query } from '../core/db.mjs';
import { httpError } from '../core/http.mjs';
import { record } from '../lib/audit.mjs';
import { requireFresh } from '../lib/auth.mjs';
import { accessOf, need } from '../lib/access.mjs';
import { KINDS, createSecret, generatePassword, readSecret, updateSecret, meta, unseal, userCa } from '../lib/vault.mjs';
import { fingerprint, signKey } from '../lib/ssh.mjs';
import { publicKeys } from '../lib/hostctx.mjs';
import { getSetting } from './settings.mjs';

const isId = v => /^\d+$/.test(String(v ?? ''));
const str = (v, n) => String(v ?? '').slice(0, n);

/** The values of an entry, checked per kind; public facts derived (fingerprints, expiry) */
async function shape(kind, b, prev = {}) {
  const d = b.data || {};
  const gen = b.generate ? generatePassword(Math.min(128, Math.max(12, Number(b.generate.length) || 24)), b.generate.symbols !== false) : null;
  switch (kind) {
    case 'login': return { data: { password: gen || str(d.password ?? prev.password ?? '', 500), becomePassword: str(d.becomePassword ?? prev.becomePassword ?? '', 500) }, pub: {} };
    case 'password': return { data: { password: gen || str(d.password ?? prev.password ?? '', 500) }, pub: {} };
    case 'token': return { data: { token: str(d.token ?? prev.token ?? '', 8000) }, pub: {} };
    case 'note': return { data: { text: str(d.text ?? prev.text ?? '', 20000) }, pub: {} };
    case 'ssh_key': {
      const privateKey = str(d.privateKey ?? prev.privateKey ?? '', 20000);
      if (privateKey && !/-----BEGIN [A-Z ]*PRIVATE KEY-----/.test(privateKey)) throw httpError(400, 'bad_key', 'This is not a private key (-----BEGIN … PRIVATE KEY-----).');
      const publicKey = str(d.publicKey ?? '', 4000).trim();
      return { data: { privateKey, ...(d.certificate ? { certificate: str(d.certificate, 8000) } : prev.certificate ? { certificate: prev.certificate } : {}) }, pub: publicKey ? { publicKey, fingerprint: await fingerprint(publicKey).catch(() => '') } : undefined };
    }
    case 'ssh_cert': return { data: { certificate: str(d.certificate ?? prev.certificate ?? '', 8000) }, pub: {} };
    case 'tls': {
      const certificate = str(d.certificate ?? prev.certificate ?? '', 40000).trim(), key = str(d.key ?? prev.key ?? '', 20000).trim();
      let pub = {};
      if (certificate) {
        try { const x = new crypto.X509Certificate(certificate); pub = { subject: x.subject.replace(/\n/g, ', '), validTo: new Date(x.validTo).toISOString(), names: x.subjectAltName || '' }; }
        catch { throw httpError(400, 'bad_certificate', 'The certificate is not a PEM certificate.'); }
      }
      return { data: { certificate, key }, pub };
    }
    default: throw httpError(400, 'bad_kind', 'This kind of secret does not exist.');
  }
}

async function load(ctx, id, level) {
  if (!isId(id)) throw httpError(404, 'not_found', 'There is no such secret.');
  const [s] = await query('select s.*, h.group_id as host_group, h.name as host_name, g.name as group_name from secrets s left join hosts h on h.id = s.host_id left join groups g on g.id = s.group_id where s.id = $1', [id]);
  if (!s) throw httpError(404, 'not_found', 'There is no such secret.');
  await need(ctx, 'vault', level, s.scope === 'host' ? s.host_group ?? null : s.scope === 'group' ? s.group_id : undefined);
  if (s.scope === 'system' && level === 'change') throw httpError(403, 'system', 'FleetPilot\'s own keys are made and kept by FleetPilot.');
  return s;
}

export default function vault(app) {
  app.get('/api/vault', async ctx => {
    await need(ctx, 'vault', 'view');
    const a = await accessOf(ctx);
    const s = a.scope('vault', 'view');
    const params = [], where = [];
    if (s !== null) { params.push([...s]); where.push(`(s.scope in ('global', 'system') or s.group_id = any($1::bigint[]) or h.group_id = any($1::bigint[]))`); }
    const add = (sql, v) => { params.push(v); where.push(sql.replace(/\?/g, `$${params.length}`)); };
    if (ctx.query.scope) add('s.scope = ?', String(ctx.query.scope));
    if (isId(ctx.query.host)) add('s.host_id = ?', ctx.query.host);
    if (ctx.query.kind) add('s.kind = ?', String(ctx.query.kind));
    if (ctx.query.q) add('(s.name ilike ? or s.username ilike ? or h.name ilike ?)', `%${String(ctx.query.q).slice(0, 80).replace(/[%_]/g, '')}%`);
    return (await query(`select s.id, s.scope, s.group_id, s.host_id, s.kind, s.name, s.username, s.public, s.version, s.created_by, s.created_at, s.updated_at, s.rotated_at, h.name as host_name, g.name as group_name
      from secrets s left join hosts h on h.id = s.host_id left join groups g on g.id = s.group_id ${where.length ? 'where ' + where.join(' and ') : ''}
      order by (s.scope = 'system'), s.scope, lower(coalesce(h.name, g.name, '')), lower(s.name) limit 2000`, params)).map(r => ({ ...meta(r), host_name: r.host_name, group_name: r.group_name }));
  });

  app.post('/api/vault', async ctx => {
    const b = ctx.body || {};
    const scope = ['global', 'group', 'host'].includes(b.scope) ? b.scope : 'global';
    const groupId = scope === 'group' && isId(b.groupId) ? String(b.groupId) : null;
    const hostId = scope === 'host' && isId(b.hostId) ? String(b.hostId) : null;
    if (scope === 'group' && !groupId) throw httpError(400, 'no_group', 'Choose the group.');
    if (scope === 'host' && !hostId) throw httpError(400, 'no_host', 'Choose the host.');
    let where;
    if (hostId) { const [h] = await query('select group_id from hosts where id = $1', [hostId]); if (!h) throw httpError(404, 'not_found', 'There is no such host.'); where = h.group_id ?? null; }
    await need(ctx, 'vault', 'change', hostId ? where : groupId ?? undefined);
    if (!(b.kind in KINDS)) throw httpError(400, 'bad_kind', 'Choose what kind of secret it is.');
    const name = str(b.name, 120).trim();
    if (!name) throw httpError(400, 'name_missing', 'Give the secret a name.');
    const { data, pub } = await shape(b.kind, b);
    const s = await createSecret({ scope, groupId, hostId, kind: b.kind, name, username: str(b.username, 120).trim(), data, pub: pub || {}, by: ctx.user.username });
    await record(ctx, 'secret.created', { target: { type: 'secret', id: s.id, name }, kind: b.kind, scope });
    return { status: 201, body: s };
  });

  app.get('/api/vault/fleetpilot', async ctx => {
    await need(ctx, 'hosts', 'view');
    return publicKeys();
  });

  app.post('/api/vault/certificate', async ctx => {
    await need(ctx, 'hosts', 'change');
    const pubKey = str(ctx.body?.publicKey, 4000).trim();
    if (!/^(ssh-ed25519|ecdsa-sha2-nistp\d+|ssh-rsa) [A-Za-z0-9+/=]+( .*)?$/.test(pubKey)) throw httpError(400, 'bad_key', 'Paste your public key (one line, ssh-ed25519 AAAA…).');
    const hours = Math.min(24, Math.max(1, Math.round(Number(ctx.body?.hours) || 1)));
    await requireFresh(ctx, await getSetting('vault.reveal_minutes'));
    const ca = await userCa();
    const certificate = await signKey({ caPrivateKey: ca.data.privateKey, publicKey: pubKey, identity: `${ctx.user.username}@fleetpilot`, principals: [`fp-${ctx.user.username}`], validity: `+${hours}h` });
    await record(ctx, 'ssh_certificate.issued', { target: { type: 'user', id: ctx.user.id, name: ctx.user.username }, hours });
    return { certificate, principal: `fp-${ctx.user.username}`, hours };
  });

  app.get('/api/vault/:id', async ctx => {
    const s = await load(ctx, ctx.params.id, 'view');
    const versions = await query('select version, created_by, created_at from secret_versions where secret_id = $1 order by version desc', [s.id]);
    return { ...meta(s), host_name: s.host_name, group_name: s.group_name, data: undefined, versions };
  });

  app.put('/api/vault/:id', async ctx => {
    const s = await load(ctx, ctx.params.id, 'change');
    const b = ctx.body || {};
    const prev = unseal(s.data);
    const { data, pub } = await shape(s.kind, b, prev);
    if ('name' in b && str(b.name, 120).trim() && str(b.name, 120).trim() !== s.name) {
      try { await query('update secrets set name = $2 where id = $1', [s.id, str(b.name, 120).trim()]); } catch (e) { if (e.code === '23505') throw httpError(409, 'name_taken', 'There is a secret with this name here already.'); throw e; }
    }
    const r = await updateSecret(s.id, { data, pub, username: 'username' in b ? str(b.username, 120).trim() : undefined, by: ctx.user.username, rotated: !!b.generate });
    await record(ctx, 'secret.changed', { target: { type: 'secret', id: s.id, name: s.name }, version: r.version });
    return r;
  });

  app.post('/api/vault/:id/reveal', async ctx => {
    const s = await load(ctx, ctx.params.id, 'reveal');
    if (s.scope === 'system' && !ctx.user.isAdmin) throw httpError(403, 'not_allowed', 'Only administrators can show FleetPilot\'s own keys.');
    await requireFresh(ctx, await getSetting('vault.reveal_minutes'));
    let data;
    const v = ctx.body?.version;
    if (isId(v) && Number(v) !== s.version) {
      const [old] = await query('select data from secret_versions where secret_id = $1 and version = $2', [s.id, v]);
      if (!old) throw httpError(404, 'not_found', 'There is no such version.');
      data = unseal(old.data);
    } else data = (await readSecret(s.id)).data;
    await record(ctx, 'secret.revealed', { target: { type: 'secret', id: s.id, name: s.host_name ? `${s.host_name}: ${s.name}` : s.name }, version: isId(v) ? Number(v) : s.version });
    return { username: s.username, ...data };
  });

  app.del('/api/vault/:id', async ctx => {
    const s = await load(ctx, ctx.params.id, 'change');
    const used = await query("select t.name from templates t join template_versions v on v.template_id = t.id and v.version = t.current_version where v.definition::text like $1", [`%"${s.id}"%`]);
    if (used.length) throw httpError(409, 'in_use', `The template ${used[0].name} uses this secret. Change the template first.`);
    await query('delete from secrets where id = $1', [s.id]);
    await record(ctx, 'secret.deleted', { target: { type: 'secret', id: s.id, name: s.name } });
    return null;
  });
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/server/api"
  cat > "$W/server/api/workflows.mjs" <<'__FLEETPILOT_FILE_END__'
// FleetPilot API: workflows (a trigger and steps) and starting them.
//   GET /api/workflows                  GET /api/workflows/:id (with versions)
//   POST /api/workflows                 { name, description, kind, definition }
//   PUT /api/workflows/:id              { name, description, definition, enabled }: a new version
//   DELETE /api/workflows/:id
//   POST /api/workflows/:id/duplicate
//   POST /api/workflows/:id/run         { hostIds | groupIds | tags, checkOnly }
//   POST /api/workflows/:id/targets     the hosts it would run on, without running
import { query, tx } from '../core/db.mjs';
import { httpError } from '../core/http.mjs';
import { record } from '../lib/audit.mjs';
import { jobs } from '../lib/jobs.mjs';
import { accessOf, need } from '../lib/access.mjs';
import { normalizeWorkflow, startRun } from '../lib/runner.mjs';
import { STEP_TYPES } from '../lib/steps.mjs';

const isId = v => /^\d+$/.test(String(v ?? ''));
const str = (v, n) => String(v ?? '').trim().slice(0, n);

export const describeSteps = def => (def.steps || []).map(s => {
  const t = STEP_TYPES.get(s.type);
  let sentence = '';
  try { sentence = t.describe(s.values); } catch { sentence = t.text; }
  return { ...s, title: t.title, area: t.area, sentence };
});

async function load(id) {
  if (!isId(id)) throw httpError(404, 'not_found', 'There is no such workflow.');
  const [w] = await query('select * from workflows where id = $1', [id]);
  if (!w) throw httpError(404, 'not_found', 'There is no such workflow.');
  return w;
}
const out = w => ({ ...w, id: String(w.id), steps: describeSteps(w.definition) });

/** Hosts in the target groups (and everything inside) or with the target tags; all hosts when none are set */
export async function resolveTargets(wf, { groupIds, tags } = {}) {
  const g = groupIds ?? wf.definition.targets?.groups ?? [], t = tags ?? wf.definition.targets?.tags ?? [];
  const states = wf.kind === 'takeover' ? ['new', 'failed', 'unreachable'] : ['managed', 'unreachable'];
  const rows = await query(`with recursive inside(id) as (select unnest($1::bigint[]) union select g.id from groups g join inside on g.parent_id = inside.id)
    select h.id::text from hosts h where h.state = any($3::text[]) and (
      (cardinality($1::bigint[]) = 0 and cardinality($2::text[]) = 0)
      or h.group_id in (select id from inside) or h.tags && $2::text[]) order by h.name`, [g, t, states]);
  return rows.map(r => r.id);
}

/** Every enabled workflow with a schedule becomes a job schedule (and the others none) */
export async function scheduleWorkflows() {
  const list = await query('select * from workflows');
  const want = new Set();
  for (const w of list) {
    if (w.enabled && w.definition.trigger?.type === 'schedule' && w.definition.trigger.cron) {
      want.add(`workflow-${w.id}`);
      await jobs.schedule(`workflow-${w.id}`, w.definition.trigger.cron, 'run.scheduled', { workflowId: String(w.id) });
    }
  }
  for (const s of await jobs.schedules()) if (s.name.startsWith('workflow-') && !want.has(s.name)) await jobs.unschedule(s.name);
}

/** New hosts start the take-over workflows that are triggered by "host added" and target them */
export async function hostAdded(hostIds) {
  const list = await query("select * from workflows where enabled and kind = 'takeover' and definition->'trigger'->>'type' = 'host_added'");
  for (const wf of list) {
    const targets = new Set(await resolveTargets(wf));
    const ids = hostIds.filter(id => targets.has(String(id)));
    if (ids.length) await startRun({ workflow: wf, hostIds: ids, trigger: 'host_added' }).catch(() => {});
  }
}

/** Starts a workflow on hosts for the user of the request, with an approval when their roles ask for one */
export async function runWorkflow(ctx, workflowId, hostIds, { checkOnly = false, params = {}, name, definition } = {}) {
  const wf = await load(workflowId);
  if (definition) wf.definition = definition;
  if (!wf.enabled) throw httpError(409, 'disabled', 'This workflow is switched off.');
  const a = await accessOf(ctx);
  const hosts = await query('select id, name, group_id from hosts where id = any($1::bigint[])', [hostIds]);
  if (!hosts.length) throw httpError(400, 'no_hosts', 'Choose at least one host.');
  for (const h of hosts) if (!a.can('runs', 'run', h.group_id ?? null)) throw httpError(403, 'not_allowed', `Your roles do not allow runs on ${h.name}.`);
  const needsApproval = hosts.some(h => a.needsApproval(h.group_id ?? null));
  return startRun({ workflow: wf, hostIds: hosts.map(h => h.id), ctx, checkOnly, needsApproval, params, name });
}

export default function workflows(app) {
  app.get('/api/workflows', async ctx => {
    await need(ctx, 'automation', 'view');
    const rows = await query(`select w.*, (select json_build_object('id', r.id::text, 'status', r.status, 'at', coalesce(r.finished_at, r.created_at)) from runs r where r.workflow_id = w.id order by r.id desc limit 1) as last_run,
      (select next_at from job_schedules where name = 'workflow-' || w.id) as next_at from workflows w order by w.kind desc, lower(w.name)`);
    return rows.map(out);
  });

  app.get('/api/workflows/:id', async ctx => {
    await need(ctx, 'automation', 'view');
    const w = await load(ctx.params.id);
    const versions = await query('select version, created_by, created_at from workflow_versions where workflow_id = $1 order by version desc limit 50', [w.id]);
    const [sched] = await query("select next_at from job_schedules where name = $1", [`workflow-${w.id}`]);
    return { ...out(w), versions, nextAt: sched?.next_at || null };
  });

  app.post('/api/workflows', async ctx => {
    await need(ctx, 'automation', 'change');
    const b = ctx.body || {};
    const name = str(b.name, 80);
    if (!name) throw httpError(400, 'name_missing', 'Give the workflow a name.');
    const kind = b.kind === 'takeover' ? 'takeover' : 'maintain';
    const def = normalizeWorkflow(kind, b.definition || { steps: kind === 'takeover' ? [{ type: 'connect', values: {} }, { type: 'enroll', values: {} }] : [{ type: 'apply', values: {} }] });
    const w = await tx(async c => {
      const rows = (await c.query('insert into workflows (name, description, kind, definition, created_by) values ($1, $2, $3, $4, $5) on conflict do nothing returning *', [name, str(b.description, 1000), kind, JSON.stringify(def), ctx.user.username])).rows;
      if (!rows.length) throw httpError(409, 'name_taken', 'There is a workflow with this name already.');
      await c.query('insert into workflow_versions (workflow_id, version, definition, created_by) values ($1, 1, $2, $3)', [rows[0].id, JSON.stringify(def), ctx.user.username]);
      return rows[0];
    });
    await scheduleWorkflows();
    await record(ctx, 'workflow.created', { target: { type: 'workflow', id: w.id, name } });
    return { status: 201, body: out(w) };
  });

  app.put('/api/workflows/:id', async ctx => {
    await need(ctx, 'automation', 'change');
    const w = await load(ctx.params.id);
    const b = ctx.body || {};
    const def = b.definition ? normalizeWorkflow(w.kind, b.definition) : w.definition;
    const name = 'name' in b ? str(b.name, 80) : w.name;
    if (!name) throw httpError(400, 'name_missing', 'Give the workflow a name.');
    const changed = JSON.stringify(def) !== JSON.stringify(w.definition);
    const row = await tx(async c => {
      let r;
      try {
        r = (await c.query('update workflows set name = $2, description = $3, definition = $4, enabled = $5, version = version + $6, updated_at = now() where id = $1 returning *',
          [w.id, name, 'description' in b ? str(b.description, 1000) : w.description, JSON.stringify(def), 'enabled' in b ? !!b.enabled : w.enabled, changed ? 1 : 0])).rows[0];
      } catch (e) { if (e.code === '23505') throw httpError(409, 'name_taken', 'There is a workflow with this name already.'); throw e; }
      if (changed) await c.query('insert into workflow_versions (workflow_id, version, definition, created_by) values ($1, $2, $3, $4)', [w.id, r.version, JSON.stringify(def), ctx.user.username]);
      return r;
    });
    await scheduleWorkflows();
    await record(ctx, 'workflow.changed', { target: { type: 'workflow', id: w.id, name }, version: row.version });
    return out(row);
  });

  app.post('/api/workflows/:id/duplicate', async ctx => {
    await need(ctx, 'automation', 'change');
    const w = await load(ctx.params.id);
    let name = `${w.name} (copy)`;
    for (let i = 2; (await query('select 1 from workflows where lower(name) = lower($1)', [name])).length; i++) name = `${w.name} (copy ${i})`;
    const row = await tx(async c => {
      const [r] = (await c.query('insert into workflows (name, description, kind, definition, enabled, created_by) values ($1, $2, $3, $4, false, $5) returning *', [name.slice(0, 80), w.description, w.kind, JSON.stringify(w.definition), ctx.user.username])).rows;
      await c.query('insert into workflow_versions (workflow_id, version, definition, created_by) values ($1, 1, $2, $3)', [r.id, JSON.stringify(w.definition), ctx.user.username]);
      return r;
    });
    await record(ctx, 'workflow.created', { target: { type: 'workflow', id: row.id, name }, from: w.name });
    return { status: 201, body: out(row) };
  });

  app.del('/api/workflows/:id', async ctx => {
    await need(ctx, 'automation', 'change');
    const w = await load(ctx.params.id);
    if (w.builtin) throw httpError(409, 'builtin', 'Built-in workflows can be changed or switched off, not deleted.');
    await query('delete from workflows where id = $1', [w.id]);
    await scheduleWorkflows();
    await record(ctx, 'workflow.deleted', { target: { type: 'workflow', id: w.id, name: w.name } });
    return null;
  });

  app.post('/api/workflows/:id/targets', async ctx => {
    await need(ctx, 'automation', 'view');
    const w = await load(ctx.params.id);
    const ids = await resolveTargets(w, { groupIds: ctx.body?.groupIds, tags: ctx.body?.tags });
    return query('select id::text, name, state from hosts where id = any($1::bigint[]) order by name', [ids]);
  });

  app.post('/api/workflows/:id/run', async ctx => {
    const w = await load(ctx.params.id);
    const b = ctx.body || {};
    let ids = (Array.isArray(b.hostIds) ? b.hostIds : []).filter(isId);
    if (!ids.length && (b.groupIds?.length || b.tags?.length || b.targets)) ids = await resolveTargets(w, { groupIds: (b.groupIds || []).filter(isId), tags: b.tags || [] });
    const id = await runWorkflow(ctx, w.id, ids, { checkOnly: !!b.checkOnly });
    return { status: 201, body: { id } };
  });
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/server/core"
  cat > "$W/server/core/config.mjs" <<'__FLEETPILOT_FILE_END__'
// Configuration of the app server (blueprint 1.1.1): only environment variables,
// all named FLEETPILOT_*, the same in every deployment (installer, Docker, Kubernetes).
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const env = (k, d) => (process.env[`FLEETPILOT_${k}`] ?? '').trim() || d;

function canonical() {
  const v = env('CANONICAL', '').replace(/\/$/, '');
  if (v && !/^https?:\/\/[A-Za-z0-9.-]+(:\d{1,5})?$/.test(v)) {
    console.error(`fleetpilot: ignoring FLEETPILOT_CANONICAL='${v}' (expected e.g. https://fleetpilot.example.com, without a path)`);
    return '';
  }
  return v;
}

export const config = {
  appId: 'fleetpilot',
  appName: 'FleetPilot',
  databaseUrl: env('DATABASE_URL', ''),
  host: env('HOST', ''),                 // empty: every address (IPv6 and IPv4 where available)
  port: Number(env('PORT', '8080')),
  webDir: path.resolve(env('WEB_DIR', path.join(HERE, '..', '..', 'src'))),
  version: env('VERSION', 'dev'),
  canonical: canonical(),
  logLevel: env('LOG_LEVEL', 'info'),
  bodyLimit: 1024 * 1024                 // JSON request bodies: at most 1 MB
};
__FLEETPILOT_FILE_END__
  mkdir -p "$W/server/core"
  cat > "$W/server/core/db.mjs" <<'__FLEETPILOT_FILE_END__'
// PostgreSQL for the app server (blueprint 1.1.1).
//   query(sql, params)   one statement, returns the rows
//   tx(async c => …)     several statements in one transaction (c.query(…))
// Migrations: server/migrations/NNNN_name.sql, applied in order at start, each in its own
// transaction, with an advisory lock so that replicas starting together never collide.
// Library elements bring their own (server/migrations-lib/<element>/NNNN_name.sql): they run
// first, numbered per element, recorded in schema_migrations_lib.
// A migration is never changed or removed once released; the database only ever grows.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import pg from 'pg';
import { config } from './config.mjs';
import { log } from './log.mjs';

const MIGRATIONS = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'migrations');
const LIB_MIGRATIONS = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'migrations-lib');
const LOCK = 7_244_018_301;   // advisory lock id for migrations
export let pool = null;

export async function connect({ url = config.databaseUrl, waitSeconds = 60 } = {}) {
  if (!url) throw new Error('FLEETPILOT_DATABASE_URL is not set (postgres://user:password@host:5432/fleetpilot)');
  pool = new pg.Pool({ connectionString: url, max: 10, idleTimeoutMillis: 30_000 });
  pool.on('error', e => log.error('database connection lost', { error: e.message }));
  // The database may still be starting (Compose, Kubernetes): try for a while
  for (let i = 0; ; i++) {
    try { await pool.query('select 1'); break; }
    catch (e) {
      if (i >= waitSeconds) throw new Error(`Cannot reach the database: ${e.message}`);
      if (i % 10 === 0) log.warn('waiting for the database', { error: e.message });
      await new Promise(r => setTimeout(r, 1000));
    }
  }
  return pool;
}

export const query = async (sql, params = []) => (await pool.query(sql, params)).rows;

export async function tx(fn) {
  const c = await pool.connect();
  try {
    await c.query('begin');
    const r = await fn(c);
    await c.query('commit');
    return r;
  } catch (e) { await c.query('rollback').catch(() => {}); throw e; }
  finally { c.release(); }
}

export function migrationFiles(dir = MIGRATIONS) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).filter(f => /^\d{4}_[a-z0-9_]+\.sql$/.test(f)).sort()
    .map(f => ({ version: Number(f.slice(0, 4)), name: f.slice(5, -4), file: path.join(dir, f) }));
}

/** The migrations of the library elements: { element: [files] } */
export function libraryMigrationFiles(dir = LIB_MIGRATIONS) {
  if (!fs.existsSync(dir)) return {};
  return Object.fromEntries(fs.readdirSync(dir).sort().filter(e => fs.statSync(path.join(dir, e)).isDirectory()).map(e => [e, migrationFiles(path.join(dir, e))]));
}

async function migrateLibrary(c, dir) {
  const lib = libraryMigrationFiles(dir);
  if (!Object.keys(lib).length) return;
  await c.query('create table if not exists schema_migrations_lib (element text not null, version integer not null, name text not null, applied_at timestamptz not null default now(), primary key (element, version))');
  for (const [element, files] of Object.entries(lib)) {
    const done = new Set((await c.query('select version from schema_migrations_lib where element = $1', [element])).rows.map(r => r.version));
    const newest = Math.max(0, ...done), known = Math.max(0, ...files.map(f => f.version));
    if (newest > known) throw new Error(`The database is newer than this version of FleetPilot (library element ${element}: migration ${newest}, this version knows ${known}). Run the newer version again.`);
    for (const m of files.filter(f => !done.has(f.version))) {
      await c.query('begin');
      try {
        await c.query(fs.readFileSync(m.file, 'utf8'));
        await c.query('insert into schema_migrations_lib (element, version, name) values ($1, $2, $3)', [element, m.version, m.name]);
        await c.query('commit');
        log.info('migration applied', { element, version: m.version, name: m.name });
      } catch (e) { await c.query('rollback'); throw new Error(`Migration ${m.version} (${m.name}) of ${element} failed: ${e.message}`); }
    }
  }
}

export async function migrate(dir = MIGRATIONS, libDir = LIB_MIGRATIONS) {
  const files = migrationFiles(dir);
  const c = await pool.connect();
  try {
    await c.query('select pg_advisory_lock($1)', [LOCK]);
    await migrateLibrary(c, libDir);
    await c.query('create table if not exists schema_migrations (version integer primary key, name text not null, applied_at timestamptz not null default now())');
    const done = new Set((await c.query('select version from schema_migrations')).rows.map(r => r.version));
    const newest = Math.max(0, ...done), known = Math.max(0, ...files.map(f => f.version));
    if (newest > known) throw new Error(`The database is newer than this version of FleetPilot (migration ${newest}, this version knows ${known}). Run the newer version again; never go back over a migrated database.`);
    for (const m of files.filter(f => !done.has(f.version))) {
      await c.query('begin');
      try {
        await c.query(fs.readFileSync(m.file, 'utf8'));
        await c.query('insert into schema_migrations (version, name) values ($1, $2)', [m.version, m.name]);
        await c.query('commit');
        log.info('migration applied', { version: m.version, name: m.name });
      } catch (e) { await c.query('rollback'); throw new Error(`Migration ${m.version} (${m.name}) failed: ${e.message}`); }
    }
  } finally {
    await c.query('select pg_advisory_unlock($1)', [LOCK]).catch(() => {});
    c.release();
  }
}

export async function close() { await pool?.end(); pool = null; }
