// Library element "auth" (blueprint 1.1.1): sign-in and accounts.
// Passwords hashed with scrypt, sessions in PostgreSQL behind an HttpOnly cookie, a password
// policy, two-factor sign-in with TOTP and recovery codes, lockouts and rate limits, and the
// first administrator created with a setup code. See .blueprint/library/auth/README.md.
//
//   import { auth, requireAdmin, requireFresh } from './lib/auth.mjs'
//   await start({ routes: [auth({ onEvent, encrypt, decrypt, policy: { totp: 'admins' } }), items] })
//
// Every /api/ route needs a signed-in user (ctx.user) except the sign-in routes themselves and the
// paths given as `open`. Users who must change their password or set up two-factor sign-in first
// only reach /api/auth/.
import crypto from 'node:crypto';
import { promisify } from 'node:util';
import { query, tx } from '../core/db.mjs';
import { httpError } from '../core/http.mjs';
import { config } from '../core/config.mjs';
import { log } from '../core/log.mjs';

const scrypt = promisify(crypto.scrypt);
const COOKIE = `${config.appId}_session`;

// ---------------------------------------------------------------- Policy
export const DEFAULT_POLICY = {
  minLength: 12,          // characters
  requireLower: false,
  requireUpper: false,
  requireDigit: false,
  requireSymbol: false,
  blockCommon: true,      // refuse well-known passwords and the user name inside the password
  history: 5,             // the last n passwords cannot be used again (0: off)
  maxAgeDays: 0,          // a password must be changed after n days (0: never)
  totp: 'none',           // two-factor sign-in required for: 'none', 'admins' or 'all'
  sessionIdleMinutes: 60, // signed out after so long without a request
  sessionMaxHours: 12,    // signed out after so long in any case
  lockoutAttempts: 5,     // wrong passwords in a row before the account waits
  lockoutMinutes: 15
};
const LIMITS = {
  minLength: [8, 128], history: [0, 24], maxAgeDays: [0, 3650], sessionIdleMinutes: [5, 1440],
  sessionMaxHours: [1, 720], lockoutAttempts: [3, 50], lockoutMinutes: [1, 1440]
};
let defaults = { ...DEFAULT_POLICY };
let cached = null;   // { at, policy }: read at most every 10 seconds

/** The policy in force: the stored one over the app's defaults over the blueprint's */
export async function getPolicy() {
  if (cached && Date.now() - cached.at < 10_000) return cached.policy;
  const [row] = await query('select policy from auth_settings where id = 1');
  cached = { at: Date.now(), policy: normalizePolicy({ ...defaults, ...(row?.policy || {}) }) };
  return cached.policy;
}
export function normalizePolicy(p) {
  const out = { ...DEFAULT_POLICY };
  for (const k of Object.keys(DEFAULT_POLICY)) {
    if (!(k in p)) continue;
    const d = DEFAULT_POLICY[k];
    if (typeof d === 'boolean') out[k] = !!p[k];
    else if (typeof d === 'number') { const [lo, hi] = LIMITS[k]; const v = Math.round(Number(p[k])); out[k] = Number.isFinite(v) ? Math.min(hi, Math.max(lo, v)) : d; }
    else if (k === 'totp') out[k] = ['none', 'admins', 'all'].includes(p[k]) ? p[k] : d;
  }
  return out;
}

// Well-known passwords (the most used ones of the public leak lists); longer ones are caught by the
// patterns in passwordProblems()
const COMMON = new Set(`password password1 password12 password123 password1234 passw0rd p@ssw0rd p@ssword
123456789012 1234567890 12345678 123456789 1234567 qwertyuiop qwerty123 qwerty1234 qwertz123
1q2w3e4r5t6y 1qaz2wsx3edc zaq12wsx iloveyou123 letmein123 welcome123 welcome1234 admin123 admin1234
administrator changeme changeme123 sunshine123 football123 baseball123 dragon123 monkey123 master123
trustno1 princess123 starwars123 superman123 batman123 abc123456789 abcdefghijkl 111111111111
000000000000 aaaaaaaaaaaa secret123 default123 root1234 toor1234 test12345678 summer2024 winter2024
spring2024 autumn2024 summer2025 winter2025 summer2026 winter2026 company123 hallo12345678
passwort passwort123 geheim123 qwerasdfzxcv asdfghjkl123 zxcvbnm12345 mustang123 shadow123
michael123 jennifer123 hunter2hunter2`.split(/\s+/));

/** What is wrong with a new password, as sentences (empty when it is fine) */
export function passwordProblems(pw, policy, { username = '', name = '' } = {}) {
  const p = [];
  const s = String(pw || '');
  if ([...s].length < policy.minLength) p.push(`Use at least ${policy.minLength} characters.`);
  if ([...s].length > 256) p.push('Use at most 256 characters.');
  if (policy.requireLower && !/\p{Ll}/u.test(s)) p.push('Use at least one lowercase letter.');
  if (policy.requireUpper && !/\p{Lu}/u.test(s)) p.push('Use at least one uppercase letter.');
  if (policy.requireDigit && !/\d/.test(s)) p.push('Use at least one digit.');
  if (policy.requireSymbol && !/[^\p{L}\d]/u.test(s)) p.push('Use at least one character that is not a letter or digit.');
  if (policy.blockCommon) {
    const low = s.toLowerCase();
    const plain = low.replace(/[^a-z0-9]/g, '');
    if (COMMON.has(low) || COMMON.has(plain)) p.push('This password is on the lists of well-known passwords.');
    else if (new Set(low).size < 5 || '01234567890123456789abcdefghijklmnopqrstuvwxyzqwertyuiopasdfghjklzxcvbnm'.includes(low)) p.push('This password is too easy to guess.');
    else if (username && username.length >= 3 && low.includes(username.toLowerCase())) p.push('Do not use your user name in the password.');
    else if (name && name.length >= 4 && name.split(/\s+/).some(w => w.length >= 4 && low.includes(w.toLowerCase()))) p.push('Do not use your name in the password.');
  }
  return p;
}

// ---------------------------------------------------------------- Passwords
const N = 32768, R = 8, P = 1;
export async function hashPassword(pw) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(String(pw).normalize('NFKC'), salt, 32, { N, r: R, p: P, maxmem: 128 * N * R * 2 });
  return `scrypt$${N}$${R}$${P}$${salt.toString('base64')}$${key.toString('base64')}`;
}
export async function verifyPassword(pw, stored) {
  const [kind, n, r, p, salt, hash] = String(stored || '').split('$');
  if (kind !== 'scrypt') return false;
  const want = Buffer.from(hash, 'base64');
  const key = await scrypt(String(pw).normalize('NFKC'), Buffer.from(salt, 'base64'), want.length, { N: +n, r: +r, p: +p, maxmem: 128 * +n * +r * 2 });
  return crypto.timingSafeEqual(key, want);
}
// Same work for unknown users as for known ones: no hint from the answer time
const DUMMY = hashPassword(crypto.randomBytes(16).toString('hex'));

/** A readable random password: 4 groups of 5 letters and digits (about 100 bits) */
export function randomPassword() {
  const abc = 'abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  const pick = () => abc[crypto.randomInt(abc.length)];
  return Array.from({ length: 4 }, () => Array.from({ length: 5 }, pick).join('')).join('-');
}

// ---------------------------------------------------------------- TOTP (RFC 6238: SHA-1, 6 digits, 30 s)
const B32 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
export function base32(buf) {
  let bits = 0, value = 0, out = '';
  for (const b of buf) { value = (value << 8) | b; bits += 8; while (bits >= 5) { out += B32[(value >>> (bits - 5)) & 31]; bits -= 5; } }
  if (bits > 0) out += B32[(value << (5 - bits)) & 31];
  return out;
}
export function unbase32(s) {
  let bits = 0, value = 0; const out = [];
  for (const ch of String(s).toUpperCase().replace(/[^A-Z2-7]/g, '')) { value = (value << 5) | B32.indexOf(ch); bits += 5; if (bits >= 8) { out.push((value >>> (bits - 8)) & 255); bits -= 8; } }
  return Buffer.from(out);
}
export function totpCode(secret, counter) {
  const msg = Buffer.alloc(8);
  msg.writeBigUInt64BE(BigInt(counter));
  const h = crypto.createHmac('sha1', unbase32(secret)).update(msg).digest();
  const o = h[h.length - 1] & 15;
  return String(((h.readUInt32BE(o) & 0x7fffffff) % 1_000_000)).padStart(6, '0');
}
export const totpCounter = (t = Date.now()) => Math.floor(t / 30_000);
/** The counter of a valid code (one step of clock drift either way), or 0 */
export function totpMatch(secret, code, now = Date.now()) {
  const c = String(code || '').replace(/\s/g, '');
  if (!/^\d{6}$/.test(c)) return 0;
  for (const d of [0, -1, 1]) {
    const counter = totpCounter(now) + d;
    if (counter < 1) continue;
    if (crypto.timingSafeEqual(Buffer.from(totpCode(secret, counter)), Buffer.from(c))) return counter;
  }
  return 0;
}

// ---------------------------------------------------------------- Helpers
const sha = s => crypto.createHash('sha256').update(s).digest('hex');
let hooks = { onEvent: null, encrypt: s => s, decrypt: s => s };
const event = (ctx, action, details = {}) => { try { hooks.onEvent?.(ctx, action, details); } catch (e) { log.warn('auth event hook failed', { error: e.message }); } };

function cookies(req) {
  return Object.fromEntries(String(req.headers.cookie || '').split(';').map(c => c.trim().split('=')).filter(p => p.length === 2).map(([k, v]) => [k, decodeURIComponent(v)]));
}
const isHttps = req => req.socket.encrypted || req.headers['x-forwarded-proto'] === 'https' || config.canonical.startsWith('https:');
function setCookie(ctx, value, maxAgeSeconds) {
  ctx.res.setHeader('Set-Cookie', `${COOKIE}=${value}; Path=/; HttpOnly; SameSite=Lax${isHttps(ctx.req) ? '; Secure' : ''}; Max-Age=${maxAgeSeconds}`);
}

/** What a user may see of an account */
export const publicUser = u => ({
  id: String(u.id), username: u.username, name: u.name, email: u.email, isAdmin: u.is_admin, disabled: u.disabled,
  totpEnabled: u.totp_enabled, mustChangePassword: u.must_change_password, lastLoginAt: u.last_login_at, createdAt: u.created_at,
  locked: !!(u.locked_until && new Date(u.locked_until) > new Date())
});
const USER_COLS = 'id, username, name, email, is_admin, disabled, totp_enabled, must_change_password, last_login_at, created_at, locked_until, password_changed_at';

/** What a signed-in user still has to do before using the app: 'password', 'totp' */
function pending(u, policy) {
  const out = [];
  const aged = policy.maxAgeDays > 0 && Date.now() - new Date(u.password_changed_at).getTime() > policy.maxAgeDays * 864e5;
  if (u.must_change_password || aged) out.push('password');
  if (!u.totp_enabled && (policy.totp === 'all' || (policy.totp === 'admins' && u.is_admin))) out.push('totp');
  return out;
}

async function newSession(ctx, userId, policy, { verified = true } = {}) {
  const token = crypto.randomBytes(32).toString('base64url');
  await query(`insert into auth_sessions (token_hash, user_id, expires_at, ip, user_agent, verified_at)
    values ($1, $2, now() + make_interval(hours => $3), $4, $5, ${verified ? 'now()' : 'null'})`,
  [sha(token), userId, policy.sessionMaxHours, ctx.clientIp || '', String(ctx.req.headers['user-agent'] || '').slice(0, 200)]);
  setCookie(ctx, token, policy.sessionMaxHours * 3600);
}

/** The session of a request: { session, user } or null */
async function findSession(ctx, policy) {
  const token = cookies(ctx.req)[COOKIE];
  if (!token || token.length > 100) return null;
  const [row] = await query(`select s.id as session_id, s.last_seen_at, s.verified_at, u.* from auth_sessions s join auth_users u on u.id = s.user_id
    where s.token_hash = $1 and s.expires_at > now() and s.last_seen_at > now() - make_interval(mins => $2) and not u.disabled`, [sha(token), policy.sessionIdleMinutes]);
  if (!row) return null;
  if (Date.now() - new Date(row.last_seen_at).getTime() > 30_000) await query('update auth_sessions set last_seen_at = now() where id = $1', [row.session_id]);
  return row;
}

export function requireUser(ctx) { if (!ctx.user) throw httpError(401, 'signed_out', 'Sign in first.'); return ctx.user; }
export function requireAdmin(ctx) {
  requireUser(ctx);
  if (!ctx.user.isAdmin) throw httpError(403, 'not_allowed', 'Only administrators can do this.');
  return ctx.user;
}
/** For sensitive actions: the user proved who they are (password or two-factor code) within the last minutes */
export async function requireFresh(ctx, minutes = 5) {
  requireUser(ctx);
  const [s] = await query('select verified_at from auth_sessions where id = $1', [ctx.user.sessionId]);
  if (!s?.verified_at || Date.now() - new Date(s.verified_at).getTime() > minutes * 60_000) {
    throw httpError(403, 'verify_needed', ctx.user.totpEnabled ? 'Confirm with a code from your authenticator app.' : 'Confirm with your password.');
  }
}

async function limitedIp(ip) {
  const [r] = await query("select count(*)::int as n from auth_attempts where ip = $1 and not ok and at > now() - interval '15 minutes'", [ip]);
  return r.n >= 30;
}
async function attempt(ip, username, ok) {
  await query('insert into auth_attempts (ip, username, ok) values ($1, $2, $3)', [ip, username, ok]);
  if (Math.random() < 0.02) await query("delete from auth_attempts where at < now() - interval '30 days'");
}

const str = (v, max = 200) => String(v ?? '').trim().slice(0, max);
const usernameOf = v => str(v, 63).toLowerCase();
const LOGIN_FAILED = 'The user name or password is wrong, or there were too many attempts. Try again in a few minutes.';

async function checkNewPassword(policy, pw, user) {
  const p = passwordProblems(pw, policy, { username: user.username, name: user.name });
  if (p.length) throw httpError(400, 'weak_password', p.join(' '));
  if (await verifyPassword(pw, user.password_hash)) throw httpError(400, 'password_reused', 'Choose a new password, not the current one.');
  for (const old of (user.password_history || []).slice(0, policy.history)) {
    if (await verifyPassword(pw, old)) throw httpError(400, 'password_reused', `Choose a password you did not use for your last ${policy.history} passwords.`);
  }
}
async function storePassword(c, userId, pw, policy, { mustChange = false } = {}) {
  const hash = await hashPassword(pw);
  const [u] = (await c.query('select password_hash, password_history from auth_users where id = $1', [userId])).rows;
  const history = [u.password_hash, ...(u.password_history || [])].slice(0, Math.max(policy.history, 0));
  await c.query('update auth_users set password_hash = $2, password_history = $3, password_changed_at = now(), must_change_password = $4, updated_at = now() where id = $1',
    [userId, hash, JSON.stringify(history), mustChange]);
}

function newRecoveryCodes() {
  const codes = Array.from({ length: 10 }, () => crypto.randomBytes(5).toString('hex').replace(/(.{5})/, '$1-'));
  return { codes, hashes: codes.map(c => sha(c)) };
}

/** The setup code for the first administrator: from the environment, or made once and kept in the database */
async function setupCode() {
  const fixed = (process.env[`${config.appId.toUpperCase().replace(/-/g, '_')}_SETUP_CODE`] || '').trim();
  if (fixed) return fixed;
  const code = Array.from({ length: 3 }, () => crypto.randomBytes(3).toString('hex')).join('-');
  const [r] = await query('update auth_settings set setup_code = coalesce(setup_code, $1) where id = 1 returning setup_code', [code]);
  return r.setup_code;
}
const noUsers = async () => (await query('select not exists (select 1 from auth_users) as none'))[0].none;

// ---------------------------------------------------------------- The routes
const PUBLIC = new Set(['/api/auth/state', '/api/auth/login', '/api/auth/setup', '/api/auth/logout']);
// What a user who must first change the password or set up two-factor sign-in can reach
const PENDING_OK = new Set(['/api/auth/password', '/api/auth/totp/start', '/api/auth/totp/confirm']);

/**
 * The route module of the element.
 * options: onEvent(ctx, action, details) for an audit log; encrypt/decrypt for the TOTP secrets
 * (library element secrets); policy: the app's defaults; open: more paths that need no sign-in.
 */
export function auth({ onEvent, encrypt, decrypt, policy = {}, open = [] } = {}) {
  hooks = { onEvent, encrypt: encrypt || (s => s), decrypt: decrypt || (s => s) };
  defaults = { ...DEFAULT_POLICY, ...policy };
  const openPaths = new Set([...PUBLIC, ...open]);

  return async function authRoutes(app) {
    if (await noUsers()) log.warn('No administrator yet: open the app and create one with this setup code', { setup_code: await setupCode() });

    // Every API request: who is it?
    app.use(async ctx => {
      const pol = await getPolicy();
      const s = await findSession(ctx, pol);
      if (s) {
        ctx.user = { id: String(s.id), username: s.username, name: s.name, isAdmin: s.is_admin, totpEnabled: s.totp_enabled, sessionId: String(s.session_id), pending: pending(s, pol) };
      }
      if (openPaths.has(ctx.path)) return;
      if (!ctx.user) throw httpError(401, 'signed_out', 'Sign in first.');
      if (ctx.user.pending.length && !PENDING_OK.has(ctx.path)) throw httpError(403, 'setup_needed', ctx.user.pending.includes('password') ? 'Choose a new password first.' : 'Set up two-factor sign-in first.');
    });

    app.get('/api/auth/state', async ctx => {
      const pol = await getPolicy();
      const p = { minLength: pol.minLength, requireLower: pol.requireLower, requireUpper: pol.requireUpper, requireDigit: pol.requireDigit, requireSymbol: pol.requireSymbol, totp: pol.totp };
      if (!ctx.user) return { setup: await noUsers(), user: null, policy: p };
      const [u] = await query(`select ${USER_COLS} from auth_users where id = $1`, [ctx.user.id]);
      return { setup: false, user: { ...publicUser(u), pending: ctx.user.pending }, policy: p };
    });

    app.post('/api/auth/setup', async ctx => {
      const b = ctx.body || {};
      if (!(await noUsers())) throw httpError(409, 'already_set_up', 'There is an administrator already. Sign in instead.');
      if (await limitedIp(ctx.clientIp)) throw httpError(429, 'too_many', 'Too many attempts. Try again in a few minutes.');
      const code = await setupCode();
      const given = str(b.code, 100);
      if (given.length !== code.length || !crypto.timingSafeEqual(Buffer.from(given), Buffer.from(code))) {
        await attempt(ctx.clientIp, '', false);
        throw httpError(403, 'wrong_code', 'The setup code is wrong. It is in the log of the server and was shown by the installer.');
      }
      const username = usernameOf(b.username), name = str(b.name, 120);
      if (!/^[a-z0-9][a-z0-9._-]{1,62}$/.test(username)) throw httpError(400, 'bad_username', 'User names have 2 to 63 characters: lowercase letters, digits, dots, dashes and underscores.');
      const pol = await getPolicy();
      const problems = passwordProblems(b.password, pol, { username, name });
      if (problems.length) throw httpError(400, 'weak_password', problems.join(' '));
      const hash = await hashPassword(b.password);
      const u = await tx(async c => {
        await c.query('lock table auth_users in exclusive mode');
        if ((await c.query('select 1 from auth_users limit 1')).rows.length) throw httpError(409, 'already_set_up', 'There is an administrator already. Sign in instead.');
        const [row] = (await c.query('insert into auth_users (username, name, password_hash, is_admin) values ($1, $2, $3, true) returning id', [username, name, hash])).rows;
        await c.query('update auth_settings set setup_code = null where id = 1');
        return row;
      });
      await newSession(ctx, u.id, pol);
      ctx.user = { id: String(u.id), username, name, isAdmin: true };
      event(ctx, 'auth.setup', { username });
      return { status: 201, body: { ok: true } };
    });

    app.post('/api/auth/login', async ctx => {
      const b = ctx.body || {};
      const username = usernameOf(b.username);
      if (await limitedIp(ctx.clientIp)) throw httpError(429, 'too_many', 'Too many attempts from this address. Try again in a few minutes.');
      const pol = await getPolicy();
      const [u] = await query('select * from auth_users where username = $1', [username]);
      const okPw = u ? await verifyPassword(String(b.password ?? ''), u.password_hash) : (await verifyPassword(String(b.password ?? ''), await DUMMY), false);
      const locked = u?.locked_until && new Date(u.locked_until) > new Date();
      if (!u || !okPw || locked || u.disabled) {
        await attempt(ctx.clientIp, username, false);
        if (u && !okPw && !locked) {
          await query(`update auth_users set failed_logins = failed_logins + 1,
            locked_until = case when failed_logins + 1 >= $2 then now() + make_interval(mins => $3) else locked_until end where id = $1`, [u.id, pol.lockoutAttempts, pol.lockoutMinutes]);
        }
        event({ ...ctx, user: null }, 'auth.login_failed', { username });
        throw httpError(401, 'login_failed', LOGIN_FAILED);
      }
      if (u.totp_enabled) {
        const code = str(b.code, 20);
        if (!code) return { totp: true };
        const counter = totpMatch(hooks.decrypt(u.totp_secret), code);
        let ok = counter > Number(u.totp_last_counter);
        if (ok) await query('update auth_users set totp_last_counter = $2 where id = $1', [u.id, counter]);
        if (!ok && !counter) {
          // A recovery code: works once
          const h = sha(code.toLowerCase());
          if ((u.recovery_codes || []).includes(h)) {
            ok = true;
            await query('update auth_users set recovery_codes = $2 where id = $1', [u.id, JSON.stringify(u.recovery_codes.filter(x => x !== h))]);
            event({ ...ctx, user: { id: String(u.id), username: u.username } }, 'auth.recovery_code_used', {});
          }
        }
        if (!ok) {
          await attempt(ctx.clientIp, username, false);
          await query(`update auth_users set failed_logins = failed_logins + 1,
            locked_until = case when failed_logins + 1 >= $2 then now() + make_interval(mins => $3) else locked_until end where id = $1`, [u.id, pol.lockoutAttempts, pol.lockoutMinutes]);
          throw httpError(401, 'code_wrong', 'The code is wrong or was used already. Wait for the next one.');
        }
      }
      await attempt(ctx.clientIp, username, true);
      await query('update auth_users set failed_logins = 0, locked_until = null, last_login_at = now() where id = $1', [u.id]);
      await newSession(ctx, u.id, pol);
      event({ ...ctx, user: { id: String(u.id), username: u.username, name: u.name } }, 'auth.login', {});
      return { ok: true };
    });

    app.post('/api/auth/logout', async ctx => {
      const token = cookies(ctx.req)[COOKIE];
      if (token) await query('delete from auth_sessions where token_hash = $1', [sha(token)]);
      setCookie(ctx, '', 0);
      if (ctx.user) event(ctx, 'auth.logout', {});
      return null;
    });

    app.post('/api/auth/logout-others', async ctx => {
      const r = await query('delete from auth_sessions where user_id = $1 and id <> $2 returning id', [ctx.user.id, ctx.user.sessionId]);
      event(ctx, 'auth.logout_others', { sessions: r.length });
      return { ended: r.length };
    });

    app.get('/api/auth/sessions', async ctx => (await query(`select id, created_at, last_seen_at, ip, user_agent from auth_sessions
      where user_id = $1 and expires_at > now() order by last_seen_at desc`, [ctx.user.id])).map(s => ({ ...s, id: String(s.id), current: String(s.id) === ctx.user.sessionId })));

    app.del('/api/auth/sessions/:id', async ctx => {
      const r = await query('delete from auth_sessions where id = $1 and user_id = $2 returning id', [/^\d+$/.test(ctx.params.id) ? ctx.params.id : 0, ctx.user.id]);
      if (!r.length) throw httpError(404, 'not_found', 'There is no such session.');
      return null;
    });

    app.post('/api/auth/password', async ctx => {
      const b = ctx.body || {};
      const pol = await getPolicy();
      const [u] = await query('select * from auth_users where id = $1', [ctx.user.id]);
      if (!(await verifyPassword(String(b.current ?? ''), u.password_hash))) throw httpError(400, 'wrong_password', 'Your current password is wrong.');
      await checkNewPassword(pol, String(b.password ?? ''), u);
      await tx(c => storePassword(c, u.id, String(b.password), pol));
      // Other sessions end: whoever knew the old password is out
      await query('delete from auth_sessions where user_id = $1 and id <> $2', [u.id, ctx.user.sessionId]);
      event(ctx, 'auth.password_changed', {});
      return { ok: true };
    });

    app.post('/api/auth/verify', async ctx => {
      const b = ctx.body || {};
      const [u] = await query('select * from auth_users where id = $1', [ctx.user.id]);
      let ok = false;
      if (u.totp_enabled) {
        const counter = totpMatch(hooks.decrypt(u.totp_secret), b.code);
        ok = counter > Number(u.totp_last_counter);
        if (ok) await query('update auth_users set totp_last_counter = $2 where id = $1', [u.id, counter]);
      } else ok = await verifyPassword(String(b.password ?? ''), u.password_hash);
      if (!ok) { await attempt(ctx.clientIp, u.username, false); throw httpError(400, 'verify_failed', u.totp_enabled ? 'The code is wrong or was used already. Wait for the next one.' : 'The password is wrong.'); }
      await query('update auth_sessions set verified_at = now() where id = $1', [ctx.user.sessionId]);
      return { ok: true };
    });

    app.post('/api/auth/totp/start', async ctx => {
      const [u] = await query('select * from auth_users where id = $1', [ctx.user.id]);
      if (u.totp_enabled) throw httpError(409, 'totp_on', 'Two-factor sign-in is already on.');
      const secret = base32(crypto.randomBytes(20));
      await query('update auth_users set totp_secret = $2 where id = $1', [u.id, hooks.encrypt(secret)]);
      const label = encodeURIComponent(`${config.appName}:${u.username}`);
      return { secret, uri: `otpauth://totp/${label}?secret=${secret}&issuer=${encodeURIComponent(config.appName)}&algorithm=SHA1&digits=6&period=30` };
    });

    app.post('/api/auth/totp/confirm', async ctx => {
      const [u] = await query('select * from auth_users where id = $1', [ctx.user.id]);
      if (u.totp_enabled) throw httpError(409, 'totp_on', 'Two-factor sign-in is already on.');
      if (!u.totp_secret) throw httpError(400, 'totp_not_started', 'Start the setup first.');
      const counter = totpMatch(hooks.decrypt(u.totp_secret), ctx.body?.code);
      if (!counter) throw httpError(400, 'code_wrong', 'The code does not match. Check the time on your phone and try the next code.');
      const { codes, hashes } = newRecoveryCodes();
      await query('update auth_users set totp_enabled = true, totp_last_counter = $2, recovery_codes = $3, updated_at = now() where id = $1', [u.id, counter, JSON.stringify(hashes)]);
      await query('update auth_sessions set verified_at = now() where id = $1', [ctx.user.sessionId]);
      event(ctx, 'auth.totp_enabled', {});
      return { recoveryCodes: codes };
    });

    app.post('/api/auth/totp/disable', async ctx => {
      const pol = await getPolicy();
      const [u] = await query('select * from auth_users where id = $1', [ctx.user.id]);
      if (pol.totp === 'all' || (pol.totp === 'admins' && u.is_admin)) throw httpError(403, 'totp_required', 'Two-factor sign-in is required for your account.');
      if (!(await verifyPassword(String(ctx.body?.password ?? ''), u.password_hash))) throw httpError(400, 'wrong_password', 'Your password is wrong.');
      await query("update auth_users set totp_enabled = false, totp_secret = null, recovery_codes = '[]', updated_at = now() where id = $1", [u.id]);
      event(ctx, 'auth.totp_disabled', {});
      return { ok: true };
    });

    app.post('/api/auth/recovery-codes', async ctx => {
      await requireFresh(ctx);
      const { codes, hashes } = newRecoveryCodes();
      await query('update auth_users set recovery_codes = $2 where id = $1 and totp_enabled', [ctx.user.id, JSON.stringify(hashes)]);
      event(ctx, 'auth.recovery_codes_renewed', {});
      return { recoveryCodes: codes };
    });

    // ------------------------------------------------------------ Accounts (administrators)
    app.get('/api/auth/users', async ctx => {
      requireAdmin(ctx);
      return (await query(`select ${USER_COLS} from auth_users order by username`)).map(publicUser);
    });

    app.post('/api/auth/users', async ctx => {
      requireAdmin(ctx);
      const b = ctx.body || {};
      const username = usernameOf(b.username);
      if (!/^[a-z0-9][a-z0-9._-]{1,62}$/.test(username)) throw httpError(400, 'bad_username', 'User names have 2 to 63 characters: lowercase letters, digits, dots, dashes and underscores.');
      const pol = await getPolicy();
      const password = b.password ? String(b.password) : randomPassword();
      const problems = passwordProblems(password, pol, { username, name: str(b.name, 120) });
      if (problems.length) throw httpError(400, 'weak_password', problems.join(' '));
      const rows = await query(`insert into auth_users (username, name, email, password_hash, is_admin, must_change_password) values ($1, $2, $3, $4, $5, true)
        on conflict (username) do nothing returning ${USER_COLS}`, [username, str(b.name, 120), str(b.email, 200), await hashPassword(password), !!b.isAdmin]);
      if (!rows.length) throw httpError(409, 'username_taken', 'This user name is taken.');
      event(ctx, 'auth.user_created', { username, isAdmin: !!b.isAdmin, target: { type: 'user', id: String(rows[0].id), name: username } });
      return { status: 201, body: { ...publicUser(rows[0]), password: b.password ? undefined : password } };
    });

    const userParam = async (ctx) => {
      if (!/^\d+$/.test(ctx.params.id)) throw httpError(404, 'not_found', 'There is no such user.');
      const [u] = await query('select * from auth_users where id = $1', [ctx.params.id]);
      if (!u) throw httpError(404, 'not_found', 'There is no such user.');
      return u;
    };
    const otherAdmins = async id => (await query('select count(*)::int as n from auth_users where is_admin and not disabled and id <> $1', [id]))[0].n;

    app.patch('/api/auth/users/:id', async ctx => {
      requireAdmin(ctx);
      const u = await userParam(ctx);
      const b = ctx.body || {};
      const next = { name: 'name' in b ? str(b.name, 120) : u.name, email: 'email' in b ? str(b.email, 200) : u.email, is_admin: 'isAdmin' in b ? !!b.isAdmin : u.is_admin, disabled: 'disabled' in b ? !!b.disabled : u.disabled };
      if ((u.is_admin && !next.is_admin) || (!u.disabled && next.disabled)) {
        if (u.is_admin && !(await otherAdmins(u.id))) throw httpError(409, 'last_admin', 'This is the last active administrator. Make someone else an administrator first.');
      }
      const [row] = await query(`update auth_users set name = $2, email = $3, is_admin = $4, disabled = $5, updated_at = now(),
        locked_until = case when $6 then null else locked_until end, failed_logins = case when $6 then 0 else failed_logins end where id = $1 returning ${USER_COLS}`,
      [u.id, next.name, next.email, next.is_admin, next.disabled, b.unlock === true]);
      if (next.disabled) await query('delete from auth_sessions where user_id = $1', [u.id]);
      event(ctx, 'auth.user_changed', { target: { type: 'user', id: String(u.id), name: u.username }, changes: Object.keys(b) });
      return publicUser(row);
    });

    app.post('/api/auth/users/:id/reset-password', async ctx => {
      requireAdmin(ctx);
      const u = await userParam(ctx);
      const pol = await getPolicy();
      const password = randomPassword();
      await tx(c => storePassword(c, u.id, password, { ...pol, history: Math.max(pol.history, 1) }, { mustChange: true }));
      await query('update auth_users set failed_logins = 0, locked_until = null where id = $1', [u.id]);
      await query('delete from auth_sessions where user_id = $1', [u.id]);
      event(ctx, 'auth.password_reset', { target: { type: 'user', id: String(u.id), name: u.username } });
      return { password };
    });

    app.post('/api/auth/users/:id/reset-totp', async ctx => {
      requireAdmin(ctx);
      const u = await userParam(ctx);
      await query("update auth_users set totp_enabled = false, totp_secret = null, recovery_codes = '[]', updated_at = now() where id = $1", [u.id]);
      await query('delete from auth_sessions where user_id = $1', [u.id]);
      event(ctx, 'auth.totp_reset', { target: { type: 'user', id: String(u.id), name: u.username } });
      return { ok: true };
    });

    app.del('/api/auth/users/:id', async ctx => {
      requireAdmin(ctx);
      const u = await userParam(ctx);
      if (String(u.id) === ctx.user.id) throw httpError(409, 'self', 'You cannot delete your own account.');
      if (u.is_admin && !(await otherAdmins(u.id))) throw httpError(409, 'last_admin', 'This is the last active administrator.');
      await query('delete from auth_users where id = $1', [u.id]);
      event(ctx, 'auth.user_deleted', { target: { type: 'user', id: String(u.id), name: u.username } });
      return null;
    });

    app.get('/api/auth/policy', async ctx => { requireAdmin(ctx); return getPolicy(); });
    app.put('/api/auth/policy', async ctx => {
      requireAdmin(ctx);
      const p = normalizePolicy({ ...(await getPolicy()), ...(ctx.body || {}) });
      await query('update auth_settings set policy = $1 where id = 1', [JSON.stringify(p)]);
      cached = null;
      event(ctx, 'auth.policy_changed', { policy: p });
      return p;
    });
  };
}
__FLEETPILOT_FILE_END__
  mkdir -p "$W/server/lib"
  cat > "$W/server/lib/catalog-services.mjs" <<'__FLEETPILOT_FILE_END__'
// FleetPilot: the service catalog. Each service is a setting of the area "services": packages,
// its configuration from a form, the service started, and the ports it needs (the firewall of the
// desired state opens them by itself).
import { T, F, conf, quote } from './catalog.mjs';
import { toYaml } from './yaml.mjs';

const lines = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const portOf = (listen, def) => Number(String(listen || '').split(':').pop()) || def;

/**
 * A service: packages, files (each { dest, content, mode, validate, noLog }), the unit to run,
 * a handler that restarts (or reloads) it, ports, and optional extra tasks before or after.
 */
function service(d) {
  return {
    id: d.id, area: 'services', single: true, title: d.title, text: d.text, fields: d.fields || [], needs: d.needs, summary: d.summary,
    group: d.group,
    ports: d.ports || (() => []),
    tasks: (v, ctx) => {
      const unit = typeof d.unit === 'function' ? d.unit(v) : d.unit;
      const handler = d.reload ? `Reload ${unit}` : `Restart ${unit}`;
      const files = d.files ? d.files(v, ctx) : [];
      return {
        tasks: [
          ...(d.before ? d.before(v, ctx) : []),
          T.apt(typeof d.packages === 'function' ? d.packages(v) : d.packages, 'present', `Install ${d.title}`),
          ...files.map(f => f.dir
            ? T.file(f.name || `Make ${f.dest}`, { path: f.dest, state: 'directory', mode: f.mode || '0755', owner: f.owner || 'root', group: f.group || 'root' })
            : T.copy(f.name || `Write ${f.dest}`, f.dest, f.content, { mode: f.mode, owner: f.owner, group: f.group, validate: f.validate, noLog: f.noLog, notify: unit ? handler : undefined })),
          ...(d.after ? d.after(v, ctx) : []),
          ...(unit ? [{ ...T.service(unit), ...(d.startWhen ? { when: d.startWhen } : {}) }] : [])
        ],
        handlers: unit ? { [handler]: d.check ? [T.cmd(`Check the configuration of ${d.title}`, d.check), d.reload ? T.reload(unit) : T.restart(unit)] : d.reload ? T.reload(unit) : T.restart(unit) } : {}
      };
    }
  };
}

export const SERVICES = [
  // ---------------------------------------------------------------- Web and proxies
  service({
    id: 'nginx', group: 'Web and proxies', title: 'nginx', text: 'Web server and reverse proxy, with one site per row.',
    packages: ['nginx'], unit: 'nginx', reload: true, check: 'nginx -t',
    fields: [
      F.rows('sites', 'Sites', [
        F.text('name', 'Name', { pattern: 'name', required: true, placeholder: 'www' }), F.text('names', 'Host names', { pattern: 'any', placeholder: 'www.example.com example.com' }),
        F.num('port', 'Port', 80, [1, 65535]), F.text('root', 'Files from', { pattern: 'path', placeholder: '/var/www/html' }),
        F.text('proxy', 'Or pass on to', { pattern: 'url', placeholder: 'http://127.0.0.1:3000' }), F.text('tls', 'TLS certificate name', { pattern: 'name', placeholder: 'www (from TLS certificates)' })
      ]),
      F.bool('removeDefault', 'Remove the default site', true)
    ],
    files: v => v.sites.flatMap(s => [{ dest: `/etc/nginx/sites-available/fp-${s.name}.conf`, content: conf([
      'server {', `    listen ${s.tls ? `${s.port === 80 ? 443 : s.port} ssl` : s.port};`, `    listen [::]:${s.tls ? `${s.port === 80 ? 443 : s.port} ssl` : s.port};`,
      `    server_name ${s.names || '_'};`,
      s.tls ? `    ssl_certificate /etc/ssl/fleetpilot/${s.tls}.crt;\n    ssl_certificate_key /etc/ssl/fleetpilot/${s.tls}.key;\n    ssl_protocols TLSv1.2 TLSv1.3;` : null,
      s.proxy ? `    location / {\n        proxy_pass ${s.proxy};\n        proxy_set_header Host $host;\n        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n        proxy_set_header X-Forwarded-Proto $scheme;\n        proxy_http_version 1.1;\n        proxy_set_header Upgrade $http_upgrade;\n        proxy_set_header Connection "upgrade";\n    }`
        : `    root ${s.root || '/var/www/html'};\n    index index.html;\n    location / {\n        try_files $uri $uri/ =404;\n    }`,
      '}',
      s.tls && s.port === 80 ? `server {\n    listen 80;\n    listen [::]:80;\n    server_name ${s.names || '_'};\n    return 301 https://$host$request_uri;\n}` : null
    ]) }]),
    after: v => [
      ...v.sites.map(s => T.file(`Switch on the site ${s.name}`, { src: `/etc/nginx/sites-available/fp-${s.name}.conf`, dest: `/etc/nginx/sites-enabled/fp-${s.name}.conf`, state: 'link' }, { notify: 'Reload nginx' })),
      ...(v.removeDefault ? [T.file('Remove the default site', { path: '/etc/nginx/sites-enabled/default', state: 'absent' }, { notify: 'Reload nginx' })] : [])
    ],
    ports: v => v.sites.flatMap(s => s.tls ? [{ port: s.port === 80 ? 443 : s.port, proto: 'tcp', label: 'nginx' }, ...(s.port === 80 ? [{ port: 80, proto: 'tcp', label: 'nginx' }] : [])] : [{ port: s.port, proto: 'tcp', label: 'nginx' }]),
    summary: v => v.sites.length ? v.sites.map(s => s.names || s.name).join(', ') : 'No sites'
  }),
  service({
    id: 'apache', group: 'Web and proxies', title: 'Apache', text: 'The Apache web server with name-based sites.',
    packages: ['apache2'], unit: 'apache2', reload: true, check: 'apache2ctl configtest',
    fields: [F.rows('sites', 'Sites', [F.text('name', 'Name', { pattern: 'name', required: true }), F.text('names', 'Host names', { pattern: 'any', placeholder: 'www.example.com' }), F.num('port', 'Port', 80, [1, 65535]), F.text('root', 'Files from', { pattern: 'path', placeholder: '/var/www/html' }), F.text('proxy', 'Or pass on to', { pattern: 'url' })])],
    files: v => v.sites.map(s => ({ dest: `/etc/apache2/sites-available/fp-${s.name}.conf`, content: conf([
      s.port !== 80 ? `Listen ${s.port}` : null, `<VirtualHost *:${s.port}>`, `    ServerName ${(s.names || 'localhost').split(' ')[0]}`, s.names.split(' ').length > 1 ? `    ServerAlias ${s.names.split(' ').slice(1).join(' ')}` : null,
      s.proxy ? `    ProxyPreserveHost On\n    ProxyPass / ${s.proxy}/\n    ProxyPassReverse / ${s.proxy}/` : `    DocumentRoot ${s.root || '/var/www/html'}`, '</VirtualHost>']) })),
    after: v => [
      ...(v.sites.some(s => s.proxy) ? ['proxy', 'proxy_http'].map(m => T.cmd(`Switch on the module ${m}`, `a2enmod ${m}`, { creates: `/etc/apache2/mods-enabled/${m}.load` })) : []),
      ...v.sites.map(s => T.file(`Switch on the site ${s.name}`, { src: `/etc/apache2/sites-available/fp-${s.name}.conf`, dest: `/etc/apache2/sites-enabled/fp-${s.name}.conf`, state: 'link' }, { notify: 'Reload apache2' }))
    ],
    ports: v => v.sites.map(s => ({ port: s.port, proto: 'tcp', label: 'Apache' })),
    summary: v => v.sites.map(s => s.names || s.name).join(', ') || 'No sites'
  }),
  service({
    id: 'haproxy', group: 'Web and proxies', title: 'HAProxy', text: 'Load balancer for HTTP and TCP, with health checks.',
    packages: ['haproxy'], unit: 'haproxy', reload: true,
    fields: [
      F.rows('frontends', 'Frontends', [F.text('name', 'Name', { pattern: 'name', required: true, placeholder: 'web' }), F.num('port', 'Port', 80, [1, 65535]), F.select('mode', 'Mode', [['http', 'HTTP'], ['tcp', 'TCP']]), F.text('servers', 'Servers', { pattern: 'word', placeholder: '10.0.0.11:8080,10.0.0.12:8080' }), F.select('balance', 'Balance', [['roundrobin', 'In turn'], ['leastconn', 'Fewest connections'], ['source', 'By client address']])]),
      F.num('stats', 'Statistics page on port (0: none)', 0, [0, 65535])
    ],
    files: v => [{ dest: '/etc/haproxy/haproxy.cfg', validate: 'haproxy -c -f %s', content: conf([
      'global', '    log /dev/log local0', '    maxconn 20000', '    user haproxy', '    group haproxy', '    daemon', '',
      'defaults', '    log global', '    option dontlognull', '    timeout connect 5s', '    timeout client 60s', '    timeout server 60s',
      ...v.frontends.flatMap(f => ['', `frontend ${f.name}`, `    bind :${f.port}`, `    mode ${f.mode}`, f.mode === 'http' ? '    option httplog\n    option forwardfor' : '    option tcplog', `    default_backend ${f.name}-servers`, '',
        `backend ${f.name}-servers`, `    mode ${f.mode}`, `    balance ${f.balance}`, ...lines(f.servers).map((s, i) => `    server s${i + 1} ${s} check`)]),
      ...(v.stats ? ['', 'listen stats', `    bind :${v.stats}`, '    mode http', '    stats enable', '    stats uri /'] : [])
    ]) }],
    ports: v => [...v.frontends.map(f => ({ port: f.port, proto: 'tcp', label: 'HAProxy' })), ...(v.stats ? [{ port: v.stats, proto: 'tcp', label: 'HAProxy statistics' }] : [])],
    summary: v => v.frontends.map(f => `${f.name} :${f.port}`).join(', ') || 'No frontends'
  }),
  service({
    id: 'caddy', group: 'Web and proxies', title: 'Caddy', text: 'Web server that gets its own certificates from Let\'s Encrypt.',
    packages: ['caddy'], unit: 'caddy', reload: true, check: 'caddy validate --adapter caddyfile --config /etc/caddy/Caddyfile',
    fields: [F.text('email', 'E-mail for Let\'s Encrypt', { pattern: 'any', placeholder: 'ops@example.com' }), F.rows('sites', 'Sites', [F.text('address', 'Address', { pattern: 'any', required: true, placeholder: 'www.example.com' }), F.text('proxy', 'Pass on to', { pattern: 'any', placeholder: '127.0.0.1:3000' }), F.text('root', 'Or files from', { pattern: 'path' })])],
    files: v => [{ dest: '/etc/caddy/Caddyfile', content: conf([v.email ? `{\n    email ${v.email}\n}` : null, ...v.sites.map(s => `${s.address} {\n    ${s.proxy ? `reverse_proxy ${s.proxy}` : `root * ${s.root || '/var/www/html'}\n    file_server`}\n}`)]) }],
    ports: () => [{ port: 80, proto: 'tcp', label: 'Caddy' }, { port: 443, proto: 'tcp', label: 'Caddy' }],
    summary: v => v.sites.map(s => s.address).join(', ') || 'No sites'
  }),
  service({
    id: 'squid', group: 'Web and proxies', title: 'Squid', text: 'A forward proxy for the networks you name.',
    packages: ['squid'], unit: 'squid', check: 'squid -k parse',
    fields: [F.num('port', 'Port', 3128, [1, 65535]), F.lines('allow', 'Networks that may use it', { pattern: 'cidr', placeholder: '10.0.0.0/8' })],
    files: v => [{ dest: '/etc/squid/conf.d/fleetpilot.conf', content: conf([`http_port ${v.port}`, ...v.allow.map((n, i) => `acl fp_net${i} src ${n}`), ...v.allow.map((n, i) => `http_access allow fp_net${i}`)]) }],
    ports: v => [{ port: v.port, proto: 'tcp', from: v.allow, label: 'Squid' }],
    summary: v => `Port ${v.port} for ${v.allow.join(', ') || 'nobody yet'}`
  }),

  // ---------------------------------------------------------------- Containers
  service({
    id: 'docker', group: 'Containers', title: 'Docker', text: 'Docker Engine with Compose, from Debian or from Docker\'s own repository.',
    packages: v => v.source === 'docker' ? ['docker-ce', 'docker-ce-cli', 'containerd.io', 'docker-buildx-plugin', 'docker-compose-plugin'] : ['docker.io', 'docker-compose'],
    unit: 'docker',
    fields: [
      F.select('source', 'From', [['docker', 'Docker\'s repository (newest)'], ['debian', 'The distribution']]),
      F.lines('users', 'Users who may use Docker', { pattern: 'user', placeholder: 'alice' }),
      F.text('logSize', 'Container logs at most', { pattern: 'duration', default: '50m' }), F.num('logFiles', 'Log files per container', 3, [1, 50]),
      F.bool('liveRestore', 'Containers keep running during a Docker update', true),
      F.lines('mirrors', 'Registry mirrors', { pattern: 'url', placeholder: 'https://mirror.example.com' })
    ],
    before: v => v.source === 'docker' ? [
      T.file('Make the folder for signing keys', { path: '/etc/apt/keyrings', state: 'directory', mode: '0755' }),
      { name: 'Download the signing key of Docker', 'ansible.builtin.get_url': { url: 'https://download.docker.com/linux/{{ ansible_facts.distribution | lower }}/gpg', dest: '/etc/apt/keyrings/docker.asc', mode: '0644' } },
      T.copy('Add the Docker repository', '/etc/apt/sources.list.d/docker.list', "deb [arch={{ 'amd64' if ansible_facts.architecture == 'x86_64' else 'arm64' }} signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/{{ ansible_facts.distribution | lower }} {{ ansible_facts.distribution_release }} stable\n")
    ] : [],
    files: v => [{ dir: true, dest: '/etc/docker' }, { dest: '/etc/docker/daemon.json', content: JSON.stringify({ 'log-driver': 'json-file', 'log-opts': { 'max-size': v.logSize, 'max-file': String(v.logFiles) }, 'live-restore': v.liveRestore, ...(v.mirrors.length ? { 'registry-mirrors': v.mirrors } : {}) }, null, 2) + '\n' }],
    after: v => v.users.map(u => ({ name: `Let ${u} use Docker`, 'ansible.builtin.user': { name: u, groups: ['docker'], append: true } })),
    summary: v => `${v.source === 'docker' ? 'Docker CE' : 'docker.io'}${v.users.length ? ` for ${v.users.join(', ')}` : ''}`
  }),
  service({
    id: 'podman', group: 'Containers', title: 'Podman', text: 'Containers without a daemon, also for users without root.',
    packages: ['podman', 'podman-compose', 'uidmap', 'slirp4netns'], unit: null,
    fields: [F.lines('registries', 'Registries to search', { pattern: 'host', default: ['docker.io'] })],
    files: v => [{ dir: true, dest: '/etc/containers/registries.conf.d' }, { dest: '/etc/containers/registries.conf.d/50-fleetpilot.conf', content: conf([`unqualified-search-registries = [${v.registries.map(r => quote(r)).join(', ')}]`]) }],
    summary: v => `Searches ${v.registries.join(', ')}`
  }),

  // ---------------------------------------------------------------- Databases
  service({
    id: 'postgresql', group: 'Databases', title: 'PostgreSQL', text: 'The PostgreSQL of the distribution, with who may connect from where.',
    packages: ['postgresql'], unit: 'postgresql',
    fields: [
      F.text('listen', 'Listen on', { pattern: 'word', default: 'localhost', placeholder: 'localhost or * or 10.0.0.5' }), F.num('maxConnections', 'Connections at most', 100, [10, 10000]),
      F.text('memory', 'Shared buffers', { pattern: 'duration', default: '128MB' }),
      F.rows('access', 'Who may connect', [F.text('database', 'Database', { pattern: 'word', default: 'all' }), F.text('user', 'User', { pattern: 'word', default: 'all' }), F.text('from', 'From', { pattern: 'cidr', required: true, placeholder: '10.0.0.0/8' })])
    ],
    before: () => [T.cmd('Find out the PostgreSQL version', "sh -c 'ls /etc/postgresql 2>/dev/null | sort -V | tail -1'", { register: 'fp_pg', changed: false, checkMode: false })],
    files: v => [{ name: 'Configure PostgreSQL', dest: '/etc/postgresql/{{ fp_pg.stdout }}/main/conf.d/fleetpilot.conf', content: conf([`listen_addresses = '${v.listen}'`, `max_connections = ${v.maxConnections}`, `shared_buffers = ${v.memory.replace(/M$/, 'MB').replace(/G$/, 'GB')}`]) }],
    after: v => [T.block('Allow the connections', { path: '/etc/postgresql/{{ fp_pg.stdout }}/main/pg_hba.conf', marker: '# {mark} FleetPilot access', block: v.access.map(a => `host ${a.database} ${a.user} ${a.from} scram-sha-256`).join('\n') }, { notify: 'Restart postgresql' })],
    ports: v => v.listen !== 'localhost' ? [{ port: 5432, proto: 'tcp', from: v.access.map(a => a.from), label: 'PostgreSQL' }] : [],
    summary: v => `Listens on ${v.listen}${v.access.length ? `, ${v.access.length} access rules` : ''}`
  }),
  service({
    id: 'mariadb', group: 'Databases', title: 'MariaDB', text: 'The MariaDB server of the distribution.',
    packages: ['mariadb-server'], unit: 'mariadb',
    fields: [F.text('bind', 'Listen on', { pattern: 'ip', default: '127.0.0.1' }), F.num('port', 'Port', 3306, [1, 65535]), F.num('maxConnections', 'Connections at most', 151, [10, 10000]), F.text('bufferPool', 'Buffer pool', { pattern: 'duration', default: '128M' }), F.lines('from', 'Allowed from', { pattern: 'cidr' })],
    files: v => [{ dest: '/etc/mysql/mariadb.conf.d/90-fleetpilot.cnf', content: conf(['[mysqld]', `bind-address = ${v.bind}`, `port = ${v.port}`, `max_connections = ${v.maxConnections}`, `innodb_buffer_pool_size = ${v.bufferPool}`]) }],
    ports: v => v.bind !== '127.0.0.1' ? [{ port: v.port, proto: 'tcp', from: v.from, label: 'MariaDB' }] : [],
    summary: v => `${v.bind}:${v.port}`
  }),
  service({
    id: 'redis', group: 'Databases', title: 'Redis', text: 'In-memory store, with a password from the vault.',
    packages: ['redis-server'], unit: 'redis-server',
    fields: [F.text('bind', 'Listen on', { pattern: 'any', default: '127.0.0.1 ::1' }), F.num('port', 'Port', 6379, [1, 65535]), F.text('maxmemory', 'Memory at most', { pattern: 'duration', default: '256mb' }), F.select('policy', 'When full', [['allkeys-lru', 'Drop the least used keys'], ['noeviction', 'Refuse new writes'], ['volatile-lru', 'Drop keys with an expiry']]), F.bool('password', 'Require a password (made and kept in the vault)', true), F.lines('from', 'Allowed from', { pattern: 'cidr' })],
    needs: v => v.password ? [{ type: 'hostSecret', name: 'redis', label: 'Redis password' }] : [],
    files: v => [{ dest: '/etc/redis/fleetpilot.conf', mode: '0640', owner: 'redis', group: 'redis', noLog: true, content: conf([`bind ${v.bind}`, `port ${v.port}`, `maxmemory ${v.maxmemory}`, `maxmemory-policy ${v.policy}`, v.password ? "requirepass {{ fp_host_secret['redis'] }}" : null]) }],
    after: () => [T.line('Read the FleetPilot settings of Redis', { path: '/etc/redis/redis.conf', line: 'include /etc/redis/fleetpilot.conf' }, { notify: 'Restart redis-server' })],
    ports: v => v.bind.includes('127.0.0.1') && !v.bind.includes('0.0.0.0') ? [] : [{ port: v.port, proto: 'tcp', from: v.from, label: 'Redis' }],
    summary: v => `${v.bind}:${v.port}${v.password ? ', with password' : ''}`
  }),

  // ---------------------------------------------------------------- Names, addresses, time
  service({
    id: 'bind', group: 'DNS and DHCP', title: 'BIND (DNS resolver)', text: 'A caching DNS resolver for your networks, with forwarders.',
    packages: ['bind9', 'bind9-utils'], unit: 'named', check: 'named-checkconf',
    fields: [F.lines('forwarders', 'Forward to', { pattern: 'ip', placeholder: '9.9.9.9' }), F.lines('allow', 'Answer queries from', { pattern: 'cidr', placeholder: '10.0.0.0/8' }), F.bool('dnssec', 'Validate DNSSEC', true)],
    files: v => [{ dest: '/etc/bind/named.conf.options', content: conf(['options {', '    directory "/var/cache/bind";', v.forwarders.length ? `    forwarders { ${v.forwarders.join('; ')}; };` : null, `    allow-query { localhost; ${v.allow.map(a => `${a};`).join(' ')} };`, `    allow-recursion { localhost; ${v.allow.map(a => `${a};`).join(' ')} };`, `    dnssec-validation ${v.dnssec ? 'auto' : 'no'};`, '    listen-on-v6 { any; };', '};'], '//') }],
    ports: v => [{ port: 53, proto: 'udp', from: v.allow, label: 'DNS' }, { port: 53, proto: 'tcp', from: v.allow, label: 'DNS' }],
    summary: v => v.forwarders.length ? `Forwards to ${v.forwarders.join(', ')}` : 'Resolves by itself'
  }),
  service({
    id: 'unbound', group: 'DNS and DHCP', title: 'Unbound (DNS resolver)', text: 'A small, validating DNS resolver.',
    packages: ['unbound'], unit: 'unbound', check: 'unbound-checkconf',
    fields: [F.lines('forwarders', 'Forward to', { pattern: 'ip' }), F.lines('allow', 'Answer queries from', { pattern: 'cidr' }), F.bool('tls', 'Forward over TLS (port 853)', false)],
    files: v => [{ dest: '/etc/unbound/unbound.conf.d/fleetpilot.conf', content: conf(['server:', '    interface: 0.0.0.0', '    interface: ::0', ...v.allow.map(a => `    access-control: ${a} allow`),
      ...(v.forwarders.length ? ['forward-zone:', '    name: "."', v.tls ? '    forward-tls-upstream: yes' : null, ...v.forwarders.map(f => `    forward-addr: ${f}${v.tls ? '@853' : ''}`)] : [])]) }],
    ports: v => [{ port: 53, proto: 'udp', from: v.allow, label: 'DNS' }, { port: 53, proto: 'tcp', from: v.allow, label: 'DNS' }],
    summary: v => v.forwarders.length ? `Forwards to ${v.forwarders.join(', ')}` : 'Resolves by itself'
  }),
  service({
    id: 'dnsmasq', group: 'DNS and DHCP', title: 'dnsmasq', text: 'Small DNS forwarder and DHCP server for a lab or a branch.',
    packages: ['dnsmasq'], unit: 'dnsmasq', check: 'dnsmasq --test',
    fields: [F.text('interface', 'On interface', { pattern: 'iface', placeholder: 'ens19' }), F.text('domain', 'Local domain', { pattern: 'host', placeholder: 'lab.example.com' }), F.text('rangeStart', 'DHCP from', { pattern: 'ip' }), F.text('rangeEnd', 'DHCP to', { pattern: 'ip' }), F.text('lease', 'Lease', { pattern: 'word', default: '12h' }), F.text('router', 'Gateway for clients', { pattern: 'ip' }), F.lines('dns', 'Forward DNS to', { pattern: 'ip' })],
    files: v => [{ dest: '/etc/dnsmasq.d/fleetpilot.conf', content: conf([v.interface ? `interface=${v.interface}\nbind-interfaces` : null, v.domain ? `domain=${v.domain}\nlocal=/${v.domain}/` : null, 'no-resolv', ...v.dns.map(d => `server=${d}`), v.rangeStart ? `dhcp-range=${v.rangeStart},${v.rangeEnd},${v.lease}` : null, v.router ? `dhcp-option=option:router,${v.router}` : null]) }],
    ports: v => [{ port: 53, proto: 'udp', label: 'DNS' }, { port: 53, proto: 'tcp', label: 'DNS' }, ...(v.rangeStart ? [{ port: 67, proto: 'udp', label: 'DHCP' }] : [])],
    summary: v => v.rangeStart ? `DHCP ${v.rangeStart} to ${v.rangeEnd}` : 'DNS only'
  }),
  service({
    id: 'kea', group: 'DNS and DHCP', title: 'Kea (DHCP server)', text: 'ISC Kea DHCPv4 with a pool and fixed reservations.',
    packages: ['kea-dhcp4-server'], unit: 'kea-dhcp4-server',
    fields: [
      F.text('interface', 'On interface', { pattern: 'iface', required: true, placeholder: 'ens19' }), F.text('subnet', 'Subnet', { pattern: 'cidr', required: true, placeholder: '10.40.0.0/24' }),
      F.text('poolStart', 'Pool from', { pattern: 'ip', required: true }), F.text('poolEnd', 'Pool to', { pattern: 'ip', required: true }), F.text('router', 'Gateway', { pattern: 'ip' }), F.lines('dns', 'DNS servers', { pattern: 'ip' }), F.text('domain', 'Domain', { pattern: 'host' }),
      F.num('lease', 'Lease (seconds)', 86400, [60, 31536000]),
      F.rows('reservations', 'Reservations', [F.text('mac', 'MAC', { pattern: 'word', required: true, placeholder: '52:54:00:12:34:56' }), F.text('ip', 'Address', { pattern: 'ip', required: true }), F.text('hostname', 'Name', { pattern: 'host' })])
    ],
    files: v => [{ dest: '/etc/kea/kea-dhcp4.conf', validate: 'kea-dhcp4 -t %s', content: JSON.stringify({ Dhcp4: {
      'interfaces-config': { interfaces: [v.interface] }, 'lease-database': { type: 'memfile', persist: true, name: '/var/lib/kea/kea-leases4.csv' }, 'valid-lifetime': v.lease,
      'option-data': [...(v.dns.length ? [{ name: 'domain-name-servers', data: v.dns.join(', ') }] : []), ...(v.domain ? [{ name: 'domain-name', data: v.domain }] : [])],
      subnet4: [{ id: 1, subnet: v.subnet, pools: [{ pool: `${v.poolStart} - ${v.poolEnd}` }], 'option-data': v.router ? [{ name: 'routers', data: v.router }] : [], reservations: v.reservations.map(r => ({ 'hw-address': r.mac, 'ip-address': r.ip, ...(r.hostname ? { hostname: r.hostname } : {}) })) }],
      loggers: [{ name: 'kea-dhcp4', 'output-options': [{ output: 'syslog' }], severity: 'INFO' }]
    } }, null, 2) + '\n' }],
    ports: () => [{ port: 67, proto: 'udp', label: 'DHCP' }],
    summary: v => `${v.subnet}, ${v.poolStart} to ${v.poolEnd}`
  }),

  // ---------------------------------------------------------------- VPN, files, high availability
  service({
    id: 'wireguard', group: 'VPN and files', title: 'WireGuard', text: 'A WireGuard interface with its peers. The private key is made on the host\'s behalf and kept in the vault.',
    packages: ['wireguard', 'wireguard-tools'], unit: v => `wg-quick@${v.name}`,
    fields: [F.text('name', 'Interface', { pattern: 'iface', default: 'wg0' }), F.text('address', 'Address with prefix', { pattern: 'cidr', required: true, placeholder: '10.99.0.1/24' }), F.num('port', 'Listen port', 51820, [1, 65535]),
      F.rows('peers', 'Peers', [F.text('name', 'Name', { pattern: 'any', required: true }), F.text('publicKey', 'Public key', { pattern: 'word', required: true }), F.text('allowed', 'Allowed addresses', { pattern: 'word', placeholder: '10.99.0.2/32' }), F.text('endpoint', 'Endpoint', { pattern: 'hostport' }), F.num('keepalive', 'Keepalive (s)', 0, [0, 3600])])],
    needs: v => [{ type: 'wgkey', name: v.name, label: `WireGuard ${v.name}` }],
    files: v => [{ dest: `/etc/wireguard/${v.name}.conf`, mode: '0600', noLog: true, content: conf(['[Interface]', `Address = ${v.address}`, `ListenPort = ${v.port}`, `PrivateKey = {{ fp_host_secret['wireguard ${v.name}'] }}`,
      ...v.peers.flatMap(p => ['', `# ${p.name}`, '[Peer]', `PublicKey = ${p.publicKey}`, `AllowedIPs = ${p.allowed}`, p.endpoint ? `Endpoint = ${p.endpoint}` : null, p.keepalive ? `PersistentKeepalive = ${p.keepalive}` : null])]) }],
    ports: v => [{ port: v.port, proto: 'udp', label: 'WireGuard' }],
    summary: v => `${v.name} ${v.address}, ${v.peers.length} peers`
  }),
  service({
    id: 'samba', group: 'VPN and files', title: 'Samba (SMB shares)', text: 'Windows file shares.',
    packages: ['samba'], unit: 'smbd', check: 'testparm -s',
    fields: [F.text('workgroup', 'Workgroup', { pattern: 'name', default: 'WORKGROUP' }), F.lines('allow', 'Allowed from', { pattern: 'cidr' }), F.rows('shares', 'Shares', [F.text('name', 'Name', { pattern: 'name', required: true, placeholder: 'projects' }), F.text('path', 'Folder', { pattern: 'path', required: true, placeholder: '/srv/projects' }), F.text('users', 'Users', { pattern: 'word', placeholder: 'alice,@staff' }), F.bool('readOnly', 'Read only', false), F.bool('guest', 'Guests allowed', false)])],
    files: v => [...v.shares.map(s => ({ dir: true, dest: s.path, mode: '0775' })), { dest: '/etc/samba/smb.conf', content: conf(['[global]', `   workgroup = ${v.workgroup}`, '   server role = standalone server', '   server min protocol = SMB2_10', '   map to guest = bad user', v.allow.length ? `   hosts allow = 127.0.0.1 ${v.allow.join(' ')}` : null, '   log file = /var/log/samba/log.%m', '   max log size = 1000',
      ...v.shares.flatMap(s => ['', `[${s.name}]`, `   path = ${s.path}`, `   read only = ${s.readOnly ? 'yes' : 'no'}`, `   guest ok = ${s.guest ? 'yes' : 'no'}`, s.users ? `   valid users = ${lines(s.users).join(' ')}` : null])]) }],
    ports: v => [{ port: 445, proto: 'tcp', from: v.allow, label: 'SMB' }],
    summary: v => v.shares.map(s => s.name).join(', ') || 'No shares'
  }),
  service({
    id: 'nfs', group: 'VPN and files', title: 'NFS server', text: 'NFS exports for Linux clients.',
    packages: ['nfs-kernel-server'], unit: 'nfs-server',
    fields: [F.rows('exports', 'Exports', [F.text('path', 'Folder', { pattern: 'path', required: true, placeholder: '/srv/nfs/data' }), F.text('clients', 'Clients', { pattern: 'cidr', required: true, placeholder: '10.0.0.0/24' }), F.text('options', 'Options', { pattern: 'word', default: 'rw,sync,no_subtree_check' })])],
    files: v => [...v.exports.map(e => ({ dir: true, dest: e.path })), { dir: true, dest: '/etc/exports.d' }, { dest: '/etc/exports.d/fleetpilot.exports', content: conf(v.exports.map(e => `${e.path} ${e.clients}(${e.options})`)) }],
    after: () => [T.cmd('Publish the exports', 'exportfs -ra', { changed: false })],
    ports: v => [{ port: 2049, proto: 'tcp', from: v.exports.map(e => e.clients), label: 'NFS' }],
    summary: v => v.exports.map(e => e.path).join(', ') || 'No exports'
  }),
  service({
    id: 'keepalived', group: 'VPN and files', title: 'Keepalived (shared address)', text: 'A virtual address that moves to another host when one fails (VRRP).',
    packages: ['keepalived'], unit: 'keepalived',
    fields: [F.rows('instances', 'Shared addresses', [F.text('name', 'Name', { pattern: 'name', required: true, placeholder: 'web' }), F.text('interface', 'Interface', { pattern: 'iface', placeholder: 'ens18' }), F.num('router', 'Router id', 51, [1, 255]), F.text('vip', 'Shared address', { pattern: 'cidr', required: true, placeholder: '10.20.0.100/24' }), F.select('role', 'Role', [['BACKUP', 'Equal (highest priority wins)'], ['MASTER', 'Preferred']]), F.num('priority', 'Priority', 100, [1, 254])])],
    needs: v => v.instances.map(i => ({ type: 'shared', key: `vrrp:${i.name}`, length: 8, label: `VRRP ${i.name}` })),
    files: v => [{ dest: '/etc/keepalived/keepalived.conf', mode: '0600', noLog: true, content: conf(v.instances.flatMap(i => [`vrrp_instance ${i.name} {`, `    state ${i.role}`, `    interface ${i.interface || '{{ ansible_facts.default_ipv4.interface }}'}`, `    virtual_router_id ${i.router}`, `    priority ${i.priority}`, '    advert_int 1', '    authentication {', '        auth_type PASS', `        auth_pass {{ fp_shared['vrrp:${i.name}'] }}`, '    }', '    virtual_ipaddress {', `        ${i.vip}`, '    }', '}'])) }],
    ports: () => [{ raw: 'ip protocol vrrp', label: 'VRRP' }],
    summary: v => v.instances.map(i => i.vip).join(', ') || 'None'
  }),

  // ---------------------------------------------------------------- Monitoring
  service({
    id: 'nodeexporter', group: 'Monitoring', title: 'Prometheus node exporter', text: 'Hardware and system metrics for Prometheus.',
    packages: ['prometheus-node-exporter'], unit: 'prometheus-node-exporter',
    fields: [F.text('listen', 'Listen on', { pattern: 'word', default: ':9100' }), F.lines('from', 'Allowed from', { pattern: 'cidr' }), F.bool('systemd', 'Also report systemd units', true)],
    files: v => [{ dest: '/etc/default/prometheus-node-exporter', content: conf([`ARGS="--web.listen-address=${v.listen}${v.systemd ? ' --collector.systemd' : ''}"`]) }],
    ports: v => [{ port: portOf(v.listen, 9100), proto: 'tcp', from: v.from, label: 'node exporter' }],
    summary: v => v.listen
  }),
  service({
    id: 'prometheus', group: 'Monitoring', title: 'Prometheus', text: 'Collects metrics from the targets you name.',
    packages: ['prometheus'], unit: 'prometheus', reload: true, check: 'promtool check config /etc/prometheus/prometheus.yml',
    fields: [F.text('interval', 'Collect every', { pattern: 'word', default: '30s' }), F.text('retention', 'Keep for', { pattern: 'word', default: '30d' }), F.rows('jobs', 'Targets', [F.text('name', 'Job', { pattern: 'name', required: true, placeholder: 'nodes' }), F.text('targets', 'Targets', { pattern: 'word', placeholder: '10.0.0.11:9100,10.0.0.12:9100' })]), F.lines('from', 'Web page allowed from', { pattern: 'cidr' })],
    files: v => [{ dest: '/etc/prometheus/prometheus.yml', content: '# Managed by FleetPilot\n' + toYaml({ global: { scrape_interval: v.interval }, scrape_configs: [{ job_name: 'prometheus', static_configs: [{ targets: ['localhost:9090'] }] }, ...v.jobs.map(j => ({ job_name: j.name, static_configs: [{ targets: lines(j.targets) }] }))] }) },
      { dest: '/etc/default/prometheus', content: conf([`ARGS="--storage.tsdb.retention.time=${v.retention}"`]) }],
    ports: v => [{ port: 9090, proto: 'tcp', from: v.from, label: 'Prometheus' }],
    summary: v => `${v.jobs.length} jobs, every ${v.interval}`
  }),
  service({
    id: 'grafana', group: 'Monitoring', title: 'Grafana', text: 'Dashboards, from Grafana\'s repository, with the admin password in the vault.',
    packages: ['grafana'], unit: 'grafana-server',
    fields: [F.num('port', 'Port', 3000, [1, 65535]), F.text('domain', 'Address', { pattern: 'host', placeholder: 'grafana.example.com' }), F.lines('from', 'Allowed from', { pattern: 'cidr' })],
    needs: () => [{ type: 'hostSecret', name: 'grafana admin', label: 'Grafana admin password' }],
    before: () => [
      T.file('Make the folder for signing keys', { path: '/etc/apt/keyrings', state: 'directory', mode: '0755' }),
      { name: 'Download the signing key of Grafana', 'ansible.builtin.get_url': { url: 'https://apt.grafana.com/gpg.key', dest: '/etc/apt/keyrings/grafana.asc', mode: '0644' } },
      T.copy('Add the Grafana repository', '/etc/apt/sources.list.d/grafana.list', 'deb [signed-by=/etc/apt/keyrings/grafana.asc] https://apt.grafana.com stable main\n')
    ],
    files: v => [{ dest: '/etc/default/grafana-server', mode: '0640', group: 'grafana', noLog: true, content: conf(['GRAFANA_USER=grafana', 'GRAFANA_GROUP=grafana', 'GRAFANA_HOME=/usr/share/grafana', 'LOG_DIR=/var/log/grafana', 'DATA_DIR=/var/lib/grafana', 'CONF_DIR=/etc/grafana', 'CONF_FILE=/etc/grafana/grafana.ini', 'PID_FILE_DIR=/run/grafana', 'RESTART_ON_UPGRADE=true',
      `GF_SERVER_HTTP_PORT=${v.port}`, v.domain ? `GF_SERVER_DOMAIN=${v.domain}` : null, "GF_SECURITY_ADMIN_PASSWORD={{ fp_host_secret['grafana admin'] }}", 'GF_ANALYTICS_REPORTING_ENABLED=false']) }],
    ports: v => [{ port: v.port, proto: 'tcp', from: v.from, label: 'Grafana' }],
    summary: v => `Port ${v.port}`
  }),
  service({
    id: 'zabbix', group: 'Monitoring', title: 'Zabbix agent', text: 'The agent for your Zabbix server.',
    packages: ['zabbix-agent'], unit: 'zabbix-agent',
    fields: [F.text('server', 'Zabbix server', { pattern: 'host', required: true, placeholder: 'zabbix.example.com' }), F.bool('active', 'Active checks too', true), F.text('hostname', 'Name in Zabbix', { pattern: 'host', default: '{{ fp_name }}' })],
    files: v => [{ dest: '/etc/zabbix/zabbix_agentd.conf.d/fleetpilot.conf', content: conf([`Server=${v.server}`, v.active ? `ServerActive=${v.server}` : 'ServerActive=', `Hostname=${v.hostname}`]) }],
    ports: v => [{ port: 10050, proto: 'tcp', from: [], label: 'Zabbix' }],
    summary: v => v.server
  }),

  // ---------------------------------------------------------------- Security and mail
  service({
    id: 'clamav', group: 'Security and mail', title: 'ClamAV', text: 'Virus scanner with daily signature updates.',
    packages: ['clamav', 'clamav-daemon', 'clamav-freshclam'], unit: 'clamav-freshclam',
    fields: [F.num('checks', 'Signature updates per day', 12, [1, 50]), F.bool('daemon', 'Run the scanning daemon (needs about 1.5 GB memory)', false)],
    after: v => [T.line('Set the update interval', { path: '/etc/clamav/freshclam.conf', regexp: '^Checks ', line: `Checks ${v.checks}` }, { notify: 'Restart clamav-freshclam' }), T.service('clamav-daemon', { state: v.daemon ? 'started' : 'stopped', enabled: v.daemon, name: v.daemon ? 'Start the scanning daemon' : 'Stop the scanning daemon' })],
    summary: v => `${v.checks} updates a day${v.daemon ? ', daemon on' : ''}`
  }),
  service({
    id: 'postfix', group: 'Security and mail', title: 'Mail relay (Postfix)', text: 'Sends the host\'s mail (cron, alerts) through your mail server.',
    packages: ['postfix', 'bsd-mailx'], unit: 'postfix',
    fields: [F.text('relay', 'Mail server', { pattern: 'any', required: true, placeholder: '[smtp.example.com]:587' }), F.text('from', 'Domain of the sender', { pattern: 'host', placeholder: 'example.com' }), F.text('root', 'Mail for root goes to', { pattern: 'any', placeholder: 'ops@example.com' })],
    after: v => [
      ...[['relayhost', v.relay], ['inet_interfaces', 'loopback-only'], ['mydestination', ''], ['myhostname', '{{ fp_fqdn }}'], ...(v.from ? [['myorigin', v.from]] : [])]
        .map(([k, val]) => T.line(`Set ${k}`, { path: '/etc/postfix/main.cf', regexp: `^${k}\\s*=`, line: `${k} = ${val}` }, { notify: 'Restart postfix' })),
      ...(v.root ? [T.line('Forward mail for root', { path: '/etc/aliases', regexp: '^root:', line: `root: ${v.root}` }, { notify: 'Update the mail aliases' })] : [])
    ],
    summary: v => `Through ${v.relay}`
  }),

  // ---------------------------------------------------------------- Tools for virtual machines and administration
  service({
    id: 'qemuagent', group: 'Virtual machines', title: 'QEMU guest agent', text: 'Lets Proxmox and KVM see the addresses of the VM and shut it down cleanly.',
    packages: ['qemu-guest-agent'], unit: 'qemu-guest-agent', fields: [], summary: () => 'On',
    // Only a VM has the agent's device: on other machines it is installed, not started
    startWhen: "ansible_facts.virtualization_role == 'guest' and ansible_facts.virtualization_type in ['kvm', 'qemu']"
  }),
  service({
    id: 'vmtools', group: 'Virtual machines', title: 'VMware tools', text: 'open-vm-tools for VMs on VMware.',
    packages: ['open-vm-tools'], unit: 'open-vm-tools', fields: [], summary: () => 'On',
    startWhen: "ansible_facts.virtualization_type == 'VMware'"
  }),
  service({
    id: 'cockpit', group: 'Virtual machines', title: 'Cockpit', text: 'A web console for the host.',
    packages: ['cockpit'], unit: 'cockpit.socket',
    fields: [F.num('port', 'Port', 9090, [1, 65535]), F.lines('from', 'Allowed from', { pattern: 'cidr' })],
    files: v => [{ dir: true, dest: '/etc/systemd/system/cockpit.socket.d' }, { dest: '/etc/systemd/system/cockpit.socket.d/listen.conf', content: conf(['[Socket]', 'ListenStream=', `ListenStream=${v.port}`]) }],
    ports: v => [{ port: v.port, proto: 'tcp', from: v.from, label: 'Cockpit' }],
    summary: v => `Port ${v.port}`
  }),
  service({
    id: 'lldpd', group: 'Virtual machines', title: 'LLDP', text: 'Tells switches who is connected where, and learns it from them.',
    packages: ['lldpd'], unit: 'lldpd',
    fields: [F.text('description', 'Description', { pattern: 'any', default: '{{ fp_name }}' })],
    files: v => [{ dest: '/etc/lldpd.d/fleetpilot.conf', content: conf([`configure system description ${quote(v.description)}`]) }],
    summary: () => 'On'
  })
];

// Handlers that some services notify but do not restart themselves
export const EXTRA_HANDLERS = {
  'Update the mail aliases': T.cmd('Update the mail aliases', 'newaliases')
};
__FLEETPILOT_FILE_END__
  mkdir -p "$W/server/lib"
  cat > "$W/server/lib/catalog-settings.mjs" <<'__FLEETPILOT_FILE_END__'
// FleetPilot: the setting types of every area except services (catalog-services.mjs).
// A type: { id, area, title, text, fields, single | collect: { field, key }, tasks(v, ctx), summary(v), needs?(v), ports?(v) }
//   single   one per host: the most specific template wins
//   collect  rows of all templates are put together (a later row with the same key wins)
// tasks() returns { tasks, handlers } in ansible.builtin; ctx has ports (all open ports), sshPort.
import { T, F, conf, quote, slug } from './catalog.mjs';

const H = {   // handlers used by several settings
  sysctl: { 'Apply kernel settings': T.cmd('Apply kernel settings', 'sysctl --system') },
  sshd: { 'Reload the SSH server': [T.cmd('Check the SSH server configuration', 'sshd -t'), T.reload('ssh')] },
  daemon: { 'Reload systemd': { name: 'Reload systemd', 'ansible.builtin.systemd': { daemon_reload: true } } }
};
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

export const SETTINGS = [
  // ---------------------------------------------------------------- System
  {
    id: 'hostname', area: 'system', single: true, title: 'Host name',
    text: 'Sets the host name from FleetPilot and the matching line in /etc/hosts.',
    fields: [
      F.text('domain', 'Domain', { pattern: 'host', placeholder: 'example.com', help: 'Empty: the domain of the host\'s subnet, if it has one.' }),
      F.bool('hostsLine', 'Write the name into /etc/hosts (127.0.1.1)', true)
    ],
    tasks: v => {
      const fqdn = v.domain ? `{{ fp_name }}.${v.domain}` : '{{ fp_fqdn }}';
      return {
        tasks: [
          { name: 'Set the host name', 'ansible.builtin.hostname': { name: '{{ fp_name }}' } },
          ...(v.hostsLine ? [T.line('Name the host in /etc/hosts', { path: '/etc/hosts', unsafe_writes: true, regexp: '^127\\.0\\.1\\.1\\s', line: `127.0.1.1 ${fqdn} {{ fp_name }}` })] : [])
        ]
      };
    },
    summary: v => v.domain ? `The FleetPilot name with the domain ${v.domain}` : 'The FleetPilot name of each host'
  },
  {
    id: 'timezone', area: 'system', single: true, title: 'Time zone',
    text: 'Sets the time zone of the host.',
    fields: [F.text('zone', 'Time zone', { default: 'Etc/UTC', pattern: 'word', placeholder: 'Europe/Zurich', required: true })],
    tasks: v => ({
      tasks: [
        T.file('Set the time zone', { src: `/usr/share/zoneinfo/${v.zone}`, dest: '/etc/localtime', state: 'link', force: true }),
        T.copy('Write /etc/timezone', '/etc/timezone', `${v.zone}\n`)
      ]
    }),
    summary: v => v.zone
  },
  {
    id: 'locale', area: 'system', single: true, title: 'Language and keyboard',
    text: 'The language of messages and formats, more languages to have, and the keyboard layout.',
    fields: [
      F.text('lang', 'Language', { default: 'en_US.UTF-8', pattern: 'word', required: true }),
      F.lines('extra', 'More languages to generate', { pattern: 'word', placeholder: 'de_CH.UTF-8' }),
      F.text('keyboard', 'Keyboard layout', { default: 'us', pattern: 'word', placeholder: 'ch' }),
      F.text('variant', 'Keyboard variant', { pattern: 'word', placeholder: 'de' })
    ],
    tasks: v => {
      const locales = [...new Set([v.lang, ...v.extra])];
      return {
        tasks: [
          T.apt(['locales', 'keyboard-configuration'], 'present', 'Install the language support'),
          ...locales.map(l => T.line(`Offer the language ${l}`, { path: '/etc/locale.gen', regexp: `^#?\\s*${l.replace(/\./g, '\\.')}\\s`, line: `${l} ${l.split('.')[1] || 'UTF-8'}` }, { notify: 'Generate languages' })),
          T.copy('Set the language', '/etc/default/locale', `LANG=${v.lang}\n`),
          ...(v.keyboard ? [T.copy('Set the keyboard layout', '/etc/default/keyboard', conf([`XKBMODEL="pc105"`, `XKBLAYOUT=${quote(v.keyboard)}`, `XKBVARIANT=${quote(v.variant)}`, 'XKBOPTIONS=""', 'BACKSPACE="guess"']))] : [])
        ],
        handlers: { 'Generate languages': T.cmd('Generate languages', 'locale-gen') }
      };
    },
    summary: v => `${v.lang}${v.keyboard ? `, keyboard ${v.keyboard}${v.variant ? ` ${v.variant}` : ''}` : ''}`
  },
  {
    id: 'ntp', area: 'system', single: true, title: 'Time servers',
    text: 'Keeps the clock right with chrony and the time servers you name.',
    fields: [
      F.lines('servers', 'Time servers', { pattern: 'host', placeholder: 'ntp.example.com', default: [] , help: 'One per line. Empty: the public Debian pool.' }),
      F.bool('only', 'Use only these servers (not the public pool)', true),
      F.bool('serve', 'Serve the time to other hosts', false),
      F.lines('allow', 'Networks that may ask for the time', { pattern: 'cidr', when: { serve: true } })
    ],
    tasks: v => ({
      tasks: [
        T.apt(['chrony']),
        T.copy('Name the time servers', '/etc/chrony/sources.d/fleetpilot.sources', conf(v.servers.map(s => `server ${s} iburst`)), { notify: 'Restart chrony' }),
        ...(v.only && v.servers.length ? [{ name: 'Use only the named time servers', 'ansible.builtin.replace': { path: '/etc/chrony/chrony.conf', regexp: '^(pool|server) ', replace: '#\\1 ' }, notify: ['Restart chrony'] }] : []),
        T.copy('Serve the time', '/etc/chrony/conf.d/fleetpilot.conf', conf(v.serve ? (v.allow.length ? v.allow.map(a => `allow ${a}`) : ['allow']) : ['# Not serving the time']), { notify: 'Restart chrony' }),
        T.service('chrony')
      ],
      handlers: { 'Restart chrony': T.restart('chrony') }
    }),
    ports: v => v.serve ? [{ port: 123, proto: 'udp', from: v.allow }] : [],
    summary: v => v.servers.length ? `${v.servers.join(', ')}${v.serve ? ', serves the time' : ''}` : 'The public pool'
  },
  {
    id: 'banner', area: 'system', single: true, title: 'Login messages',
    text: 'The message after login (MOTD), and a notice before login on the console and over SSH.',
    fields: [
      F.area('motd', 'After login', { placeholder: 'Managed by FleetPilot. Changes by hand are overwritten.' }),
      F.area('notice', 'Before login', { placeholder: 'Authorized use only. Activity is logged.' }),
      F.bool('ssh', 'Show the notice before an SSH login too', true)
    ],
    tasks: v => ({
      tasks: [
        T.copy('Write the message after login', '/etc/motd', v.motd ? v.motd.replace(/\n?$/, '\n') : ''),
        T.copy('Write the notice before login', '/etc/issue.net', v.notice ? v.notice.replace(/\n?$/, '\n') : ''),
        T.copy('Write the notice for the console', '/etc/issue', v.notice ? v.notice.replace(/\n?$/, '\n') : '\\S\nKernel \\r on an \\m\n\n'),
        T.copy('Show the notice over SSH', '/etc/ssh/sshd_config.d/05-fleetpilot-banner.conf', conf([v.ssh && v.notice ? 'Banner /etc/issue.net' : 'Banner none']), { notify: 'Reload the SSH server' })
      ],
      handlers: H.sshd
    }),
    summary: v => [v.motd && 'after login', v.notice && 'before login'].filter(Boolean).join(' and ') || 'No messages'
  },
  {
    id: 'sysctl', area: 'system', collect: { field: 'values', key: 'key' }, title: 'Kernel settings',
    text: 'Values for /proc/sys (sysctl), kept in /etc/sysctl.d/90-fleetpilot.conf.',
    fields: [F.rows('values', 'Settings', [F.text('key', 'Key', { pattern: 'word', required: true, placeholder: 'net.ipv4.ip_forward' }), F.text('value', 'Value', { pattern: 'any', placeholder: '1' })])],
    tasks: v => ({
      tasks: [T.copy('Write the kernel settings', '/etc/sysctl.d/90-fleetpilot.conf', conf(v.values.map(r => `${r.key} = ${r.value}`)), { notify: 'Apply kernel settings' })],
      handlers: H.sysctl
    }),
    summary: v => plural(v.values.length, 'value', 'values')
  },
  {
    id: 'modules', area: 'system', collect: { field: 'modules', key: 'name' }, title: 'Kernel modules',
    text: 'Modules to load at boot, and modules that must never load.',
    fields: [F.rows('modules', 'Modules', [F.text('name', 'Module', { pattern: 'name', required: true, placeholder: 'br_netfilter' }), F.select('mode', 'Then', [['load', 'Load at boot'], ['block', 'Never load']])])],
    tasks: v => ({
      tasks: [
        T.file('Make the folder for modules to load', { path: '/etc/modules-load.d', state: 'directory', mode: '0755' }),
        T.file('Make the folder for module rules', { path: '/etc/modprobe.d', state: 'directory', mode: '0755' }),
        T.copy('Load modules at boot', '/etc/modules-load.d/fleetpilot.conf', conf(v.modules.filter(m => m.mode === 'load').map(m => m.name))),
        T.copy('Block modules', '/etc/modprobe.d/fleetpilot-blocked.conf', conf(v.modules.filter(m => m.mode === 'block').flatMap(m => [`blacklist ${m.name}`, `install ${m.name} /bin/false`]))),
        ...v.modules.filter(m => m.mode === 'load').map(m => T.cmd(`Load ${m.name} now`, `modprobe ${m.name}`, { changed: false }))
      ]
    }),
    summary: v => v.modules.map(m => m.mode === 'load' ? m.name : `no ${m.name}`).join(', ') || 'None'
  },
  {
    id: 'grub', area: 'system', single: true, title: 'Boot parameters',
    text: 'Kernel parameters in GRUB. They take effect after the next reboot.',
    fields: [F.text('params', 'Parameters', { pattern: 'any', placeholder: 'quiet net.ifnames=0 console=ttyS0', default: 'quiet' })],
    tasks: v => ({
      tasks: [T.line('Set the boot parameters', { path: '/etc/default/grub', regexp: '^GRUB_CMDLINE_LINUX_DEFAULT=', line: `GRUB_CMDLINE_LINUX_DEFAULT=${quote(v.params)}` }, { notify: 'Update GRUB' })],
      handlers: { 'Update GRUB': T.cmd('Update GRUB', 'update-grub') }
    }),
    summary: v => v.params || 'No parameters'
  },
  {
    id: 'swap', area: 'system', single: true, title: 'Swap',
    text: 'A swap file of the size you choose, and how eagerly the kernel uses it.',
    fields: [F.num('size', 'Swap file in MB (0: none)', 0, [0, 262144]), F.num('swappiness', 'Swappiness', 60, [0, 200], { help: '0 to 200. Lower keeps more in memory.' })],
    tasks: v => ({
      tasks: [
        ...(v.size > 0 ? [
          T.cmd('Make the swap file', `fallocate -l ${v.size}M /swapfile`, { creates: '/swapfile' }),
          T.file('Protect the swap file', { path: '/swapfile', mode: '0600', owner: 'root', group: 'root' }),
          T.shell('Prepare the swap file', 'blkid /swapfile | grep -q swap || { mkswap /swapfile >/dev/null; echo made; }', { register: 'fp_swap', changedWhen: "'made' in fp_swap.stdout" }),
          T.line('Use the swap file at boot', { path: '/etc/fstab', regexp: '^/swapfile\\s', line: '/swapfile none swap sw 0 0' }),
          T.shell('Turn the swap file on', 'swapon --show=NAME --noheadings | grep -qx /swapfile || swapon /swapfile', { changed: false })
        ] : []),
        T.copy('Set the swappiness', '/etc/sysctl.d/91-fleetpilot-swap.conf', conf([`vm.swappiness = ${v.swappiness}`]), { notify: 'Apply kernel settings' })
      ],
      handlers: H.sysctl
    }),
    summary: v => `${v.size ? `${v.size} MB swap file` : 'No swap file'}, swappiness ${v.swappiness}`
  },
  {
    id: 'journald', area: 'system', single: true, title: 'System log',
    text: 'How much the systemd journal keeps, and for how long.',
    fields: [
      F.text('maxUse', 'At most', { default: '500M', pattern: 'duration' }),
      F.text('retention', 'For at most', { default: '1month', pattern: 'duration' }),
      F.bool('persistent', 'Keep the log across reboots', true),
      F.bool('syslog', 'Also hand messages to syslog', false)
    ],
    tasks: v => ({
      tasks: [
        T.file('Make the folder for journal settings', { path: '/etc/systemd/journald.conf.d', state: 'directory', mode: '0755' }),
        T.copy('Set the journal limits', '/etc/systemd/journald.conf.d/fleetpilot.conf', conf(['[Journal]', `Storage=${v.persistent ? 'persistent' : 'volatile'}`, `SystemMaxUse=${v.maxUse}`, `MaxRetentionSec=${v.retention}`, `ForwardToSyslog=${v.syslog ? 'yes' : 'no'}`]), { notify: 'Restart journald' })
      ],
      handlers: { 'Restart journald': T.restart('systemd-journald') }
    }),
    summary: v => `${v.maxUse}, ${v.retention}${v.persistent ? ', kept across reboots' : ''}`
  },
  {
    id: 'proxy', area: 'system', single: true, title: 'Proxy',
    text: 'A proxy for package downloads and for programs that read http_proxy.',
    fields: [
      F.text('http', 'HTTP proxy', { pattern: 'url', placeholder: 'http://proxy.example.com:3128' }),
      F.text('https', 'HTTPS proxy', { pattern: 'url', placeholder: 'Empty: the same as HTTP' }),
      F.text('noProxy', 'Not for', { pattern: 'word', default: 'localhost,127.0.0.1', placeholder: 'localhost,127.0.0.1,.example.com' }),
      F.bool('apt', 'Use it for packages', true)
    ],
    tasks: v => {
      const https = v.https || v.http;
      return {
        tasks: [
          T.copy('Set the proxy for programs', '/etc/profile.d/fleetpilot-proxy.sh', conf(v.http ? [`export http_proxy=${quote(v.http)} HTTP_PROXY=${quote(v.http)}`, `export https_proxy=${quote(https)} HTTPS_PROXY=${quote(https)}`, `export no_proxy=${quote(v.noProxy)} NO_PROXY=${quote(v.noProxy)}`] : [])),
          ...['http_proxy', 'https_proxy', 'no_proxy'].map(k => T.line(`Set ${k} for services`, v.http ? { path: '/etc/environment', regexp: `^${k}=`, line: `${k}=${k === 'no_proxy' ? v.noProxy : k === 'https_proxy' ? https : v.http}` } : { path: '/etc/environment', regexp: `^${k}=`, state: 'absent' })),
          T.copy('Set the proxy for packages', '/etc/apt/apt.conf.d/90fleetpilot-proxy', conf(v.http && v.apt ? [`Acquire::http::Proxy ${quote(v.http)};`, `Acquire::https::Proxy ${quote(https)};`] : [], '//'))
        ]
      };
    },
    summary: v => v.http || 'No proxy'
  },
  {
    id: 'hosts', area: 'system', collect: { field: 'entries', key: 'ip' }, title: 'Entries in /etc/hosts',
    text: 'Names for addresses, without DNS.',
    fields: [F.rows('entries', 'Entries', [F.text('ip', 'Address', { pattern: 'ip', required: true, placeholder: '10.20.0.5' }), F.text('names', 'Names', { pattern: 'any', placeholder: 'db.example.com db' })])],
    tasks: v => ({ tasks: [T.block('Write the entries into /etc/hosts', { path: '/etc/hosts', unsafe_writes: true, marker: '# {mark} FleetPilot entries', block: v.entries.map(e => `${e.ip} ${e.names}`).join('\n') })] }),
    summary: v => plural(v.entries.length, 'entry', 'entries')
  },
  {
    id: 'reboot', area: 'system', single: true, title: 'Reboot when needed',
    text: 'Reboots the host at the end when installed updates ask for it (/var/run/reboot-required).',
    fields: [F.bool('allowed', 'Reboot when needed', true), F.num('timeout', 'Wait for the host at most (seconds)', 600, [60, 3600])],
    tasks: v => ({
      tasks: v.allowed ? [
        { name: 'Find out whether a reboot is needed', 'ansible.builtin.stat': { path: '/var/run/reboot-required' }, register: 'fp_reboot' },
        { name: 'Reboot because updates need it', 'ansible.builtin.reboot': { reboot_timeout: v.timeout, msg: 'Reboot by FleetPilot: updates need it' }, when: 'fp_reboot.stat.exists' }
      ] : []
    }),
    summary: v => v.allowed ? 'Reboots when updates need it' : 'Never reboots by itself'
  },

  // ---------------------------------------------------------------- Network (the files are written by network.mjs)
  {
    id: 'interface', area: 'network', single: true, title: 'Address of the host',
    text: 'The main interface: an address from IP management, a fixed one, or DHCP.',
    fields: [
      F.select('method', 'Address', [['ipam', 'From IP management (the host\'s address)'], ['static', 'A fixed address'], ['dhcp', 'DHCP']]),
      F.text('address', 'Fixed address with prefix', { pattern: 'cidr', placeholder: '10.20.0.11/24', when: { method: 'static' } }),
      F.text('gateway', 'Gateway', { pattern: 'ip', placeholder: 'Empty: the subnet\'s gateway', when: { method: ['static', 'ipam'] } }),
      F.text('name', 'Interface', { pattern: 'iface', placeholder: 'Empty: the one with the default route' }),
      F.num('mtu', 'MTU', 0, [0, 9216], { help: '0: leave it as it is' }),
      F.select('ipv6', 'IPv6', [['auto', 'Automatic (router advertisements)'], ['off', 'Off on this interface']])
    ],
    summary: v => ({ ipam: 'Address from IP management', static: `Fixed ${v.address}`, dhcp: 'DHCP' }[v.method])
  },
  {
    id: 'vlans', area: 'network', collect: { field: 'vlans', key: 'id' }, title: 'VLAN interfaces',
    text: 'Tagged VLANs on a physical interface, a bond or a bridge.',
    fields: [F.rows('vlans', 'VLANs', [
      F.num('id', 'VLAN', 10, [1, 4094], { required: true }), F.text('parent', 'On', { pattern: 'iface', placeholder: 'ens18' }),
      F.select('method', 'Address', [['none', 'No address'], ['static', 'Fixed'], ['dhcp', 'DHCP']]), F.text('address', 'Address with prefix', { pattern: 'cidr', placeholder: '10.30.0.11/24' })
    ])],
    summary: v => v.vlans.map(x => `VLAN ${x.id}`).join(', ') || 'None'
  },
  {
    id: 'bonds', area: 'network', collect: { field: 'bonds', key: 'name' }, title: 'Bonds',
    text: 'Several interfaces as one, for more bandwidth or a spare link.',
    fields: [F.rows('bonds', 'Bonds', [
      F.text('name', 'Name', { pattern: 'iface', required: true, placeholder: 'bond0' }), F.text('members', 'Interfaces', { pattern: 'word', placeholder: 'ens18,ens19' }),
      F.select('mode', 'Mode', [['active-backup', 'Active and spare'], ['802.3ad', 'LACP (802.3ad)'], ['balance-alb', 'Adaptive load balancing']]),
      F.select('method', 'Address', [['none', 'No address'], ['static', 'Fixed'], ['dhcp', 'DHCP']]), F.text('address', 'Address with prefix', { pattern: 'cidr' })
    ])],
    summary: v => v.bonds.map(b => `${b.name} (${b.members})`).join(', ') || 'None'
  },
  {
    id: 'bridges', area: 'network', collect: { field: 'bridges', key: 'name' }, title: 'Bridges',
    text: 'Bridges for virtual machines and containers.',
    fields: [F.rows('bridges', 'Bridges', [
      F.text('name', 'Name', { pattern: 'iface', required: true, placeholder: 'br0' }), F.text('ports', 'Ports', { pattern: 'word', placeholder: 'ens19' }),
      F.select('method', 'Address', [['none', 'No address'], ['static', 'Fixed'], ['dhcp', 'DHCP']]), F.text('address', 'Address with prefix', { pattern: 'cidr' })
    ])],
    summary: v => v.bridges.map(b => b.name).join(', ') || 'None'
  },
  {
    id: 'routes', area: 'network', collect: { field: 'routes', key: 'to' }, title: 'Static routes',
    text: 'Routes to other networks through a gateway.',
    fields: [F.rows('routes', 'Routes', [F.text('to', 'Network', { pattern: 'cidr', required: true, placeholder: '10.50.0.0/16' }), F.text('via', 'Through', { pattern: 'ip', placeholder: '10.20.0.254' }), F.text('dev', 'Interface', { pattern: 'iface', placeholder: 'Empty: the main one' })])],
    summary: v => v.routes.map(r => `${r.to} via ${r.via}`).join(', ') || 'None'
  },
  {
    id: 'dns', area: 'network', single: true, title: 'Name resolution',
    text: 'DNS servers and search domains. Empty fields take the values of the host\'s subnet.',
    fields: [F.lines('servers', 'DNS servers', { pattern: 'ip', placeholder: '10.20.0.53' }), F.lines('search', 'Search domains', { pattern: 'host', placeholder: 'example.com' })],
    summary: v => v.servers.length ? v.servers.join(', ') : 'From the subnet'
  },
  {
    id: 'ipv6', area: 'network', single: true, title: 'IPv6 on the host',
    text: 'Turns IPv6 off on all interfaces when your networks do not use it.',
    fields: [F.bool('disable', 'Turn IPv6 off', false)],
    tasks: v => ({ tasks: [T.copy('Set IPv6', '/etc/sysctl.d/93-fleetpilot-ipv6.conf', conf(v.disable ? ['net.ipv6.conf.all.disable_ipv6 = 1', 'net.ipv6.conf.default.disable_ipv6 = 1'] : ['# IPv6 stays on']), { notify: 'Apply kernel settings' })], handlers: H.sysctl }),
    summary: v => v.disable ? 'Off' : 'On'
  },

  // ---------------------------------------------------------------- Access
  {
    id: 'users', area: 'access', collect: { field: 'users', key: 'username' }, title: 'Users',
    text: 'Local accounts, their groups, sudo rights and a first password that FleetPilot makes and keeps in the vault.',
    fields: [F.rows('users', 'Users', [
      F.text('username', 'User', { pattern: 'user', required: true, placeholder: 'alice' }),
      F.text('name', 'Full name', { pattern: 'any', placeholder: 'Alice Doe' }),
      F.text('groups', 'Groups', { pattern: 'word', placeholder: 'adm,systemd-journal' }),
      F.select('sudo', 'sudo', [['none', 'No sudo'], ['password', 'With password'], ['nopassword', 'Without password']]),
      F.select('shell', 'Shell', [['/bin/bash', 'bash'], ['/bin/sh', 'sh'], ['/usr/bin/zsh', 'zsh'], ['/usr/sbin/nologin', 'No login']]),
      F.select('state', 'State', [['present', 'Present'], ['absent', 'Removed'], ['locked', 'Locked']])
    ])],
    needs: v => v.users.filter(u => u.state !== 'absent').map(u => ({ type: 'password', name: u.username, generate: true })),
    tasks: v => {
      const tasks = [];
      if (v.users.some(u => u.sudo !== 'none' && u.state === 'present')) tasks.push(T.apt(['sudo']));
      for (const u of v.users) {
        const groups = u.groups.split(',').map(g => g.trim()).filter(Boolean);
        if (u.state === 'absent') {
          tasks.push({ name: `Remove the user ${u.username}`, 'ansible.builtin.user': { name: u.username, state: 'absent', remove: false } });
          tasks.push(T.file(`Remove the sudo rights of ${u.username}`, { path: `/etc/sudoers.d/fp-${u.username}`, state: 'absent' }));
          continue;
        }
        tasks.push({ name: `Create the user ${u.username}`, 'ansible.builtin.user': { name: u.username, comment: u.name, shell: u.shell, groups, append: true, password: `{{ fp_passwords['${u.username}'] | default(omit) }}`, update_password: 'on_create', password_lock: u.state === 'locked' }, no_log: true });
        tasks.push(u.sudo === 'none'
          ? T.file(`No sudo for ${u.username}`, { path: `/etc/sudoers.d/fp-${u.username}`, state: 'absent' })
          : T.copy(`Give ${u.username} sudo`, `/etc/sudoers.d/fp-${u.username}`, conf([`${u.username} ALL=(ALL:ALL) ${u.sudo === 'nopassword' ? 'NOPASSWD: ' : ''}ALL`]), { mode: '0440', validate: 'visudo -cf %s' }));
      }
      return { tasks };
    },
    summary: v => v.users.map(u => u.username).join(', ') || 'None'
  },
  {
    id: 'groups', area: 'access', collect: { field: 'groups', key: 'name' }, title: 'Groups',
    text: 'Local groups, for example for shared folders.',
    fields: [F.rows('groups', 'Groups', [F.text('name', 'Group', { pattern: 'user', required: true, placeholder: 'developers' }), F.num('gid', 'Group id', 0, [0, 4294967294], { help: '0: chosen by the system' }), F.select('state', 'State', [['present', 'Present'], ['absent', 'Removed']])])],
    tasks: v => ({ tasks: v.groups.map(g => ({ name: `${g.state === 'absent' ? 'Remove' : 'Create'} the group ${g.name}`, 'ansible.builtin.group': { name: g.name, state: g.state, ...(g.gid ? { gid: g.gid } : {}) } })) }),
    summary: v => v.groups.map(g => g.name).join(', ') || 'None'
  },
  {
    id: 'root', area: 'access', single: true, title: 'The root account',
    text: 'Whether root may log in with a password at all. Its password is set by the workflow "Rotate passwords".',
    fields: [F.bool('lock', 'Lock the root password (use sudo instead)', false)],
    tasks: v => ({ tasks: [{ name: v.lock ? 'Lock the root password' : 'Leave the root password usable', 'ansible.builtin.user': { name: 'root', password_lock: v.lock } }] }),
    summary: v => v.lock ? 'Password locked' : 'Password usable'
  },
  {
    id: 'keys', area: 'access', collect: { field: 'keys', key: 'key' }, title: 'Authorized SSH keys',
    text: 'Public keys that may log in as a user.',
    fields: [
      F.rows('keys', 'Keys', [F.text('user', 'User', { pattern: 'user', required: true, placeholder: 'alice' }), F.text('key', 'Public key', { pattern: 'any', maxLength: 2000, required: true, placeholder: 'ssh-ed25519 AAAA… alice@laptop' })]),
      F.bool('exclusive', 'Remove keys that are not listed here (FleetPilot\'s own key stays)', false)
    ],
    tasks: v => {
      const users = [...new Set(v.keys.map(k => k.user))];
      return {
        tasks: users.flatMap(u => [
          T.file(`Make the SSH folder of ${u}`, { path: `~${u}/.ssh`, state: 'directory', owner: u, group: u, mode: '0700' }),
          v.exclusive
            ? T.copy(`Set the keys of ${u}`, `~${u}/.ssh/authorized_keys`, [...v.keys.filter(k => k.user === u).map(k => k.key), ...(u === 'fleetpilot' ? ['{{ fp_ssh_public_key }}'] : [])].join('\n') + '\n', { owner: u, group: u, mode: '0600' })
            : T.block(`Add the keys of ${u}`, { path: `~${u}/.ssh/authorized_keys`, create: true, owner: u, group: u, mode: '0600', marker: '# {mark} FleetPilot keys', block: v.keys.filter(k => k.user === u).map(k => k.key).join('\n') })
        ])
      };
    },
    summary: v => plural(v.keys.length, 'key', 'keys')
  },
  {
    id: 'sshd', area: 'access', single: true, title: 'SSH server',
    text: 'Port, password and root logins, who may log in, and modern ciphers only.',
    fields: [
      F.num('port', 'Port', 22, [1, 65535]),
      F.bool('passwords', 'Allow logins with a password', false),
      F.select('root', 'Root login', [['prohibit-password', 'Only with a key'], ['no', 'Never'], ['yes', 'Also with a password']]),
      F.text('allowUsers', 'Only these users', { pattern: 'word', placeholder: 'Empty: everybody. alice,bob' }),
      F.text('allowGroups', 'Only these groups', { pattern: 'word', placeholder: 'sshusers' }),
      F.num('maxTries', 'Attempts per connection', 4, [1, 20]),
      F.num('idle', 'End idle sessions after (minutes, 0: never)', 0, [0, 1440]),
      F.bool('forwarding', 'Allow forwarding (tunnels, agent, X11)', false),
      F.bool('modern', 'Only modern ciphers and key exchanges', true)
    ],
    tasks: v => {
      const users = v.allowUsers ? [...new Set([...v.allowUsers.split(','), 'fleetpilot'])].join(' ') : '';
      return {
        tasks: [T.copy('Configure the SSH server', '/etc/ssh/sshd_config.d/10-fleetpilot.conf', conf([
          `Port ${v.port}`,
          `PasswordAuthentication ${v.passwords ? 'yes' : 'no'}`,
          `KbdInteractiveAuthentication ${v.passwords ? 'yes' : 'no'}`,
          `PermitRootLogin ${v.root}`,
          users ? `AllowUsers ${users}` : null,
          v.allowGroups ? `AllowGroups ${v.allowGroups.split(',').join(' ')}` : null,
          `MaxAuthTries ${v.maxTries}`,
          v.idle ? `ClientAliveInterval 60\nClientAliveCountMax ${v.idle}` : null,
          `AllowTcpForwarding ${v.forwarding ? 'yes' : 'no'}`, `AllowAgentForwarding ${v.forwarding ? 'yes' : 'no'}`, `X11Forwarding ${v.forwarding ? 'yes' : 'no'}`,
          v.modern ? 'KexAlgorithms sntrup761x25519-sha512@openssh.com,curve25519-sha256,curve25519-sha256@libssh.org\nCiphers chacha20-poly1305@openssh.com,aes256-gcm@openssh.com,aes128-gcm@openssh.com\nMACs hmac-sha2-512-etm@openssh.com,hmac-sha2-256-etm@openssh.com' : null
        ]), { notify: 'Reload the SSH server' })],
        handlers: H.sshd
      };
    },
    ports: v => [{ port: v.port, proto: 'tcp', ssh: true }],
    summary: v => `Port ${v.port}, ${v.passwords ? 'passwords allowed' : 'keys only'}, root ${({ 'prohibit-password': 'with a key', no: 'never', yes: 'with a password' })[v.root]}`
  },
  {
    id: 'sudo', area: 'access', single: true, title: 'sudo rules',
    text: 'How long sudo remembers a password, and whether every command is logged.',
    fields: [F.num('timeout', 'Remember the password for (minutes)', 15, [0, 1440]), F.bool('log', 'Log every command with its output', false), F.bool('lecture', 'Show the warning at the first use', true)],
    tasks: v => ({
      tasks: [T.apt(['sudo']), T.copy('Set the sudo rules', '/etc/sudoers.d/00-fleetpilot', conf([`Defaults timestamp_timeout=${v.timeout}`, v.log ? 'Defaults log_output\nDefaults!/usr/bin/sudoreplay !log_output\nDefaults logfile=/var/log/sudo.log' : null, `Defaults lecture=${v.lecture ? 'once' : 'never'}`]), { mode: '0440', validate: 'visudo -cf %s' })]
    }),
    summary: v => `${v.timeout} min${v.log ? ', every command logged' : ''}`
  },
  {
    id: 'pwquality', area: 'access', single: true, title: 'Password rules on the host',
    text: 'How strong the passwords of local users must be (pwquality).',
    fields: [F.num('minlen', 'Shortest password', 12, [6, 64]), F.num('minclass', 'Kinds of characters (lower, upper, digits, others)', 0, [0, 4]), F.num('maxrepeat', 'At most the same character in a row (0: any)', 3, [0, 10]), F.bool('dictcheck', 'Refuse dictionary words', true)],
    tasks: v => ({
      tasks: [T.apt(['libpam-pwquality']), T.file('Make the folder for password rules', { path: '/etc/security/pwquality.conf.d', state: 'directory', mode: '0755' }),
        T.copy('Set the password rules', '/etc/security/pwquality.conf.d/fleetpilot.conf', conf([`minlen = ${v.minlen}`, `minclass = ${v.minclass}`, `maxrepeat = ${v.maxrepeat}`, `dictcheck = ${v.dictcheck ? 1 : 0}`, 'enforce_for_root']))]
    }),
    summary: v => `At least ${v.minlen} characters`
  },
  {
    id: 'faillock', area: 'access', single: true, title: 'Lockout after wrong passwords',
    text: 'Locks a local account for a while after wrong passwords (pam_faillock).',
    fields: [F.num('deny', 'Wrong passwords before the lock', 5, [1, 50]), F.num('unlock', 'Locked for (seconds)', 900, [0, 86400]), F.bool('root', 'Lock root too', false)],
    tasks: v => ({
      tasks: [
        T.copy('Set the lockout', '/etc/security/faillock.conf', conf([`deny = ${v.deny}`, `unlock_time = ${v.unlock}`, v.root ? 'even_deny_root' : null, 'audit', 'silent'])),
        T.copy('Describe the lockout for PAM', '/usr/share/pam-configs/faillock', 'Name: Lock accounts after wrong passwords (FleetPilot)\nDefault: yes\nPriority: 0\nAuth-Type: Primary\nAuth:\n\t[default=die]\tpam_faillock.so authfail\n', { notify: 'Update PAM' }),
        T.copy('Describe the lockout check for PAM', '/usr/share/pam-configs/faillock_notify', 'Name: Check the account lockout (FleetPilot)\nDefault: yes\nPriority: 1024\nAuth-Type: Primary\nAuth:\n\trequisite\tpam_faillock.so preauth\nAccount-Type: Primary\nAccount:\n\trequired\tpam_faillock.so\n', { notify: 'Update PAM' })
      ],
      handlers: { 'Update PAM': T.cmd('Update PAM', 'pam-auth-update --package --enable faillock faillock_notify') }
    }),
    summary: v => `${v.deny} attempts, ${Math.round(v.unlock / 60)} min`
  },
  {
    id: 'timeout', area: 'access', single: true, title: 'Idle shells',
    text: 'Ends idle shell sessions on the console and over SSH.',
    fields: [F.num('minutes', 'After (minutes, 0: never)', 15, [0, 1440])],
    tasks: v => ({ tasks: [T.copy('Set the idle time', '/etc/profile.d/fleetpilot-timeout.sh', conf(v.minutes ? [`TMOUT=${v.minutes * 60}`, 'readonly TMOUT', 'export TMOUT'] : []))] }),
    summary: v => v.minutes ? `${v.minutes} min` : 'Never'
  },
  {
    id: 'certlogin', area: 'access', single: true, title: 'Logins with SSH certificates',
    text: 'People sign in with a short-lived certificate from FleetPilot instead of keys copied to every host.',
    fields: [F.rows('logins', 'Who may log in as whom', [F.text('local', 'Local user', { pattern: 'user', required: true, placeholder: 'root' }), F.text('people', 'FleetPilot users', { pattern: 'word', placeholder: 'alice,bob' })])],
    tasks: v => ({
      tasks: [
        T.file('Make the folder for principals', { path: '/etc/ssh/auth_principals', state: 'directory', mode: '0755' }),
        ...v.logins.map(l => T.copy(`Let FleetPilot users log in as ${l.local}`, `/etc/ssh/auth_principals/${l.local}`, conf([...(l.local === 'fleetpilot' ? ['fleetpilot'] : []), ...l.people.split(',').filter(Boolean).map(p => `fp-${p.trim()}`)])))
      ]
    }),
    summary: v => v.logins.map(l => `${l.people || 'nobody'} as ${l.local}`).join(', ') || 'Nobody'
  },

  // ---------------------------------------------------------------- Packages
  {
    id: 'packages', area: 'packages', collect: { field: 'packages', key: 'name' }, title: 'Packages',
    text: 'Packages to install, keep up to date or remove.',
    fields: [F.rows('packages', 'Packages', [F.text('name', 'Package', { pattern: 'word', required: true, placeholder: 'htop' }), F.select('state', 'State', [['present', 'Installed'], ['latest', 'Always the newest'], ['absent', 'Removed']])])],
    tasks: v => {
      const by = s => v.packages.filter(p => p.state === s).map(p => p.name);
      return { tasks: [['present', 'Install'], ['latest', 'Update'], ['absent', 'Remove']].filter(([s]) => by(s).length).map(([s, verb]) => T.apt(by(s), s, `${verb} ${by(s).join(', ')}`)) };
    },
    summary: v => v.packages.map(p => p.state === 'absent' ? `no ${p.name}` : p.name).join(', ') || 'None'
  },
  {
    id: 'repos', area: 'packages', collect: { field: 'repos', key: 'name' }, title: 'Package sources',
    text: 'More apt repositories, each with its signing key.',
    fields: [F.rows('repos', 'Sources', [
      F.text('name', 'Name', { pattern: 'name', required: true, placeholder: 'docker' }), F.text('url', 'Address', { pattern: 'url', placeholder: 'https://download.docker.com/linux/debian' }),
      F.text('suite', 'Suite', { pattern: 'word', placeholder: 'Empty: the release of the host' }), F.text('components', 'Components', { pattern: 'any', default: 'main' }),
      F.text('key', 'Signing key', { pattern: 'url', placeholder: 'https://download.docker.com/linux/debian/gpg' })
    ])],
    tasks: v => ({
      tasks: [
        T.file('Make the folder for signing keys', { path: '/etc/apt/keyrings', state: 'directory', mode: '0755' }),
        ...v.repos.flatMap(r => [
          ...(r.key ? [{ name: `Download the signing key of ${r.name}`, 'ansible.builtin.get_url': { url: r.key, dest: `/etc/apt/keyrings/fp-${r.name}.asc`, mode: '0644' } }] : []),
          T.copy(`Add the source ${r.name}`, `/etc/apt/sources.list.d/fp-${r.name}.list`, conf([`deb [${r.key ? `signed-by=/etc/apt/keyrings/fp-${r.name}.asc ` : ''}arch={{ 'amd64' if ansible_facts.architecture == 'x86_64' else 'arm64' }}] ${r.url} ${r.suite || '{{ ansible_facts.distribution_release }}'} ${r.components}`]), { notify: 'Update the package lists' })
        ]),
        { name: 'Update the package lists now', 'ansible.builtin.meta': 'flush_handlers' }
      ],
      handlers: { 'Update the package lists': { name: 'Update the package lists', 'ansible.builtin.apt': { update_cache: true } } }
    }),
    summary: v => v.repos.map(r => r.name).join(', ') || 'None'
  },
  {
    id: 'unattended', area: 'packages', single: true, title: 'Automatic updates',
    text: 'Installs updates by itself every day (unattended-upgrades).',
    fields: [
      F.select('scope', 'Which updates', [['security', 'Security updates'], ['all', 'All updates of the release']]),
      F.bool('reboot', 'Reboot by itself when needed', false), F.text('rebootTime', 'At', { pattern: 'word', default: '03:30', when: { reboot: true } }),
      F.bool('removeUnused', 'Remove packages that are no longer needed', true)
    ],
    tasks: v => ({
      tasks: [T.apt(['unattended-upgrades', 'apt-listchanges']),
        T.copy('Switch on the daily updates', '/etc/apt/apt.conf.d/20auto-upgrades', conf(['APT::Periodic::Update-Package-Lists "1";', 'APT::Periodic::Unattended-Upgrade "1";'], '//')),
        T.copy('Choose the automatic updates', '/etc/apt/apt.conf.d/52fleetpilot-unattended', conf([
          'Unattended-Upgrade::Origins-Pattern {', '  "origin=Debian,codename=${distro_codename},label=Debian-Security";', '  "origin=Debian,codename=${distro_codename}-security,label=Debian-Security";', '  "origin=Ubuntu,archive=${distro_codename}-security";',
          ...(v.scope === 'all' ? ['  "origin=Debian,codename=${distro_codename},label=Debian";', '  "origin=Debian,codename=${distro_codename}-updates";', '  "origin=Ubuntu,archive=${distro_codename}-updates";'] : []), '};',
          `Unattended-Upgrade::Automatic-Reboot "${v.reboot}";`, `Unattended-Upgrade::Automatic-Reboot-Time "${v.rebootTime}";`, `Unattended-Upgrade::Remove-Unused-Dependencies "${v.removeUnused}";`], '//'))]
    }),
    summary: v => `${v.scope === 'all' ? 'All' : 'Security'} updates${v.reboot ? `, reboot at ${v.rebootTime}` : ''}`
  },
  {
    id: 'holds', area: 'packages', collect: { field: 'packages', key: 'name' }, title: 'Held packages',
    text: 'Packages that keep their version until you release them.',
    fields: [F.rows('packages', 'Packages', [F.text('name', 'Package', { pattern: 'word', required: true, placeholder: 'postgresql-15' }), F.select('selection', 'State', [['hold', 'Held'], ['install', 'Released']])])],
    tasks: v => ({ tasks: v.packages.map(p => ({ name: `${p.selection === 'hold' ? 'Hold' : 'Release'} ${p.name}`, 'ansible.builtin.dpkg_selections': { name: p.name, selection: p.selection } })) }),
    summary: v => v.packages.filter(p => p.selection === 'hold').map(p => p.name).join(', ') || 'None'
  },

  // ---------------------------------------------------------------- Storage
  {
    id: 'mounts', area: 'storage', collect: { field: 'mounts', key: 'path' }, title: 'Mounts and shares',
    text: 'Disks, NFS and SMB shares, mounted at boot. SMB credentials come from the vault.',
    fields: [F.rows('mounts', 'Mounts', [
      F.text('path', 'Mount point', { pattern: 'path', required: true, placeholder: '/srv/data' }),
      F.select('type', 'Type', [['nfs', 'NFS'], ['cifs', 'SMB (CIFS)'], ['ext4', 'ext4'], ['xfs', 'XFS'], ['tmpfs', 'tmpfs'], ['none', 'Bind mount']]),
      F.text('source', 'Source', { pattern: 'any', placeholder: 'nas:/export/data, //nas/share or UUID=…' }),
      F.text('options', 'Options', { pattern: 'word', default: 'defaults', placeholder: 'defaults,_netdev' }),
      F.secret('credential', 'Login (SMB)', ['login'])
    ])],
    needs: v => v.mounts.filter(m => m.type === 'cifs' && m.credential).map(m => ({ type: 'secret', id: m.credential })),
    tasks: v => {
      const pk = [...new Set(v.mounts.map(m => ({ nfs: 'nfs-common', cifs: 'cifs-utils', xfs: 'xfsprogs' })[m.type]).filter(Boolean))];
      return {
        tasks: [
          ...(pk.length ? [T.apt(pk)] : []),
          ...v.mounts.flatMap(m => {
            const credFile = `/etc/fleetpilot/cifs-${slug(m.path)}.cred`;
            const opts = m.type === 'cifs' && m.credential ? `${m.options},credentials=${credFile}` : m.type === 'none' ? `bind,${m.options}` : m.options;
            return [
              ...(m.type === 'cifs' && m.credential ? [T.file('Make the folder for share logins', { path: '/etc/fleetpilot', state: 'directory', mode: '0700' }),
                T.copy(`Write the login for ${m.path}`, credFile, `username={{ fp_secret['${m.credential}'].username }}\npassword={{ fp_secret['${m.credential}'].password }}\n`, { mode: '0600', noLog: true })] : []),
              T.file(`Make the mount point ${m.path}`, { path: m.path, state: 'directory', mode: '0755' }),
              T.line(`Mount ${m.path} at boot`, { path: '/etc/fstab', regexp: `^\\S+\\s+${m.path.replace(/[.]/g, '\\.')}\\s`, line: `${m.source} ${m.path} ${m.type} ${opts} 0 ${['ext4', 'xfs'].includes(m.type) ? 2 : 0}` }),
              T.shell(`Mount ${m.path} now`, `findmnt -rn ${m.path} >/dev/null || mount ${m.path}`, { changed: false })
            ];
          })
        ]
      };
    },
    summary: v => v.mounts.map(m => m.path).join(', ') || 'None'
  },
  {
    id: 'logrotate', area: 'storage', collect: { field: 'rules', key: 'name' }, title: 'Log rotation',
    text: 'Rotates the logs of your own applications.',
    fields: [F.rows('rules', 'Rules', [
      F.text('name', 'Name', { pattern: 'name', required: true, placeholder: 'myapp' }), F.text('path', 'Files', { pattern: 'path', placeholder: '/var/log/myapp/*.log' }),
      F.select('every', 'Every', [['daily', 'Day'], ['weekly', 'Week'], ['monthly', 'Month']]), F.num('keep', 'Keep', 14, [1, 1000]), F.text('maxsize', 'Also when larger than', { pattern: 'duration', placeholder: '100M' })
    ])],
    tasks: v => ({ tasks: v.rules.map(r => T.copy(`Rotate the logs of ${r.name}`, `/etc/logrotate.d/fp-${r.name}`, conf([`${r.path} {`, `  ${r.every}`, `  rotate ${r.keep}`, r.maxsize ? `  maxsize ${r.maxsize}` : null, '  missingok', '  notifempty', '  compress', '  delaycompress', '  copytruncate', '}']))) }),
    summary: v => v.rules.map(r => r.name).join(', ') || 'None'
  },
  {
    id: 'lvm', area: 'storage', collect: { field: 'volumes', key: 'lv' }, title: 'Grow logical volumes',
    text: 'Grows LVM volumes and their filesystems into free space (never shrinks).',
    fields: [F.rows('volumes', 'Volumes', [F.text('lv', 'Volume', { pattern: 'path', required: true, placeholder: '/dev/vg0/root' }), F.text('size', 'To', { pattern: 'word', default: '+100%FREE', placeholder: '+100%FREE or 50G' })])],
    tasks: v => ({ tasks: v.volumes.map(x => T.shell(`Grow ${x.lv}`, `lvextend -r ${x.size.startsWith('+') && x.size.includes('%') ? `-l ${x.size}` : `-L ${x.size}`} ${x.lv} 2>&1 || true`, { changedWhen: "'successfully resized' in fp_out.stdout", register: 'fp_out' })) }),
    summary: v => v.volumes.map(x => `${x.lv} to ${x.size}`).join(', ') || 'None'
  },

  // ---------------------------------------------------------------- Security
  {
    id: 'firewall', area: 'security', single: true, title: 'Firewall',
    text: 'nftables: incoming connections only where allowed. Ports of the services in the desired state are opened by themselves, SSH always.',
    fields: [
      F.select('incoming', 'Incoming connections', [['drop', 'Only what is allowed'], ['accept', 'All (the firewall only logs)']]),
      F.lines('sshFrom', 'SSH from', { pattern: 'ipOrCidr', placeholder: 'Empty: from anywhere. 10.0.0.0/8' }),
      F.rows('allow', 'Also allow', [F.text('port', 'Port', { pattern: 'word', required: true, placeholder: '8080 or 8000-8100' }), F.select('proto', 'Protocol', [['tcp', 'TCP'], ['udp', 'UDP']]), F.text('from', 'From', { pattern: 'ipOrCidr', placeholder: 'any' })]),
      F.bool('ping', 'Answer ping', true),
      F.bool('forward', 'Let traffic pass through (routers, containers)', true)
    ],
    tasks: (v, ctx) => {
      // One rule per address family; "any" or nothing means from everywhere
      const rule = (from, match, comment) => {
        const list = [].concat(from || []).filter(f => f && f !== 'any');
        const v4 = list.filter(x => !x.includes(':')), v6 = list.filter(x => x.includes(':'));
        const srcs = list.length ? [v4.length && `ip saddr { ${v4.join(', ')} }`, v6.length && `ip6 saddr { ${v6.join(', ')} }`].filter(Boolean) : [''];
        return srcs.map(src => '    ' + [src, match, 'accept', comment ? `comment ${quote(comment)}` : ''].filter(Boolean).join(' '));
      };
      const sshPorts = [...new Set((ctx.ports || []).filter(p => p.ssh).map(p => p.port).concat(ctx.sshPort || 22))];
      const rules = [
        ...sshPorts.flatMap(p => rule(v.sshFrom, `tcp dport ${p}`, 'SSH')),
        ...(ctx.ports || []).filter(p => !p.ssh).flatMap(p => rule(p.from, p.raw || `${p.proto} dport ${p.port}`, p.label)),
        ...v.allow.flatMap(a => rule(a.from, `${a.proto} dport ${a.port}`))
      ];
      const text = conf([
        '# Only the table of FleetPilot: Docker and other tools keep their own',
        'table inet fleetpilot',
        'delete table inet fleetpilot',
        'table inet fleetpilot {',
        '  chain input {',
        `    type filter hook input priority filter; policy ${v.incoming};`,
        '    ct state established,related accept',
        '    ct state invalid drop',
        '    iif lo accept',
        ...(v.ping ? ['    meta l4proto icmp accept', '    meta l4proto ipv6-icmp accept'] : ['    meta l4proto ipv6-icmp icmpv6 type { nd-neighbor-solicit, nd-neighbor-advert, nd-router-advert } accept']),
        ...rules,
        v.incoming === 'accept' ? '    log prefix "fleetpilot-in " level info' : null,
        '  }',
        '  chain forward {',
        `    type filter hook forward priority filter; policy ${v.forward ? 'accept' : 'drop'};`,
        '  }',
        '}'
      ]);
      return {
        tasks: [
          T.apt(['nftables']),
          T.copy('Write the firewall rules', '/etc/nftables.conf', text.startsWith('#') ? `#!/usr/sbin/nft -f\n${text}` : text, { mode: '0755', validate: 'nft -c -f %s', notify: 'Load the firewall rules' }),
          T.service('nftables')
        ],
        handlers: { 'Load the firewall rules': T.cmd('Load the firewall rules', 'nft -f /etc/nftables.conf') }
      };
    },
    summary: v => `${v.incoming === 'drop' ? 'Only allowed connections' : 'All connections, logged'}${v.allow.length ? `, ${plural(v.allow.length, 'extra rule', 'extra rules')}` : ''}`
  },
  {
    id: 'fail2ban', area: 'security', single: true, title: 'Ban attackers (fail2ban)',
    text: 'Bans addresses that try too many wrong logins over SSH.',
    fields: [F.num('maxretry', 'Wrong logins', 5, [1, 100]), F.num('findtime', 'Within (minutes)', 10, [1, 1440]), F.num('bantime', 'Ban for (minutes)', 60, [1, 525600]), F.lines('ignore', 'Never ban', { pattern: 'ipOrCidr', placeholder: '10.0.0.0/8' })],
    tasks: v => ({
      tasks: [T.apt(['fail2ban', 'python3-systemd']),
        T.copy('Configure fail2ban', '/etc/fail2ban/jail.d/fleetpilot.local', conf(['[DEFAULT]', `bantime = ${v.bantime}m`, `findtime = ${v.findtime}m`, `maxretry = ${v.maxretry}`, `ignoreip = 127.0.0.1/8 ::1 ${v.ignore.join(' ')}`.trim(), 'banaction = nftables', '', '[sshd]', 'enabled = true', 'backend = systemd']), { notify: 'Restart fail2ban' }),
        T.service('fail2ban')],
      handlers: { 'Restart fail2ban': T.restart('fail2ban') }
    }),
    summary: v => `${v.maxretry} tries in ${v.findtime} min, ban for ${v.bantime} min`
  },
  {
    id: 'hardening', area: 'security', single: true, title: 'Hardening',
    text: 'Common hardening measures for the kernel and the system. Each one can be switched off.',
    fields: [
      F.bool('coredumps', 'No core dumps', true), F.bool('dmesg', 'Only root reads kernel messages', true), F.bool('kptr', 'Hide kernel addresses', true),
      F.bool('ptrace', 'Processes may only debug their own children', true), F.bool('redirects', 'Ignore ICMP redirects and source routes', true),
      F.bool('syncookies', 'SYN cookies against floods', true), F.bool('martians', 'Log impossible addresses', false), F.bool('rpfilter', 'Drop packets with spoofed sources', true),
      F.bool('filesystems', 'Block rare filesystems (cramfs, hfs, udf, …)', true), F.bool('usb', 'Block USB storage', false), F.bool('umask', 'New files private by default (umask 027)', false)
    ],
    tasks: v => ({
      tasks: [
        T.copy('Write the kernel hardening', '/etc/sysctl.d/92-fleetpilot-hardening.conf', conf([
          v.coredumps ? 'fs.suid_dumpable = 0\nkernel.core_pattern = |/bin/false' : null, v.dmesg ? 'kernel.dmesg_restrict = 1' : null, v.kptr ? 'kernel.kptr_restrict = 2' : null,
          v.ptrace ? 'kernel.yama.ptrace_scope = 1' : null,
          v.redirects ? 'net.ipv4.conf.all.accept_redirects = 0\nnet.ipv4.conf.default.accept_redirects = 0\nnet.ipv4.conf.all.send_redirects = 0\nnet.ipv4.conf.all.accept_source_route = 0\nnet.ipv6.conf.all.accept_redirects = 0\nnet.ipv6.conf.default.accept_redirects = 0' : null,
          v.syncookies ? 'net.ipv4.tcp_syncookies = 1' : null, v.martians ? 'net.ipv4.conf.all.log_martians = 1' : null, v.rpfilter ? 'net.ipv4.conf.all.rp_filter = 1\nnet.ipv4.conf.default.rp_filter = 1' : null
        ]), { notify: 'Apply kernel settings' }),
        T.copy('Limit core dumps', '/etc/security/limits.d/fleetpilot.conf', conf(v.coredumps ? ['* hard core 0'] : [])),
        T.file('Make the folder for module rules', { path: '/etc/modprobe.d', state: 'directory', mode: '0755' }),
        T.copy('Block rare filesystems and USB storage', '/etc/modprobe.d/fleetpilot-hardening.conf', conf([
          ...(v.filesystems ? ['cramfs', 'freevxfs', 'hfs', 'hfsplus', 'jffs2', 'udf'] : []).map(m => `install ${m} /bin/false`), v.usb ? 'install usb-storage /bin/false' : null])),
        T.line('Set the default umask', { path: '/etc/login.defs', regexp: '^UMASK\\s', line: `UMASK\t\t${v.umask ? '027' : '022'}` })
      ],
      handlers: H.sysctl
    }),
    summary: v => `${Object.values(v).filter(x => x === true).length} measures`
  },
  {
    id: 'apparmor', area: 'security', single: true, title: 'AppArmor',
    text: 'Confines programs to what their profiles allow.',
    fields: [F.bool('enabled', 'On', true), F.bool('extra', 'Install the extra profiles', false)],
    tasks: v => ({ tasks: v.enabled ? [T.apt(['apparmor', 'apparmor-utils', ...(v.extra ? ['apparmor-profiles', 'apparmor-profiles-extra'] : [])]), T.service('apparmor')] : [T.service('apparmor', { state: 'stopped', enabled: false, name: 'Switch AppArmor off' })] }),
    summary: v => v.enabled ? 'On' : 'Off'
  },
  {
    id: 'auditd', area: 'security', single: true, title: 'Auditing (auditd)',
    text: 'Records logins, changes to accounts, sudo and changes to system files.',
    fields: [F.bool('identity', 'Changes to users, groups and passwords', true), F.bool('sudoers', 'Changes to sudo rules', true), F.bool('sshd', 'Changes to the SSH configuration', true), F.bool('modules', 'Loading kernel modules', true), F.bool('time', 'Changes to the clock', true), F.area('custom', 'Own rules', { raw: true, placeholder: '-w /etc/myapp/ -p wa -k myapp' })],
    tasks: v => ({
      tasks: [T.apt(['auditd']),
        T.copy('Write the audit rules', '/etc/audit/rules.d/50-fleetpilot.rules', conf([
          v.identity ? '-w /etc/passwd -p wa -k identity\n-w /etc/group -p wa -k identity\n-w /etc/shadow -p wa -k identity\n-w /etc/gshadow -p wa -k identity' : null,
          v.sudoers ? '-w /etc/sudoers -p wa -k sudoers\n-w /etc/sudoers.d/ -p wa -k sudoers' : null, v.sshd ? '-w /etc/ssh/sshd_config -p wa -k sshd\n-w /etc/ssh/sshd_config.d/ -p wa -k sshd' : null,
          v.modules ? '-w /sbin/insmod -p x -k modules\n-w /sbin/modprobe -p x -k modules\n-a always,exit -F arch=b64 -S init_module,finit_module,delete_module -k modules' : null,
          v.time ? '-a always,exit -F arch=b64 -S adjtimex,settimeofday,clock_settime -k time\n-w /etc/localtime -p wa -k time' : null,
          ...String(v.custom || '').split('\n').filter(l => /^-[wa]\s/.test(l.trim())).map(l => l.trim())
        ]), { mode: '0640', notify: 'Load the audit rules' }), T.service('auditd')],
      handlers: { 'Load the audit rules': T.cmd('Load the audit rules', 'augenrules --load') }
    }),
    summary: v => `${['identity', 'sudoers', 'sshd', 'modules', 'time'].filter(k => v[k]).length} areas${v.custom ? ' and own rules' : ''}`
  },
  {
    id: 'tls', area: 'security', collect: { field: 'certs', key: 'name' }, title: 'TLS certificates',
    text: 'Certificates and their keys from the vault, written where services find them.',
    fields: [F.rows('certs', 'Certificates', [F.text('name', 'Name', { pattern: 'name', required: true, placeholder: 'www' }), F.secret('secret', 'Certificate in the vault', ['tls']), F.text('dir', 'Folder', { pattern: 'path', default: '/etc/ssl/fleetpilot' })])],
    needs: v => v.certs.filter(c => c.secret).map(c => ({ type: 'secret', id: c.secret })),
    tasks: v => ({
      tasks: v.certs.filter(c => c.secret).flatMap(c => [
        T.file(`Make the folder ${c.dir}`, { path: c.dir, state: 'directory', mode: '0755' }),
        T.copy(`Write the certificate ${c.name}`, `${c.dir}/${c.name}.crt`, `{{ fp_secret['${c.secret}'].certificate }}`, { mode: '0644' }),
        T.copy(`Write the key of ${c.name}`, `${c.dir}/${c.name}.key`, `{{ fp_secret['${c.secret}'].key }}`, { mode: '0600', noLog: true })
      ])
    }),
    summary: v => v.certs.map(c => c.name).join(', ') || 'None'
  },
  {
    id: 'cas', area: 'security', collect: { field: 'cas', key: 'name' }, title: 'Trusted certificate authorities',
    text: 'Your own certificate authorities, trusted by the whole system.',
    fields: [F.rows('cas', 'Authorities', [F.text('name', 'Name', { pattern: 'name', required: true, placeholder: 'company-root' }), F.area('pem', 'Certificate (PEM)', { raw: true, placeholder: '-----BEGIN CERTIFICATE-----' })])],
    tasks: v => ({
      tasks: [T.apt(['ca-certificates']), ...v.cas.filter(c => /^-----BEGIN CERTIFICATE-----[\s\S]+-----END CERTIFICATE-----\s*$/.test(c.pem.trim()))
        .map(c => T.copy(`Trust ${c.name}`, `/usr/local/share/ca-certificates/fp-${c.name}.crt`, c.pem.trim() + '\n', { notify: 'Update the trusted authorities' }))],
      handlers: { 'Update the trusted authorities': T.cmd('Update the trusted authorities', 'update-ca-certificates') }
    }),
    summary: v => v.cas.map(c => c.name).join(', ') || 'None'
  },

  // ---------------------------------------------------------------- Monitoring
  {
    id: 'snmp', area: 'monitoring', single: true, title: 'SNMP agent',
    text: 'snmpd for your monitoring system: SNMPv3 with a user and passwords from the vault, or a read-only v2c community.',
    fields: [
      F.select('version', 'Version', [['v3', 'SNMPv3 (encrypted)'], ['v2c', 'v2c (community, not encrypted)']]),
      F.text('user', 'v3 user', { pattern: 'name', default: 'monitor', when: { version: 'v3' } }),
      F.text('community', 'Community', { pattern: 'name', default: 'public', when: { version: 'v2c' } }),
      F.lines('from', 'Allowed from', { pattern: 'cidr', placeholder: '10.0.0.0/8' }),
      F.text('location', 'Location', { pattern: 'any', placeholder: 'Rack 4, Datacenter 1' }), F.text('contact', 'Contact', { pattern: 'any', placeholder: 'ops@example.com' })
    ],
    needs: v => v.version === 'v3' ? [{ type: 'shared', key: `snmp:${v.user}:auth`, label: `SNMP ${v.user} authentication` }, { type: 'shared', key: `snmp:${v.user}:priv`, label: `SNMP ${v.user} privacy` }] : [],
    tasks: v => ({
      tasks: [T.apt(['snmpd']),
        T.copy('Configure the SNMP agent', '/etc/snmp/snmpd.conf', conf([
          'agentAddress udp:161,udp6:[::1]:161', `sysLocation ${v.location || 'unknown'}`, `sysContact ${v.contact || 'unknown'}`,
          ...(v.version === 'v3' ? [`createUser ${v.user} SHA-256 "{{ fp_shared['snmp:${v.user}:auth'] }}" AES "{{ fp_shared['snmp:${v.user}:priv'] }}"`, `rouser ${v.user} priv`]
            : (v.from.length ? v.from : ['127.0.0.1/32']).map(n => `rocommunity ${v.community} ${n}`))
        ]), { mode: '0600', noLog: true, notify: 'Restart snmpd' }), T.service('snmpd')],
      handlers: { 'Restart snmpd': T.restart('snmpd') }
    }),
    ports: v => [{ port: 161, proto: 'udp', from: v.from, label: 'SNMP' }],
    summary: v => v.version === 'v3' ? `SNMPv3 user ${v.user}` : `v2c, community ${v.community}`
  },
  {
    id: 'syslog', area: 'monitoring', single: true, title: 'Log forwarding',
    text: 'Sends the logs to a central log server (rsyslog).',
    fields: [F.text('target', 'Log server', { pattern: 'host', required: true, placeholder: 'logs.example.com' }), F.num('port', 'Port', 514, [1, 65535]), F.select('proto', 'Protocol', [['udp', 'UDP'], ['tcp', 'TCP']]), F.select('level', 'From level', [['*', 'Everything'], ['info', 'Info'], ['notice', 'Notice'], ['warning', 'Warning'], ['err', 'Error']])],
    tasks: v => ({
      tasks: [T.apt(['rsyslog']), T.copy('Forward the logs', '/etc/rsyslog.d/90-fleetpilot-forward.conf', conf([`*.${v.level} action(type="omfwd" target=${quote(v.target)} port="${v.port}" protocol="${v.proto}" queue.type="LinkedList" queue.size="10000" action.resumeRetryCount="-1")`]), { notify: 'Restart rsyslog' }), T.service('rsyslog')],
      handlers: { 'Restart rsyslog': T.restart('rsyslog') }
    }),
    summary: v => `${v.target}:${v.port} (${v.proto})`
  },
