        return { name: `${j.state === 'absent' ? 'Remove' : 'Schedule'} "${j.name}"`, 'ansible.builtin.cron': { name: `FleetPilot: ${j.name}`, user: j.user, job: j.command, state: j.state, ...(special ? { special_time: special } : { minute, hour, day, month, weekday }) } };
      })
    }),
